INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(3451, 101, 'In computing, what do the letters AI stand for?', 'Artificial Intelligence', 'Automated Input', 'Advanced Internet', 'Algorithmic Interface', 'A', 'AI is the standard acronym for Artificial Intelligence, the study of machines that perform tasks that typically require human intelligence.', 'BEGINNER', 1, 'MCQ', 1),
(3452, 101, 'Which discipline is the parent field of artificial intelligence?', 'Mechanical Engineering', 'Computer Science', 'Biology', 'Astronomy', 'B', 'AI is a subfield of computer science, although it draws ideas from psychology, linguistics and mathematics.', 'BEGINNER', 1, 'MCQ', 1),
(3453, 101, 'Which option best describes an intelligent agent?', 'a database for storing sensor logs', 'a web browser extension', 'an entity that perceives its environment and acts to achieve goals', 'a compiler optimization pass', 'C', 'An intelligent agent perceives its environment through sensors and acts on it through actuators to pursue its goals.', 'BEGINNER', 1, 'MCQ', 1),
(3454, 101, 'In the agent-environment loop, what does the agent send back to the environment?', 'percepts', 'raw sensor data', 'goal statements', 'actions', 'D', 'The agent acts on the environment by performing actions produced by its actuators.', 'BEGINNER', 1, 'MCQ', 1),
(3455, 101, 'What is a percept in agent terminology?', 'the input an agent receives from its sensors at an instant', 'the agent''s internal state', 'the agent''s reward signal', 'the agent''s action history', 'A', 'A percept is the current sensor reading that the agent uses to decide its next action.', 'BEGINNER', 1, 'MCQ', 1),
(3456, 101, 'Which of the following is an example of an intelligent agent?', 'a pocket calculator', 'a self-driving car''s control system', 'a text file', 'a keyboard', 'B', 'A self-driving car senses the road and acts on it, satisfying the definition of an intelligent agent.', 'BEGINNER', 1, 'MCQ', 1),
(3457, 101, 'What is the role of sensors in an agent?', 'to perform actions', 'to compute rewards', 'to gather information about the environment', 'to communicate with humans', 'C', 'Sensors let the agent perceive the state of its environment so it can choose appropriate actions.', 'BEGINNER', 1, 'MCQ', 1),
(3458, 101, 'A thermostat that turns heating on or off based on temperature readings is best described as:', 'a utility-based agent', 'a goal-based agent', 'an uncertain agent', 'a simple reflex agent', 'D', 'A thermostat maps its current temperature percept directly to an action, the hallmark of a simple reflex agent.', 'BEGINNER', 1, 'MCQ', 1),
(3459, 101, 'What is the central goal of artificial intelligence?', 'building systems that perform tasks that typically require human intelligence', 'replacing all human jobs', 'increasing database sizes', 'removing errors from code', 'A', 'AI seeks to build systems that carry out tasks that normally require human intelligence, such as perception and reasoning.', 'BEGINNER', 1, 'MCQ', 1),
(3460, 101, 'Which of the following is a typical example of an AI application?', 'a hardware firewall', 'a spelling and grammar assistant that suggests corrections', 'a file compressor', 'a BIOS', 'B', 'A spelling and grammar assistant performs a language task normally done by humans, a classic AI application.', 'BEGINNER', 1, 'MCQ', 1),
(3461, 101, 'A robot vacuum explores a room and maps obstacles while cleaning. Which agent capability is being demonstrated?', 'complete self-awareness', 'perception and planning', 'wireless charging', 'cloud storage', 'B', 'The robot perceives obstacles with its sensors and plans a cleaning route, combining perception and planning.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3462, 101, 'An agent keeps a model of the world and chooses actions that lead to a goal state. What type of agent is this?', 'a simple reflex agent', 'a random agent', 'a goal-based agent', 'a passive database', 'C', 'A goal-based agent maintains a model of the world and searches for actions that reach a desired goal state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3463, 101, 'A temperature-sensing agent decides actions using the single rule ''if temperature > 25 then turn on fan''. What kind of behaviour does this show?', 'learning from experience', 'probabilistic inference', 'deep reasoning', 'reflex (condition-action) behaviour', 'D', 'The agent uses a fixed condition-action rule, so it behaves as a reflex agent rather than reasoning or learning.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3464, 101, 'Which pair correctly matches a sensing task with its typical sensor?', 'obstacle detection - lidar', 'text colour - keyboard', 'sound level - camera', 'air pressure - microphone', 'A', 'Lidar measures distances and is a standard sensor for obstacle detection in robotic agents.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3465, 101, 'A chatbot that answers questions by retrieving pre-written answers without remembering past turns is best described as:', 'a learning agent', 'a memoryless (stateless) reactive agent', 'a deep Q-network', 'a planning agent', 'B', 'Because it keeps no memory of previous turns, the chatbot is a stateless reactive agent.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3466, 101, 'An agent''s utility function measures what?', 'how fast the processor runs', 'the size of its memory', 'how good a given state is for the agent', 'the number of sensors', 'C', 'A utility function assigns a numeric score to states so the agent can compare how desirable they are.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3467, 101, 'If an agent acts, observes the result, and adjusts its future behaviour to maximise rewards, which property is it displaying?', 'hard-coding', 'actuation', 'immutability', 'learning', 'D', 'Improving behaviour based on the outcomes of past actions is exactly what it means for an agent to learn.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3468, 101, 'A chess-playing program that only reacts to the current board with a precomputed move table would be classified as:', 'a table-driven reflex agent', 'a fully rational planner', 'an unsupervised learner', 'a conversational agent', 'A', 'Using a lookup of condition-action pairs indexed by the current percept is the table-driven reflex design.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3469, 101, 'Which of the following best matches the idea of a rational agent?', 'one that always does nothing', 'one that chooses actions expected to maximise its performance measure', 'one that acts randomly', 'one that follows only stored patterns', 'B', 'Rationality means selecting the action expected to best achieve the agent''s performance measure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3470, 101, 'An agent with four sensors that each report one bit has how many distinct percepts at any instant?', '4', '16', '2', '8', 'C', 'Four binary sensors combine to give 2 raised to the power 4, which is 16 distinct percept combinations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3471, 101, 'An e-commerce recommendation agent that adapts its suggestions based on past purchases is an example of:', 'a purely reflexive agent', 'a static lookup table', 'a learning agent that improves from experience', 'a model-free firewall', 'C', 'The agent changes its behaviour using past interactions, which is the defining trait of a learning agent.', 'ADVANCED', 3, 'MCQ', 1),
(3472, 101, 'Why is the PEAS description useful when designing an agent?', 'it defines the programming language', 'it forces the designer to describe Performance measure, Environment, Actuators and Sensors', 'it removes the need for sensors', 'it guarantees optimal behaviour', 'D', 'PEAS stands for Performance, Environment, Actuators and Sensors, the four aspects that fully specify an agent''s task.', 'ADVANCED', 3, 'MCQ', 1),
(3473, 101, 'For a fully observable, deterministic environment, which agent design is usually the simplest that works?', 'a reflex agent with a condition-action rule for each percept', 'a multi-agent simulator', 'an evolutionary population', 'a reinforcement learner', 'A', 'When each percept fully determines the correct action, a simple condition-action reflex agent suffices.', 'ADVANCED', 3, 'MCQ', 1),
(3474, 101, 'A delivery robot must decide routes, avoid pedestrians and recharge itself. Which set of design decisions best addresses this?', 'ignore pedestrians to save time', 'model the world, plan routes, and combine goals with a utility function', 'use only a fixed lookup table', 'delete the recharge rule', 'B', 'Conflicting goals such as speed, safety and battery life are best balanced with a model-based planner and a utility function.', 'ADVANCED', 3, 'MCQ', 1),
(3475, 101, 'A system tracks a user''s health data and alerts a doctor if risk rises. Which concern is most critical for this agent?', 'the font of the alerts', 'the agent''s learning rate', 'trustworthiness and safety of its recommendations', 'the number of buttons on the screen', 'C', 'A health-alerting agent must be safe and trustworthy because an incorrect recommendation can harm the user.', 'ADVANCED', 3, 'MCQ', 1),
(3476, 101, 'Why does a rational agent need a performance measure?', 'to decide when to turn off', 'to debug its sensors', 'to choose its sensors', 'to evaluate how well different actions achieve success', 'D', 'A performance measure lets the agent compare the outcomes of candidate actions and pick the best one.', 'ADVANCED', 3, 'MCQ', 1),
(3477, 101, 'A stock-trading agent trades millions of times per day and learns from each outcome. Which architecture best supports continuous improvement?', 'a learning agent with a critic that updates a performance element', 'a fixed reflex rule base', 'a static database', 'a random number generator', 'A', 'A learning agent uses a critic to evaluate outcomes and updates its performance element accordingly.', 'ADVANCED', 3, 'MCQ', 1),
(3478, 101, 'Which statement about the environment in PEAS is correct?', 'it describes only the agent''s brain', 'it is the context in which the agent operates and which the agent senses and affects', 'it is the set of actuators', 'it is the reward function', 'B', 'The environment is everything outside the agent that the agent perceives and acts upon.', 'ADVANCED', 3, 'MCQ', 1),
(3479, 101, 'An agent that operates in an environment where it has incomplete information must be able to:', 'always act optimally without sensing', 'maintain a belief or model and reason under uncertainty', 'ignore new percepts', 'rely on a single fixed rule', 'C', 'Under partial observability the agent must keep beliefs about the hidden state and reason under uncertainty.', 'ADVANCED', 3, 'MCQ', 1),
(3480, 101, 'When two intelligent agents cooperate to lift a heavy object, which branch of AI focuses on such interaction?', 'knowledge representation alone', 'computer vision', 'natural language generation', 'multi-agent systems', 'D', 'Multi-agent systems study how multiple agents interact, cooperate and compete to solve shared problems.', 'ADVANCED', 3, 'MCQ', 1),
(3481, 102, 'What does BFS stand for?', 'Breadth-First Search', 'Binary File System', 'Best-First Search', 'Backward-Facing Search', 'A', 'BFS stands for Breadth-First Search, which explores a graph level by level.', 'BEGINNER', 1, 'MCQ', 1),
(3482, 102, 'Which data structure is used by Breadth-First Search to manage frontier nodes?', 'a stack', 'a queue', 'a heap', 'a linked hash map', 'B', 'BFS uses a queue so that nodes are expanded in first-in, first-out order.', 'BEGINNER', 1, 'MCQ', 1),
(3483, 102, 'What is the goal of an uninformed (blind) search algorithm?', 'to use domain knowledge to prune nodes', 'to find a solution path without using domain-specific heuristics', 'to prove a theorem', 'to train a classifier', 'C', 'Uninformed search finds solutions using only the problem definition, with no heuristic guidance.', 'BEGINNER', 1, 'MCQ', 1),
(3484, 102, 'Which data structure does Depth-First Search rely on?', 'a queue', 'a min-heap', 'a priority queue', 'a stack', 'D', 'DFS uses a stack so it always explores the most recently discovered node first.', 'BEGINNER', 1, 'MCQ', 1),
(3485, 102, 'What does a heuristic function h(n) estimate in informed search?', 'the cost from node n to the goal', 'the number of goals in the map', 'the memory used by the frontier', 'the depth of the tree', 'A', 'A heuristic h(n) estimates the remaining cost from node n to the goal state.', 'BEGINNER', 1, 'MCQ', 1),
(3486, 102, 'What is the key idea behind Greedy Best-First Search?', 'expanding nodes with the largest g-cost', 'always expanding the node with the smallest h(n) value', 'expanding nodes in random order', 'expanding the deepest node first', 'B', 'Greedy Best-First Search always expands the node whose heuristic h(n) is smallest.', 'BEGINNER', 1, 'MCQ', 1),
(3487, 102, 'What property ensures an admissible heuristic never overestimates?', 'it is always equal to zero', 'it returns the exact cost', 'it never overestimates the true cost to reach the goal', 'it ignores the goal', 'C', 'Admissibility requires h(n) to never exceed the true cost from n to the goal.', 'BEGINNER', 1, 'MCQ', 1),
(3488, 102, 'In tree search, what is the branching factor b?', 'the depth of the goal', 'the number of goals', 'the number of solutions', 'the maximum number of successors of any node', 'D', 'The branching factor b is the maximum number of successors a node can generate.', 'BEGINNER', 1, 'MCQ', 1),
(3489, 102, 'What is the time complexity of BFS on a graph with branching factor b and solution depth d?', 'O(b^d)', 'O(d)', 'O(b*d)', 'O(log d)', 'A', 'BFS expands O(b^d) nodes because the tree grows by a factor of b per level up to depth d.', 'BEGINNER', 1, 'MCQ', 1),
(3490, 102, 'What is the key difference between tree search and graph search?', 'tree search is always faster', 'graph search keeps track of visited states to avoid revisiting them', 'graph search uses heuristics', 'tree search stores all nodes in a stack', 'B', 'Graph search maintains a closed set of visited states so it never expands the same state twice.', 'BEGINNER', 1, 'MCQ', 1),
(3491, 102, 'Consider the tree where A has children B and C, and B has child D. In what order does BFS first expand the nodes?', 'A, D, B, C', 'A, B, C, D', 'A, C, B, D', 'D, B, C, A', 'B', 'BFS expands level by level: first A, then its children B and C, then the next level containing D.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3492, 102, 'A binary tree has a goal at the deepest level. Which order does DFS expand nodes?', 'level by level', 'in a single path all the way down before backtracking', 'in decreasing g-cost order', 'randomly', 'C', 'DFS follows one branch as deep as possible before backtracking to explore sibling branches.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3493, 102, 'For an admissible heuristic in A*, why is optimality guaranteed?', 'it reduces the branching factor to one', 'it guarantees the goal is always at depth one', 'it always expands the deepest node first', 'it guarantees the first goal node popped from the frontier is optimal', 'D', 'Because an admissible heuristic never overestimates, the first goal popped by A* has the optimal path cost.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3494, 102, 'In A*, the evaluation function f(n) = g(n) + h(n). What does g(n) represent?', 'the actual cost of the path from the start to node n', 'the heuristic estimate to the goal', 'the depth of the tree', 'the number of visited states', 'A', 'g(n) is the known cost of the best path found so far from the start node to n.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3495, 102, 'Start node S has h = 10 and g = 0. Its child T has h = 5 and g = 4. What is f(T) in A*?', '15', '9', '10', '4', 'B', 'f(T) is g(T) + h(T), which is 4 + 5 = 9.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3496, 102, 'A search that expands nodes in order of their path cost g(n) rather than depth is called:', 'Breadth-First Search', 'Depth-First Search', 'Uniform-Cost Search', 'Greedy Best-First Search', 'C', 'Uniform-Cost Search expands the node with the smallest g(n), making it optimal for weighted graphs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3497, 102, 'In DFS on a very deep or infinite tree, what is the main risk?', 'running out of memory in the queue', 'not finding the shallowest goal first', 'wasting time storing every visited node', 'getting stuck going down an unbounded path without finding the goal', 'D', 'DFS can descend an infinitely deep branch forever, so it is not complete on infinite state spaces.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3498, 102, 'In A*, node P has f = 8, node Q has f = 10 and node R has f = 9. Which node is expanded next?', 'P', 'Q', 'R', 'all at once', 'A', 'A* always expands the frontier node with the smallest f value, so P is chosen next.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3499, 102, 'For finding the SHORTEST path in an unweighted graph, which algorithm is guaranteed to work?', 'Depth-First Search', 'Breadth-First Search', 'Greedy Best-First Search with any heuristic', 'Random Search', 'B', 'BFS expands level by level, so the first goal it reaches in an unweighted graph is via a shortest path.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3500, 102, 'A heuristic h is consistent if it satisfies which inequality for every node n and its successor n''?', 'h(n) = g(n)', 'h(n) >= c(n,n'')', 'h(n) <= c(n,n'') + h(n'')', 'h(n) = c(n,n'') * h(n'')', 'C', 'Consistency requires that the drop in h along an edge never exceeds the edge cost, so h(n) <= c(n,n'') + h(n'').', 'INTERMEDIATE', 2, 'MCQ', 1),
(3501, 102, 'An 8-puzzle heuristic counts misplaced tiles. This heuristic is admissible because:', 'it overestimates the true cost', 'it ignores the start state', 'each misplaced tile must move at least once, so it never overestimates the true moves', 'it returns the optimal solution directly', 'C', 'Every misplaced tile needs at least one move, so the count never exceeds the true number of moves required.', 'ADVANCED', 3, 'MCQ', 1),
(3502, 102, 'For the 8-puzzle, the Manhattan distance heuristic is preferred over misplaced-tiles because:', 'it is easier to compute', 'it is inadmissible', 'it is faster', 'it is more informed and never overestimates, so A* expands fewer nodes', 'D', 'Manhattan distance sums the grid moves for each tile, giving a tighter admissible estimate that prunes more of the search.', 'ADVANCED', 3, 'MCQ', 1),
(3503, 102, 'In a large map with a high branching factor, A* may exhaust memory. Which technique addresses this?', 'Iterative-Deepening A* (IDA*)', 'increasing the branching factor', 'switching to random sampling', 'removing the heuristic', 'A', 'IDA* repeats depth-limited searches with increasing f-cost limits, using only linear memory.', 'ADVANCED', 3, 'MCQ', 1),
(3504, 102, 'Why is BFS inappropriate for a graph with billions of nodes and an unknown deep goal?', 'it never terminates', 'it requires a heuristic', 'its frontier grows exponentially with depth, consuming huge memory', 'it only works on trees', 'C', 'BFS stores every node at the current depth, and that frontier grows exponentially as depth increases.', 'ADVANCED', 3, 'MCQ', 1),
(3505, 102, 'With a consistent heuristic, how many times does A* graph search expand each state?', 'an infinite number of times', 'zero times', 'once', 'exactly twice', 'C', 'Consistency ensures a state is reached optimally the first time, so it is expanded at most once.', 'ADVANCED', 3, 'MCQ', 1),
(3506, 102, 'Which search strategy combines the low memory of DFS with the optimality of BFS for shortest paths in unweighted graphs?', 'Greedy Best-First', 'Uniform-Cost with a heap', 'Bidirectional search', 'Iterative Deepening DFS (IDDFS)', 'D', 'IDDFS repeatedly runs depth-limited DFS with increasing limits, giving BFS-like optimality with linear memory.', 'ADVANCED', 3, 'MCQ', 1),
(3507, 102, 'A navigation app that must return the fastest route in real time would most likely use:', 'A* with an admissible heuristic like travel-time estimates', 'pure DFS', 'pure BFS on the whole map', 'a random walk', 'A', 'A* guided by a travel-time heuristic focuses the search on promising routes, making it fast in practice.', 'ADVANCED', 3, 'MCQ', 1),
(3508, 102, 'You have an admissible but very weak heuristic that is often zero. What happens to A*?', 'it becomes greedy', 'it degrades toward Dijkstra''s algorithm, expanding many more nodes', 'it crashes', 'it becomes inadmissible', 'B', 'When h is close to zero, f is dominated by g, so A* behaves like Dijkstra and expands many nodes.', 'ADVANCED', 3, 'MCQ', 1),
(3509, 102, 'If a heuristic is admissible but inconsistent, a standard A* graph search may:', 'find an optimal solution faster', 'use less memory', 're-open already-closed nodes and potentially lose optimality', 'terminate immediately', 'C', 'An inconsistent heuristic can cause nodes in the closed set to need re-expansion, so the graph search must re-open them to stay optimal.', 'ADVANCED', 3, 'MCQ', 1),
(3510, 102, 'In an enormous state space where exhaustive search is impossible, which approach is often taken?', 'always using exhaustive DFS', 'avoiding any search', 'restricting to depth 1', 'using heuristic approximations such as hill climbing that sacrifice completeness for speed', 'D', 'Hill climbing and other local search trade completeness and optimality for tractability in huge spaces.', 'ADVANCED', 3, 'MCQ', 1),
(3511, 103, 'What is knowledge representation in AI?', 'the encoding of information about the world so a program can reason with it', 'the storage of photos on a disk', 'the layout of a web page', 'the speed of a processor', 'A', 'Knowledge representation is the way facts about the world are encoded so that a program can use them for reasoning.', 'BEGINNER', 1, 'MCQ', 1),
(3512, 103, 'Which of the following is a fact expressed in propositional logic?', 'Open the window', 'It is raining', 'Please stop', 'Do it now', 'B', 'A proposition is a declarative sentence that is either true or false, such as ''It is raining''.', 'BEGINNER', 1, 'MCQ', 1),
(3513, 103, 'Which symbol represents logical AND in propositional logic?', 'OR', 'NOT', 'AND (conjunction)', 'IMPLIES', 'C', 'The conjunction operator AND is true only when both of its operands are true.', 'BEGINNER', 1, 'MCQ', 1),
(3514, 103, 'What does a knowledge base contain?', 'the hardware devices', 'a collection of sentences that represent known facts', 'the compiled program', 'the user password', 'D', 'A knowledge base stores a set of sentences that represent what the system believes about the world.', 'BEGINNER', 1, 'MCQ', 1),
(3515, 103, 'In logic, what does entailment (KB |= sentence) mean?', 'the knowledge base logically implies the sentence', 'the sentence is false', 'the sentence contradicts the KB', 'the sentence is random', 'A', 'Entailment means that every model in which the knowledge base is true also makes the sentence true.', 'BEGINNER', 1, 'MCQ', 1),
(3516, 103, 'Which representation is a simple graph-based structure of nodes connected by edges?', 'a stack', 'a semantic network', 'a register file', 'a priority queue', 'B', 'A semantic network represents concepts as nodes and their relationships as labelled edges.', 'BEGINNER', 1, 'MCQ', 1),
(3517, 103, 'What is an ontology in knowledge representation?', 'a formal specification of concepts and relationships in a domain', 'a programming language', 'a data compression tool', 'a type of neural network', 'C', 'An ontology formally defines the concepts, properties and relations that exist in a particular domain.', 'BEGINNER', 1, 'MCQ', 1),
(3518, 103, 'Which of the following is a common knowledge representation scheme?', 'a keyboard', 'a CPU cache', 'a router', 'semantic networks', 'D', 'Semantic networks, frames, rules and logic are all widely used knowledge representation schemes.', 'BEGINNER', 1, 'MCQ', 1),
(3519, 103, 'What does a rule ''IF X THEN Y'' express?', 'a conditional relationship: if X holds, then Y follows', 'that Y is always false', 'that X is a number', 'that Y happened before X', 'A', 'A production rule states that when the premise X is true, the conclusion Y can be derived.', 'BEGINNER', 1, 'MCQ', 1),
(3520, 103, 'Which logic extends propositional logic with variables and quantifiers?', 'propositional logic', 'first-order logic', 'boolean algebra', 'fuzzy sets', 'B', 'First-order logic adds objects, variables, functions and the quantifiers forall and exists.', 'BEGINNER', 1, 'MCQ', 1),
(3521, 103, 'Which of these is a well-formed first-order logic sentence?', 'Tall(y) and Short', 'forall x Student(x) implies Likes(x, Coffee)', 'Student', 'forall', 'C', 'A well-formed first-order sentence combines a quantifier, a variable, and predicates such as Student(x) and Likes(x, Coffee).', 'INTERMEDIATE', 2, 'MCQ', 1),
(3522, 103, 'A knowledge base contains ''Cat(Fluffy)''. To conclude ''Mammal(Fluffy)'' you need:', 'a negation', 'a rule such as forall x Cat(x) implies Mammal(x)', 'a random number', 'a question mark', 'B', 'A general rule that every cat is a mammal lets inference derive the new fact Mammal(Fluffy).', 'INTERMEDIATE', 2, 'MCQ', 1),
(3523, 103, 'Which of the following is a sound inference rule?', 'guessing', 'flipping a coin', 'ignoring the premises', 'modus ponens', 'D', 'Modus ponens, from P and P implies Q we derive Q, always preserves truth and is therefore sound.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3524, 103, 'What is the difference between soundness and completeness of an inference algorithm?', 'soundness means it derives only true conclusions; completeness means it can derive every entailed sentence', 'they are the same thing', 'soundness concerns speed', 'completeness concerns memory', 'A', 'A sound algorithm never derives false conclusions, while a complete algorithm derives every sentence entailed by the knowledge base.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3525, 103, 'In a semantic network, what do the links typically represent?', 'relationships between concepts', 'electrical wires', 'menu items', 'binary numbers', 'B', 'Edges in a semantic network label relationships such as ''is-a'' or ''has-part'' between concepts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3526, 103, 'A decision tree represents knowledge as:', 'a single equation', 'a linked list of characters', 'a series of attribute tests leading to decisions', 'a queue of actions', 'C', 'A decision tree routes a case through attribute tests until a leaf gives the decision.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3527, 103, 'The AND-OR graph is a representation used for:', 'training neural networks', 'compressing images', 'sorting arrays', 'expressing decomposable problems where subgoals combine', 'D', 'In an AND-OR graph, AND nodes require all subgoals while OR nodes require at least one, supporting problem decomposition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3528, 103, 'A frame in frame-based representation contains:', 'slots with values describing an object', 'random tokens', 'a compiled binary', 'a list of colours', 'A', 'A frame is a record-like structure whose slots hold attributes and values describing an object or class.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3529, 103, 'Which representation is best suited for representing imprecise terms like ''tall'' or ''hot''?', 'propositional logic', 'fuzzy logic', 'first-order logic', 'bitmaps', 'B', 'Fuzzy logic allows degrees of membership so that imprecise terms like ''tall'' can be represented continuously.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3530, 103, 'In first-order logic, what does the existential quantifier exist x mean?', 'for all x', 'for no x', 'there exists an x such that', 'x is false', 'C', 'The existential quantifier states that there is at least one object x satisfying the formula.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3531, 103, 'A knowledge base has many rules and you want a reasoning method guaranteed not to make false conclusions. Which property matters most?', 'completeness alone', 'speed alone', 'soundness', 'memory usage', 'C', 'Soundness guarantees that every derived conclusion is a logical consequence of the knowledge base.', 'ADVANCED', 3, 'MCQ', 1),
(3532, 103, 'Why is forward chaining well-suited to rule-based systems?', 'it works backwards from the goal', 'it never uses rules', 'it requires no facts', 'it starts from known facts and applies rules to derive new facts', 'D', 'Forward chaining begins with known facts and fires rules to generate new facts, matching how data-driven systems work.', 'ADVANCED', 3, 'MCQ', 1),
(3533, 103, 'A diagnostic expert system that starts with a hypothesis and searches rules backward for supporting evidence uses:', 'backward chaining', 'forward chaining', 'random sampling', 'genetic algorithms', 'A', 'Backward chaining works from a goal backwards through rules to find the facts that would prove it.', 'ADVANCED', 3, 'MCQ', 1),
(3534, 103, 'Your representation must reason with certainty levels because sensor data is noisy. Which approach is appropriate?', 'pure propositional logic', 'probabilistic reasoning such as Bayesian networks', 'deterministic grammars', 'fixed lookup tables', 'B', 'Bayesian networks model uncertain dependencies between variables and support probabilistic inference.', 'ADVANCED', 3, 'MCQ', 1),
(3535, 103, 'In a semantic network, the ''is-a'' link mainly expresses:', 'a temporal relation', 'a part-whole physical relation', 'a class-inclusion relation (generalization)', 'a numerical order', 'C', 'The is-a link states that an individual belongs to a class, supporting inheritance of properties.', 'ADVANCED', 3, 'MCQ', 1),
(3536, 103, 'A description-logic-based ontology such as OWL is most useful when you need:', 'bit-level arithmetic', 'a faster sort', 'a way to draw graphs', 'automatic classification and shared semantics of a domain', 'D', 'Description logics support automated classification and give the domain a shared, machine-readable meaning.', 'ADVANCED', 3, 'MCQ', 1),
(3537, 103, 'The frame problem in AI refers to:', 'the difficulty of representing what stays UNCHANGED when an action occurs', 'the problem of opening windows', 'a memory leak in recursion', 'the frame rate of a video', 'A', 'The frame problem is the challenge of efficiently representing the many things that do not change after an action.', 'ADVANCED', 3, 'MCQ', 1),
(3538, 103, 'Which reasoning approach lets an expert system derive conclusions even when the exact truth of premises is uncertain?', 'modus tollens only', 'probabilistic or fuzzy inference with degrees of belief', 'binary logic', 'exhaustive enumeration', 'B', 'Probabilistic and fuzzy inference propagate degrees of belief so conclusions can be drawn from uncertain premises.', 'ADVANCED', 3, 'MCQ', 1),
(3539, 103, 'A rule base contains ''Bird(Tweety)'', ''NotFlies(Tweety)'' and a default that birds fly. The need to prefer one conclusion over another is handled by:', 'syntax errors', 'compiling faster', 'default logic or non-monotonic reasoning', 'larger memory', 'C', 'Default logic lets a conclusion be retracted when new information contradicts it, which is non-monotonic reasoning.', 'ADVANCED', 3, 'MCQ', 1),
(3540, 103, 'The main advantage of declarative knowledge over a hard-coded program is that:', 'it runs faster', 'it requires no facts', 'it is easier to update and reason about independently of the program logic', 'it removes the need for inference', 'D', 'Declarative knowledge separates facts from the inference engine, so knowledge can be added or changed without rewriting code.', 'ADVANCED', 3, 'MCQ', 1),
(3541, 104, 'What is machine learning primarily about?', 'building systems that learn patterns from data and improve with experience', 'writing fixed rules by hand', 'building faster CPUs', 'managing databases', 'A', 'Machine learning builds models that infer patterns from data and improve as they see more examples.', 'BEGINNER', 1, 'MCQ', 1),
(3542, 104, 'Which type of learning uses labelled data (input-output pairs)?', 'unsupervised learning', 'supervised learning', 'reinforcement learning only', 'genetic programming', 'B', 'Supervised learning trains on examples that include both input features and known correct outputs.', 'BEGINNER', 1, 'MCQ', 1),
(3543, 104, 'In supervised learning, what is the label?', 'the input feature', 'the known correct output for a training example', 'the weight of a neuron', 'the learning rate', 'C', 'A label is the known correct answer paired with an input in a labelled training dataset.', 'BEGINNER', 1, 'MCQ', 1),
(3544, 104, 'Which learning type groups data without any labels?', 'supervised learning', 'semi-supervised learning', 'reinforcement learning', 'unsupervised learning (clustering)', 'D', 'Unsupervised learning finds structure in unlabelled data, and clustering is its most common form.', 'BEGINNER', 1, 'MCQ', 1),
(3545, 104, 'What is a training set?', 'the data used to teach the model', 'the final deployment logs', 'the test for the user', 'the weight matrix', 'A', 'The training set is the portion of data the model learns from during training.', 'BEGINNER', 1, 'MCQ', 1),
(3546, 104, 'What is the role of the test set?', 'to train the model', 'to evaluate how well the trained model generalizes to unseen data', 'to store backups', 'to label data', 'B', 'The test set measures performance on data the model never saw during training.', 'BEGINNER', 1, 'MCQ', 1),
(3547, 104, 'Which of these is a classification task?', 'predicting a house price', 'predicting whether an email is spam or not', 'grouping customers by similarity', 'finding frequent items', 'C', 'Predicting a discrete category such as spam or not spam is a classification task.', 'BEGINNER', 1, 'MCQ', 1),
(3548, 104, 'Which of these is a regression task?', 'classifying images', 'detecting fraud with categories', 'predicting tomorrow''s temperature as a number', 'clustering news', 'D', 'Regression predicts a continuous numeric value, such as a temperature reading.', 'BEGINNER', 1, 'MCQ', 1),
(3549, 104, 'What is overfitting?', 'the model memorizes the training data and fails on new data', 'the model learns nothing', 'the model trains too quickly', 'the dataset is too large', 'A', 'Overfitting means the model fits the training data too closely and does not generalize to new data.', 'BEGINNER', 1, 'MCQ', 1),
(3550, 104, 'What is feature engineering?', 'selecting or creating input variables that help a model learn patterns', 'deleting the training data', 'increasing the learning rate', 'hardcoding model predictions', 'A', 'Feature engineering transforms raw data into informative inputs, giving the model the attributes it needs to learn patterns.', 'BEGINNER', 1, 'MCQ', 1),
(3551, 104, 'A dataset has 1000 labelled emails and you train a model that assigns each to spam or not spam. This is an example of:', 'regression', 'binary classification', 'clustering', 'dimensionality reduction', 'B', 'Assigning each email to one of two discrete classes is binary classification.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3552, 104, 'In k-nearest neighbours, which parameter controls how many neighbours vote on the prediction?', 'the learning rate', 'the epoch count', 'the value of k', 'the batch size', 'C', 'The parameter k sets how many of the closest training examples vote on a new prediction.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3553, 104, 'A model gets 99% accuracy on training data but only 60% on test data. The most likely problem is:', 'underfitting', 'missing test data', 'too few epochs', 'overfitting', 'D', 'The large gap between training and test accuracy is the classic signature of overfitting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3554, 104, 'For a regression problem, which metric measures the average squared prediction error?', 'mean squared error (MSE)', 'accuracy', 'precision', 'recall', 'A', 'MSE averages the squared differences between predicted and actual values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3555, 104, 'For classification, the fraction of correct predictions out of all predictions is called:', 'loss', 'accuracy', 'variance', 'bias', 'B', 'Accuracy is the proportion of predictions the model got right.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3556, 104, 'In gradient descent, what does the learning rate control?', 'the number of features', 'the size of each update step to the model''s parameters', 'the size of the dataset', 'the number of neighbours', 'C', 'The learning rate scales how much the parameters move in each gradient step.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3557, 104, 'A clustering algorithm assigns each point to the nearest of k centroids. Which algorithm is this?', 'linear regression', 'decision tree', 'logistic regression', 'k-means', 'D', 'K-means iteratively assigns points to the nearest centroid and recomputes the centroids.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3558, 104, 'In reinforcement learning, what does the agent receive after each action?', 'a reward signal', 'a labelled example', 'a validation set', 'a gradient', 'A', 'The environment returns a reward that tells the agent how good the action was.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3559, 104, 'A model with high variance most likely has what property?', 'it is too simple', 'it fits training data too closely and changes a lot with new data', 'it always predicts the mean', 'it never trains', 'B', 'High variance means the model reacts strongly to particular training samples and does not generalize steadily.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3560, 104, 'Which of the following is a supervised learning model?', 'k-means clustering', 'association rule mining', 'a decision tree trained on labelled data', 'autoencoders', 'C', 'A decision tree trained with input-output pairs is a supervised model.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3561, 104, 'Your model performs well on training data but poorly on validation data. Which of these is the BEST first remedy?', 'increase model complexity', 'train longer without changes', 'simplify the model or add regularization', 'delete the validation set', 'C', 'Overfitting is best countered by simplifying the model or adding regularization to reduce variance.', 'ADVANCED', 3, 'MCQ', 1),
(3562, 104, 'A dataset has 100,000 features but very few samples. Which technique can help?', 'increasing epochs', 'adding more noise', 'adding more layers', 'feature selection or regularization', 'D', 'With many features and few samples, feature selection and regularization prevent the model from overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3563, 104, 'Why is k-fold cross-validation better than a single train/test split?', 'it uses multiple folds so every sample is used for both training and validation, giving a more reliable estimate', 'it is faster to run', 'it needs no data', 'it removes the need for features', 'A', 'Cross-validation cycles each fold through validation, so the performance estimate uses all the data.', 'ADVANCED', 3, 'MCQ', 1),
(3564, 104, 'In reinforcement learning, the exploration-exploitation trade-off means the agent must:', 'always exploit', 'balance trying new actions (explore) with using known good ones (exploit)', 'never explore', 'randomly reset', 'B', 'The agent must explore to discover good actions while exploiting what it already knows works.', 'ADVANCED', 3, 'MCQ', 1),
(3565, 104, 'Which best describes the bias-variance trade-off?', 'increasing variance always lowers bias and vice versa; the goal is the sweet spot that minimizes total error', 'high bias and high variance are the same', 'the trade-off only applies to unsupervised learning', 'there is no trade-off', 'C', 'Bias and variance tend to move in opposite directions, and the best model balances both to minimize total error.', 'ADVANCED', 3, 'MCQ', 1),
(3566, 104, 'A bank wants to minimize missed fraud cases (false negatives). Which metric should they prioritize?', 'accuracy', 'precision', 'F1 only', 'recall (sensitivity)', 'D', 'Recall measures the fraction of actual fraud cases that are caught, so maximizing it reduces missed fraud.', 'ADVANCED', 3, 'MCQ', 1),
(3567, 104, 'A learning curve shows training error staying low while test error stays high. This indicates:', 'overfitting (high variance)', 'underfitting', 'an unbalanced class', 'a bug in the loader', 'A', 'A persistent gap between low training error and high test error is the sign of overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3568, 104, 'A dataset with 99% non-spam and 1% spam makes accuracy misleading because:', 'accuracy is always correct', 'a model predicting only the majority class still scores 99%, hiding poor minority performance', 'the model cannot train', 'the test set is unused', 'B', 'With imbalanced classes, predicting the majority class gives high accuracy while failing on the minority.', 'ADVANCED', 3, 'MCQ', 1),
(3569, 104, 'The primary purpose of regularization such as L2 in a linear model is to:', 'increase training accuracy', 'speed up data loading', 'penalize large weights to prevent overfitting', 'add more training data', 'C', 'L2 regularization adds a penalty on large weights, keeping the model simple and reducing overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3570, 104, 'A model trained on historical housing data performs badly in a new city. The most likely cause is:', 'the model is too small to run', 'feature distribution shift: the new city differs from the training distribution', 'the model lacks GPU', 'the data had no labels', 'D', 'When the test data comes from a different distribution than the training data, the model no longer generalizes.', 'ADVANCED', 3, 'MCQ', 1),
(3571, 105, 'What is the main goal of AI ethics?', 'ensuring AI systems are fair, transparent, accountable and beneficial to society', 'making AI faster', 'reducing AI memory', 'publishing research', 'A', 'AI ethics focuses on fairness, transparency, accountability and the overall benefit of AI to society.', 'BEGINNER', 1, 'MCQ', 1),
(3572, 105, 'If an AI hiring tool is biased against a group of applicants, which ethical concern is being violated?', 'bias and fairness', 'processing speed', 'storage cost', 'network latency', 'B', 'Treating one group unfairly violates the ethical principle of fairness.', 'BEGINNER', 1, 'MCQ', 1),
(3573, 105, 'What does algorithmic bias refer to?', 'when an algorithm''s results systematically favour or harm certain groups', 'when an algorithm runs slowly', 'when data is encrypted', 'when a model is too deep', 'C', 'Algorithmic bias is a systematic, unfair preference for or against certain groups in the algorithm''s results.', 'BEGINNER', 1, 'MCQ', 1),
(3574, 105, 'Which of these is a well-known application area of AI?', 'natural language processing', 'a screwdriver', 'a filing cabinet', 'a power outlet', 'D', 'Natural language processing, along with vision and robotics, is a major AI application area.', 'BEGINNER', 1, 'MCQ', 1),
(3575, 105, 'Why is transparency important in AI?', 'so users and auditors can understand how decisions are made', 'so the code runs faster', 'so the model uses less memory', 'so the dataset is bigger', 'A', 'Transparency lets people understand and inspect how an AI system reaches its decisions.', 'BEGINNER', 1, 'MCQ', 1),
(3576, 105, 'What is a common privacy risk of AI systems that process personal data?', 'the data may be misused or leaked', 'the data is always deleted', 'the data grows slower', 'the data is public', 'B', 'AI systems that store personal data can leak or misuse it if privacy is not protected.', 'BEGINNER', 1, 'MCQ', 1),
(3577, 105, 'Which technology powers chatbots like ChatGPT?', 'database replication', 'virtual reality headsets', 'large language models', 'cryptographic hashing', 'C', 'Large language models are trained on text and generate the conversational responses of modern chatbots.', 'BEGINNER', 1, 'MCQ', 1),
(3578, 105, 'What does accountability in AI require?', 'that someone can be held responsible for the system''s behaviour', 'that the model is fast', 'that data is free', 'that the UI is pretty', 'D', 'Accountability means clear assignment of responsibility for an AI system''s actions and outcomes.', 'BEGINNER', 1, 'MCQ', 1),
(3579, 105, 'Which of the following is an AI application in healthcare?', 'disease detection from medical images', 'a paper notebook', 'a refrigerator', 'a washing machine', 'A', 'AI systems analyse medical images to help detect diseases such as tumours.', 'BEGINNER', 1, 'MCQ', 1),
(3580, 105, 'What is deepfake technology used for?', 'creating realistic but fake media, which raises misuse concerns', 'compressing videos', 'backing up files', 'wifi routing', 'B', 'Deepfakes generate convincingly realistic but fake audio or video, raising authenticity and misuse concerns.', 'BEGINNER', 1, 'MCQ', 1),
(3581, 105, 'A self-driving car must choose between harming a pedestrian or its passenger in an unavoidable crash. Which area of AI ethics deals with this?', 'model explainability', 'moral decision-making (ethical dilemmas)', 'data storage', 'network security', 'B', 'Such unavoidable-harm choices are moral dilemmas studied in the ethics of autonomous systems.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3582, 105, 'An AI that denies loans using data that correlates with race is demonstrating:', 'high accuracy', 'good generalization', 'disparate impact (bias)', 'fast training', 'C', 'Denying loans based on a proxy for race harms one group and is an example of disparate impact.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3583, 105, 'To make a model''s decisions explainable to a user, which technique is appropriate?', 'using SHAP or LIME to explain predictions', 'encrypting the weights', 'removing labels', 'increasing epochs', 'D', 'SHAP and LIME are post-hoc tools that explain which features drove a particular prediction.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3584, 105, 'A healthcare AI suggests a wrong diagnosis because it was trained only on one region''s patients. This is a problem of:', 'lack of generalizability and fairness across groups', 'slow inference', 'low memory', 'visual rendering', 'A', 'Training on a narrow population makes the model fail on other groups, a fairness and generalization problem.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3585, 105, 'Which privacy technique adds noise to data so that individual records cannot be identified?', 'data encryption at rest only', 'differential privacy', 'web caching', 'lossless compression', 'B', 'Differential privacy adds calibrated noise so queries reveal trends without exposing individuals.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3586, 105, 'An AI system that generates news articles indistinguishable from human writing raises what concern?', 'misinformation and authenticity', 'database size', 'battery life', 'screen resolution', 'C', 'Realistic machine-written articles can spread misinformation and blur what is authentic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3587, 105, 'Why might an audit of an AI system be required before deployment in banking?', 'to verify fairness, safety and compliance with regulations', 'to increase the number of users', 'to reduce the file size', 'to change the logo', 'D', 'Regulations require proof that credit and lending systems are fair, safe and compliant.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3588, 105, 'What does ''human-in-the-loop'' mean in AI systems?', 'a human reviews or intervenes in the AI''s decisions', 'humans never interact with AI', 'only AI makes decisions', 'a human controls the power supply', 'A', 'Human-in-the-loop keeps a person involved in reviewing or overriding AI decisions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3589, 105, 'A recommendation system that only shows content similar to what you already watch may create:', 'a faster network', 'a filter bubble (echo chamber)', 'better battery life', 'more storage', 'B', 'Narrow personalization can trap users in a filter bubble that hides opposing or diverse content.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3590, 105, 'Which principle states that AI should be developed for the benefit of all people?', 'beneficence', 'efficiency', 'speed', 'profit maximization', 'C', 'Beneficence is the ethical principle of acting for the good and well-being of others.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3591, 105, 'A hospital deploys a diagnostic AI whose outcomes differ across ethnic groups. The most responsible next step is:', 'ignore the difference', 'deploy anyway to save time', 'conduct a fairness audit, retrain with balanced data and monitor outcomes', 'delete the model', 'C', 'A fairness audit identifies the cause, balanced retraining reduces bias, and ongoing monitoring prevents relapse.', 'ADVANCED', 3, 'MCQ', 1),
(3592, 105, 'A social media platform''s engagement-maximizing AI contributes to the spread of harmful content. This is an example of:', 'overfitting', 'hardware failure', 'correct labelling', 'misaligned incentives (unintended social harm)', 'D', 'Optimizing purely for engagement can produce harmful social outcomes the designers did not intend.', 'ADVANCED', 3, 'MCQ', 1),
(3593, 105, 'Under the principle of meaningful human control, an autonomous weapon system should:', 'keep a human accountable for decisions on the use of force', 'always operate without humans', 'ignore override commands', 'only act at night', 'A', 'Meaningful human control requires that humans remain responsible and able to override lethal decisions.', 'ADVANCED', 3, 'MCQ', 1),
(3594, 105, 'A company wants to use customer data to train a model. Which practice respects user autonomy?', 'secretly collecting data', 'obtaining informed consent and allowing opt-out', 'selling data without notice', 'encrypting the model only', 'B', 'Informed consent and the option to opt out give users control over how their data is used.', 'ADVANCED', 3, 'MCQ', 1),
(3595, 105, 'Which strategy best addresses the risk that an AI trained on historical data encodes past discrimination?', 'debiasing the data and auditing outcomes across groups', 'increasing the dataset size', 'using only the newest model', 'removing all features', 'C', 'Debiasing the training data plus auditing results across groups actively counteracts historical discrimination.', 'ADVANCED', 3, 'MCQ', 1),
(3596, 105, 'A financial model must explain why a loan was denied to satisfy regulations. Which approach is most defensible?', 'deploying an opaque deep network with no explanation', 'refusing to explain', 'ignoring the request', 'using interpretable models or post-hoc explanation methods validated for fidelity', 'D', 'Interpretable models or fidelity-validated explanations satisfy the legal right to an explanation.', 'ADVANCED', 3, 'MCQ', 1),
(3597, 105, 'When an AI system makes an error that harms a patient, which ethical requirement applies?', 'clear accountability and liability mechanisms for the harm', 'deleting the logs', 'blaming the patient', 'hiding the error', 'A', 'Clear accountability and liability rules determine who is responsible when an AI harms someone.', 'ADVANCED', 3, 'MCQ', 1),
(3598, 105, 'A government uses facial recognition for mass surveillance. Which concern is most directly raised?', 'the models are too large', 'civil liberties and privacy of citizens', 'the frame rate is low', 'the servers are slow', 'B', 'Mass surveillance with facial recognition threatens citizens'' privacy and civil liberties.', 'ADVANCED', 3, 'MCQ', 1),
(3599, 105, 'To prevent an LLM from producing dangerous instructions, which mitigation is commonly used?', 'removing all parameters', 'disabling networking', 'red-teaming, safety fine-tuning and output filtering', 'increasing the context window', 'C', 'Red-teaming finds harmful outputs, safety fine-tuning reduces them, and filtering blocks remaining ones.', 'ADVANCED', 3, 'MCQ', 1),
(3600, 105, 'The best way to operationalize ethical principles in an AI product lifecycle is to:', 'write them once and never revisit', 'embed them in a design-time and runtime governance process with audits', 'document them but ignore them', 'leave them to the end users', 'D', 'Ethical principles only take effect when embedded in ongoing governance with audits at design and runtime.', 'ADVANCED', 3, 'MCQ', 1),
(3601, 106, 'What is the primary goal of a linear regression model?', 'predict a continuous numerical value', 'predict a categorical label', 'cluster similar data points', 'reduce the dimensionality of data', 'A', 'Linear regression models the relationship between features and a continuous target, so its goal is to predict a numeric value.', 'BEGINNER', 1, 'MCQ', 1),
(3602, 106, 'In the linear equation y = mx + b, what does the term m represent?', 'the intercept', 'the slope of the line', 'the error term', 'the dependent variable', 'B', 'In y = mx + b the coefficient m is the slope, which controls how much y changes for a one-unit change in x.', 'BEGINNER', 1, 'MCQ', 1),
(3603, 106, 'Which of the following tasks is best suited to linear regression?', 'classifying emails as spam or not spam', 'grouping customers into segments', 'predicting a house sale price', 'detecting fraudulent transactions', 'C', 'Predicting a numeric amount such as a house price is a regression task, which linear regression is designed to handle.', 'BEGINNER', 1, 'MCQ', 1),
(3604, 106, 'In linear regression, what is a residual?', 'the intercept of the fitted line', 'the slope of the fitted line', 'the input feature value', 'the difference between the observed and predicted values', 'D', 'A residual is the difference between the actual observed target value and the value predicted by the model.', 'BEGINNER', 1, 'MCQ', 1),
(3605, 106, 'What is the purpose of the coefficient of determination, R-squared?', 'to measure how well the regression model explains the variance of the target', 'to measure the number of features in the model', 'to determine the learning rate', 'to calculate the slope of the line', 'A', 'R-squared tells how much of the variance in the target variable is explained by the features in the model.', 'BEGINNER', 1, 'MCQ', 1),
(3606, 106, 'What range of values does the sigmoid function used in logistic regression output?', 'any real number', 'between 0 and 1', 'between -1 and 1', 'between 0 and infinity', 'B', 'The sigmoid function squashes its input to the interval from 0 to 1, which makes it usable as a probability.', 'BEGINNER', 1, 'MCQ', 1),
(3607, 106, 'For which type of target variable is logistic regression designed?', 'a continuous numeric target', 'an unordered cluster id', 'a binary categorical target', 'a time series timestamp', 'C', 'Logistic regression predicts the probability of membership in a class, so it is used for binary categorical targets.', 'BEGINNER', 1, 'MCQ', 1),
(3608, 106, 'What does the intercept term b represent in a simple linear regression model?', 'the average slope', 'the size of the residuals', 'the number of training examples', 'the predicted value when the input feature is zero', 'D', 'The intercept is the expected value of the target when all input features are equal to zero.', 'BEGINNER', 1, 'MCQ', 1),
(3609, 106, 'Which of the following best describes a supervised learning task?', 'the model learns from labeled input-output pairs', 'the model discovers patterns without labels', 'the model is trained on unlabeled text', 'the model groups data by similarity', 'A', 'In supervised learning the model is trained on input-output pairs that include the correct labels or target values.', 'BEGINNER', 1, 'MCQ', 1),
(3610, 106, 'In the sigmoid function, what is the output when the input is a large positive number?', 'close to 0', 'negative', 'close to 1', 'exactly 0.5', 'C', 'For a large positive input the sigmoid approaches 1, so the function saturates near the upper bound.', 'BEGINNER', 1, 'MCQ', 1),
(3611, 106, 'What is the slope of the line passing through the points (1, 2) and (3, 6)?', '2', '1', '3', '4', 'A', 'The slope is the change in y divided by the change in x, which is (6 - 2) / (3 - 1) = 2.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3612, 106, 'In ordinary least squares linear regression, what quantity is minimized?', 'the sum of the residuals', 'the sum of the squared residuals', 'the product of the residuals', 'the number of features', 'B', 'Ordinary least squares finds the line that minimizes the sum of the squared vertical distances to the data points.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3613, 106, 'For the model y = 2 + 3x, what is the predicted value of y when x is 4?', '14', '12', '9', '24', 'C', 'Substituting x = 4 into y = 2 + 3x gives y = 2 + 12 = 14.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3614, 106, 'A model predicts the values [3, 5, 7] while the true values are [3, 4, 8]. What is the mean absolute error?', '1.33', '2.00', '1.00', 'approximately 0.67', 'D', 'The absolute errors are 0, 1 and 1, and their average is 2 / 3, which is approximately 0.67.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3615, 106, 'What value does the sigmoid function produce for an input of exactly 0?', '0.5', '0', '1', '0.25', 'A', 'The sigmoid of 0 is 1 / (1 + e^0) = 1 / 2 = 0.5, so the function passes through the midpoint of its range.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3616, 106, 'A logistic regression model outputs a probability of 0.7 for a sample, and the decision threshold is 0.5. What class is predicted?', 'class 0', 'class 1', 'no class', 'both classes', 'B', 'Since 0.7 exceeds the 0.5 threshold, the sample is classified into the positive class, class 1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3617, 106, 'What does an R-squared value of 0.9 tell you about a fitted regression model?', 'the model is useless', 'it explains about 90 percent of the variance in the target', '90 percent of the points lie exactly on the line', 'the slope is 0.9', 'C', 'An R-squared of 0.9 means the features account for 90 percent of the variance in the target variable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3618, 106, 'In a correctly fitted linear regression, what happens to the predictions when one feature is rescaled by multiplying it by 10?', 'the predictions are divided by 10', 'the predictions are multiplied by 10', 'the predictions are unchanged', 'the predictions become zero', 'D', 'After refitting, the coefficient for the rescaled feature adjusts inversely, so the fitted predictions stay the same.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3619, 106, 'Which loss function is most commonly used to train a binary logistic regression model?', 'log loss (binary cross-entropy)', 'mean squared error', 'hinge loss', 'mean absolute error', 'A', 'Logistic regression is trained with log loss (binary cross-entropy), which measures the divergence of predicted probabilities from the true labels.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3620, 106, 'If a linear regression model achieves an R-squared of exactly 1 on the training set, what must be true about the residuals?', 'they are all positive', 'they are all negative', 'they are all exactly zero', 'they follow a normal distribution', 'C', 'R-squared equal to 1 means the model explains all the variance, which is only possible when every residual is zero.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3621, 106, 'A housing price regression model includes two highly correlated features. What is the most likely consequence of this multicollinearity?', 'the predictions become less accurate', 'the training time drops to zero', 'the model refuses to train', 'the individual coefficient estimates become unstable', 'D', 'Multicollinearity makes it hard to attribute variance to any one predictor, so the individual coefficients become unstable.', 'ADVANCED', 3, 'MCQ', 1),
(3622, 106, 'In a fraud detection dataset where only 1 percent of transactions are fraudulent, why is accuracy alone a poor metric for a logistic regression model?', 'accuracy is always zero', 'the model cannot be trained', 'a model that predicts everything as non-fraud would still be 99 percent accurate', 'accuracy is only defined for regression', 'C', 'With heavy class imbalance a trivial model can be very accurate, so precision, recall and AUC must also be examined.', 'ADVANCED', 3, 'MCQ', 1),
(3623, 106, 'What is the primary effect of L2 (ridge) regularization on the coefficient estimates of a linear regression model?', 'it sets all coefficients to zero', 'it shrinks the coefficients toward zero', 'it doubles the coefficients', 'it has no effect on the coefficients', 'B', 'L2 regularization penalizes the sum of squared coefficients, which shrinks them toward zero without setting them exactly to zero.', 'ADVANCED', 3, 'MCQ', 1),
(3624, 106, 'A categorical feature with three levels is one-hot encoded for a linear regression model. How many binary columns should be created to avoid perfect multicollinearity?', 'two', 'three', 'one', 'zero', 'A', 'Dropping one reference level and keeping k - 1 = 2 dummy columns avoids perfect multicollinearity with the intercept.', 'ADVANCED', 3, 'MCQ', 1),
(3625, 106, 'A training set contains 50 million rows and 200 numeric features. Why is stochastic gradient descent a practical choice for fitting a logistic regression model?', 'it requires no data at all', 'it always finds the global optimum instantly', 'it only works on small datasets', 'it updates parameters on small random batches, scaling to large data', 'D', 'Stochastic gradient descent processes small random batches at a time, so it scales efficiently to very large datasets.', 'ADVANCED', 3, 'MCQ', 1),
(3626, 106, 'A logistic regression model returns a probability of exactly 0.9 for a sample and the decision threshold is set to 0.9. What class is assigned?', 'class 0 for sure', 'class 1 for sure', 'either class, since the sample sits exactly on the decision boundary', 'no class can ever be assigned', 'C', 'When the predicted probability equals the threshold, the sample lies exactly on the decision boundary, so the class is a tie broken by convention.', 'ADVANCED', 3, 'MCQ', 1),
(3627, 106, 'When fitting a linear regression to a time series of stock prices, which classic assumption is most likely to be violated?', 'the features must be categorical', 'the residuals should be independent, but time-correlated data breaks this', 'the target must be binary', 'the slope must be positive', 'B', 'Regression assumes independent residuals, but serial correlation in time series data violates that assumption and can distort inference.', 'ADVANCED', 3, 'MCQ', 1),
(3628, 106, 'A linear regression model with 500 features overfits the training data. Which approach directly reduces the complexity of the model?', 'add L1 or L2 regularization', 'add more features', 'remove all training data', 'increase the learning rate', 'A', 'Regularization penalizes large coefficients and effectively reduces model complexity, which counters overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3629, 106, 'In gradient descent for linear regression, what is the main benefit of scaling the features to a similar range?', 'it guarantees the global minimum', 'it makes the coefficients exactly 1', 'it removes the need for a learning rate', 'it makes the loss surface more spherical so convergence is faster', 'D', 'Scaling produces a more even-shaped loss surface so gradient descent takes smoother, faster steps toward the optimum.', 'ADVANCED', 3, 'MCQ', 1),
(3630, 106, 'A logistic regression model must classify an image into one of three classes. Which common strategy extends binary logistic regression to this multiclass problem?', 'using a single sigmoid output', 'one-vs-rest training of three binary classifiers', 'predicting a continuous price', 'using k-means on the labels', 'B', 'The one-vs-rest approach trains one binary classifier per class and is a standard way to generalize logistic regression to many classes.', 'ADVANCED', 3, 'MCQ', 1),
(3631, 107, 'What is the goal of a classification task in machine learning?', 'predict a continuous number', 'assign an input to one of several discrete classes', 'group unlabeled data by similarity', 'reduce the number of features', 'B', 'Classification assigns each input to one of a finite set of discrete class labels rather than a continuous value.', 'BEGINNER', 1, 'MCQ', 1),
(3632, 107, 'In the k-nearest neighbors (k-NN) algorithm, what does the parameter k represent?', 'the number of neighbors considered when making a prediction', 'the number of features in the dataset', 'the number of classes in the data', 'the number of training iterations', 'A', 'The k in k-NN is the number of closest training samples that vote when a prediction is made for a new point.', 'BEGINNER', 1, 'MCQ', 1),
(3633, 107, 'Which distance metric is most commonly used with k-NN for numeric data?', 'Hamming distance', 'cosine similarity', 'taxicab geometry', 'Euclidean distance', 'D', 'Euclidean distance, the straight-line distance between points, is the default and most common metric for numeric k-NN.', 'BEGINNER', 1, 'MCQ', 1),
(3634, 107, 'How does k-NN decide the class of a new test sample?', 'by following a set of if-else rules', 'by training a neural network', 'by taking a majority vote of its k nearest neighbors', 'by solving a linear equation', 'C', 'k-NN looks at the k closest training points and predicts the class that appears most often among them.', 'BEGINNER', 1, 'MCQ', 1),
(3635, 107, 'Why is k-NN sometimes called a lazy learner?', 'it needs months to train', 'it does no training; it stores the training data and classifies at prediction time', 'it only works with trees', 'it forgets the training data immediately', 'B', 'k-NN performs no model fitting up front, so all the work happens at prediction time, which makes it a lazy learner.', 'BEGINNER', 1, 'MCQ', 1),
(3636, 107, 'Is k-NN a supervised or unsupervised learning algorithm?', 'supervised, because it uses labeled training samples', 'unsupervised, because it uses no labels', 'it is neither', 'it depends on the kernel', 'A', 'k-NN uses labeled training samples to make predictions, so it is a supervised learning algorithm.', 'BEGINNER', 1, 'MCQ', 1),
(3637, 107, 'For a binary classification problem, how many distinct classes exist in the target variable?', 'zero', 'one', 'exactly three', 'two', 'D', 'A binary classification problem has exactly two possible class labels, such as spam versus not spam.', 'BEGINNER', 1, 'MCQ', 1),
(3638, 107, 'What is the main weakness of using k = 1 in k-NN?', 'it is too slow to train', 'it requires a neural network', 'it is highly sensitive to noise in a single neighbor', 'it ignores all training data', 'C', 'With k = 1 the prediction depends on a single neighbor, so one noisy point can completely change the classification.', 'BEGINNER', 1, 'MCQ', 1),
(3639, 107, 'Which statement about the training time of k-NN is correct?', 'training is very expensive', 'training is essentially negligible because no model is learned', 'training takes longer than prediction', 'training requires cross-validation', 'B', 'Because k-NN simply stores the training data, its training phase is nearly instantaneous.', 'BEGINNER', 1, 'MCQ', 1),
(3640, 107, 'In k-NN, what does a larger value of k generally do to the decision boundary?', 'it becomes more jagged', 'it disappears entirely', 'it becomes perfectly linear', 'it becomes smoother and less affected by individual noisy points', 'D', 'A larger k averages over more neighbors, which smooths the decision boundary and dampens the effect of noise.', 'BEGINNER', 1, 'MCQ', 1),
(3641, 107, 'With k = 3, the three nearest neighbors of a test point have labels A, A and B. What class is predicted?', 'B', 'A or B randomly', 'A', 'no prediction is possible', 'C', 'A appears twice and B once, so the majority vote selects class A.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3642, 107, 'What is the Euclidean distance between the points (1, 2) and (4, 6)?', '7', '3', '4', '5', 'D', 'The distance is the square root of (4 - 1)^2 + (6 - 2)^2 = 9 + 16 = 25, which equals 5.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3643, 107, 'A test sample is closest to a single training point labeled spam. With k = 1, what label is assigned?', 'spam', 'not spam', 'both labels', 'an error occurs', 'A', 'With k = 1 the prediction takes the label of the single nearest neighbor, which is spam.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3644, 107, 'Why must features be scaled before applying k-NN with Euclidean distance?', 'scaling makes k-NN unsupervised', 'features with large ranges would otherwise dominate the distance computation', 'scaling removes the need for labels', 'scaling always improves accuracy to 100 percent', 'B', 'Without scaling, features with large numeric ranges overwhelm smaller-range features in the distance calculation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3645, 107, 'In binary classification, why is an odd value of k commonly chosen for k-NN?', 'odd values train faster', 'odd values reduce memory use', 'an odd k avoids ties in the majority vote', 'odd values ignore the distance metric', 'C', 'An odd k guarantees a clear majority in a two-class vote, eliminating tie situations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3646, 107, 'What is the Manhattan distance between the points (0, 0) and (3, 4)?', '3', '4', '5', '7', 'D', 'Manhattan distance is the sum of the absolute coordinate differences, which is 3 + 4 = 7.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3647, 107, 'As k grows very large in k-NN, what typically happens to the decision boundary?', 'it becomes smoother and more stable', 'it becomes highly jagged', 'it always becomes a circle', 'it disappears', 'A', 'Voting over many neighbors averages out local fluctuations, so the boundary becomes smooth and stable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3648, 107, 'Which problem is described by the curse of dimensionality in the context of k-NN?', 'datasets with many rows train too slowly', 'in high dimensions, distances between points become less meaningful', 'labels become harder to read', 'k must always equal the number of features', 'B', 'In high-dimensional spaces distances concentrate and cease to be informative, degrading k-NN performance.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3649, 107, 'A binary classifier produces a confusion matrix. How many cells (predicted-actual combinations) does it contain?', 'two', 'three', 'four', 'nine', 'C', 'A binary confusion matrix has four cells: true positive, false positive, true negative and false negative.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3650, 107, 'A training set has 100 samples of class A and 10 of class B. With k = 5 and plain majority voting, what risk does k-NN face?', 'the majority class A may dominate small neighborhoods, hiding class B', 'the model becomes a regression model', 'no samples can ever be classified', 'the distance metric is ignored', 'A', 'Because class A is far more common, most neighborhoods contain mostly A samples, causing class B to be under-represented.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3651, 107, 'A k-NN model will be deployed for real-time fraud scoring on millions of records. What is the main scalability concern?', 'prediction time grows linearly with the training set size because all distances must be computed', 'training time is the main bottleneck', 'k must be reduced to 1', 'the confusion matrix becomes too large', 'A', 'A naive k-NN scans all training points for every query, so prediction cost grows linearly with the stored data size.', 'ADVANCED', 3, 'MCQ', 1),
(3652, 107, 'A data scientist must choose the value of k for a k-NN model. Which approach selects k most reliably?', 'always use k = 1', 'always use k = 100', 'choose the k that minimizes error on held-out validation folds', 'choose the k equal to the number of features', 'C', 'Tuning k on validation folds finds the value that generalizes best rather than relying on arbitrary or fixed choices.', 'ADVANCED', 3, 'MCQ', 1),
(3653, 107, 'A dataset mixes numeric and categorical features. How should distances be computed in k-NN?', 'use Euclidean distance for everything', 'use an appropriate mixed measure, such as Hamming distance for the categorical features', 'ignore the numeric features', 'convert the numbers to text', 'B', 'Different feature types need suitable measures, so categorical features commonly use Hamming distance while numeric ones use Euclidean distance.', 'ADVANCED', 3, 'MCQ', 1),
(3654, 107, 'A k-NN classifier performs poorly on an imbalanced dataset. Which remedy most directly helps minority-class recall?', 'increase k to 200', 'remove the minority class', 'use only the majority class', 'resample the minority class or use distance-weighted voting', 'D', 'Resampling balances the neighborhoods and distance-weighted voting lets closer neighbors count more, both helping minority recall.', 'ADVANCED', 3, 'MCQ', 1),
(3655, 107, 'During a k-NN pipeline, the scaler is fitted on the whole dataset before splitting into train and test. What is the problem?', 'this is data leakage, because test information influences the scaling of training data', 'scaling should never be applied to k-NN', 'the model becomes unsupervised', 'this makes the confusion matrix invalid', 'A', 'Fitting the scaler on all data lets test statistics leak into training, so the scaler should be fitted on the training split only.', 'ADVANCED', 3, 'MCQ', 1),
(3656, 107, 'Two features in a k-NN model have wildly different units, such as income in dollars and age in years. What must be done first?', 'nothing, k-NN handles units automatically', 'delete the age feature', 'standardize or normalize both features before computing distances', 'convert income to text', 'C', 'Standardizing brings all features to a comparable scale so no single feature dominates the distance metric.', 'ADVANCED', 3, 'MCQ', 1),
(3657, 107, 'A dataset has 1 million samples and 1,000 features. Which combination of challenges makes k-NN impractical?', 'the labels are all equal', 'the curse of dimensionality plus linear distance computation per prediction', 'there are no nearest neighbors', 'the data is too small to train', 'B', 'High dimensionality makes distances uninformative, and scanning a million points per query makes prediction too slow.', 'ADVANCED', 3, 'MCQ', 1),
(3658, 107, 'For a k-NN service that must answer billions of queries, which engineering solution is most appropriate?', 'train a single decision tree instead', 'increase the value of k', 'delete half the training data', 'build an approximate nearest-neighbor index such as a KD-tree or HNSW graph', 'D', 'Approximate nearest-neighbor indexes trade a little accuracy for enormous speedups in answering k-NN queries.', 'ADVANCED', 3, 'MCQ', 1),
(3659, 107, 'An interviewer asks about a fundamental weakness of k-NN as a lazy learner. What is the best answer?', 'it stores the entire training set, consuming large amounts of memory and making prediction slow', 'it cannot handle numeric data', 'it always underfits', 'it requires a GPU to train', 'A', 'Storing every training sample uses significant memory, and prediction requires scanning those stored samples each time.', 'ADVANCED', 3, 'MCQ', 1),
(3660, 107, 'In a k-NN regression task, how is the predicted value for a test point computed?', 'by taking a majority vote of the neighbors', 'by averaging the target values of the k nearest neighbors', 'by selecting the largest neighbor value', 'by training a linear model on the neighbors', 'B', 'For regression the prediction is the mean of the target values of the k nearest neighbors.', 'ADVANCED', 3, 'MCQ', 1),
(3661, 108, 'What is a decision tree?', 'a flowchart-like structure of decision rules used to classify or predict', 'a collection of linear equations', 'a neural network with many layers', 'a distance-based algorithm', 'A', 'A decision tree is a flowchart of nested if-else decisions on features that ends in predictions at leaf nodes.', 'BEGINNER', 1, 'MCQ', 1),
(3662, 108, 'In a decision tree, what does a leaf node represent?', 'a splitting rule', 'the final prediction or class label', 'a feature', 'a branch', 'B', 'Leaf nodes are the terminal nodes of a tree, each holding the final predicted class or value.', 'BEGINNER', 1, 'MCQ', 1),
(3663, 108, 'Which of the following is an example of an ensemble learning method?', 'a single decision tree', 'k-means', 'random forest', 'logistic regression', 'C', 'A random forest combines many decision trees, so it is an ensemble method.', 'BEGINNER', 1, 'MCQ', 1),
(3664, 108, 'What is the root node of a decision tree?', 'the last node in the tree', 'a leaf node', 'a node with no parent, where the first split occurs', 'a node with exactly two leaves', 'D', 'The root is the topmost node with no parent, and it makes the first split of the tree.', 'BEGINNER', 1, 'MCQ', 1),
(3665, 108, 'Can a decision tree be used for regression tasks?', 'yes, regression trees predict a numeric value from the leaf nodes', 'no, trees only classify', 'only if the labels are binary', 'only with 100 leaves', 'A', 'Regression trees predict a numeric value, typically the mean of the target values in each leaf.', 'BEGINNER', 1, 'MCQ', 1),
(3666, 108, 'What is bagging in ensemble learning?', 'training one giant tree', 'training many models on bootstrap samples and combining their predictions', 'training models in a chain', 'removing all features', 'B', 'Bagging trains each model on a random bootstrap sample of the data and then combines their predictions.', 'BEGINNER', 1, 'MCQ', 1),
(3667, 108, 'What is boosting in ensemble learning?', 'training models independently in parallel', 'averaging all predictions', 'training models sequentially so each corrects the errors of the previous one', 'using only one weak learner', 'C', 'Boosting builds models one after another, with each new model focusing on the mistakes made by the previous ones.', 'BEGINNER', 1, 'MCQ', 1),
(3668, 108, 'A random forest is an ensemble of what type of base model?', 'linear regressions', 'support vector machines', 'neural networks', 'decision trees', 'D', 'A random forest is composed of many decision trees whose predictions are aggregated.', 'BEGINNER', 1, 'MCQ', 1),
(3669, 108, 'What problem most commonly results from growing a decision tree too deep?', 'overfitting to the training data', 'the tree always underfits', 'the tree becomes a regression tree', 'the tree loses its root', 'A', 'Very deep trees split on tiny noise-specific details, so they memorize the training data and overfit.', 'BEGINNER', 1, 'MCQ', 1),
(3670, 108, 'Which criterion measures the purity of a node when building a decision tree?', 'mean squared error', 'accuracy', 'information gain or Gini impurity', 'the confusion matrix', 'C', 'Gini impurity and information gain quantify how pure a node is, guiding the choice of the best split.', 'BEGINNER', 1, 'MCQ', 1),
(3671, 108, 'A leaf in a classification tree contains 4 samples of class A and 1 sample of class B. What class does the tree predict for a sample reaching this leaf?', 'B', 'an average of A and B', 'no class', 'A', 'D', 'The leaf predicts the majority class among its training samples, which is class A with 4 of 5 votes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3672, 108, 'A node contains equal numbers of two classes (0.5 and 0.5). What is its Gini impurity?', '0', '1', '0.5', '0.25', 'C', 'Gini impurity is 1 minus the sum of squared class proportions, which is 1 - 0.25 - 0.25 = 0.5.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3673, 108, 'What is the main difference between bagging and boosting?', 'bagging is sequential while boosting is parallel', 'boosting trains models sequentially, each correcting the previous, while bagging trains them independently in parallel', 'they are identical', 'boosting uses only one model', 'B', 'Bagging trains models independently on bootstrap samples, while boosting trains models sequentially to correct prior errors.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3674, 108, 'A decision tree is used to predict house prices. How is a prediction computed for a sample that reaches a leaf?', 'the average of the target values of the training samples in that leaf', 'the most frequent class in the leaf', 'a random value', 'the value of the root node', 'A', 'For regression trees the leaf prediction is the mean of the target values of the training samples that fall into it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3675, 108, 'What is the entropy of a node that contains only samples of a single class?', '1', '0.5', 'infinity', '0', 'D', 'A pure node has no uncertainty, so its entropy is exactly 0.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3676, 108, 'In a random forest, what data does each individual tree use for training?', 'the entire original dataset unchanged', 'no data at all', 'a bootstrap sample of the data along with a random subset of features', 'only the test set', 'C', 'Each tree trains on a bootstrap sample of rows and considers only a random subset of features at each split.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3677, 108, 'What is a decision stump?', 'a tree with 100 nodes', 'a decision tree with a single split', 'a random forest with one tree', 'a leaf node', 'B', 'A decision stump is a tree with exactly one split, making it a very weak learner used in boosting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3678, 108, 'What type of base learner does gradient boosting typically use?', 'shallow decision trees (weak learners)', 'deep neural networks', 'k-NN models', 'fully grown trees', 'A', 'Gradient boosting builds an ensemble of shallow trees, which are weak learners whose errors are corrected sequentially.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3679, 108, 'A categorical feature with very high cardinality is used to split a decision tree. What risk arises?', 'the tree becomes a regression tree', 'the feature is ignored', 'the tree loses all leaves', 'the feature may cause the tree to overfit because of the many possible split points', 'D', 'Many categories create a huge number of possible splits, which can lead the tree to memorize the training data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3680, 108, 'For a regression task, how does a random forest produce its final prediction?', 'by taking a majority vote', 'by averaging the predictions of all trees', 'by selecting the deepest tree answer', 'by multiplying all predictions', 'B', 'For regression the random forest averages the numeric predictions of all of its trees.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3681, 108, 'A random forest with 10,000 trees must run within a tight memory budget. Which change is most effective?', 'keep all trees and add more', 'reduce the number of trees or limit their depth', 'double the number of features', 'remove the bootstrap sampling', 'B', 'Fewer trees or shallower trees directly reduce the stored model size while only mildly affecting accuracy.', 'ADVANCED', 3, 'MCQ', 1),
(3682, 108, 'How is feature importance commonly estimated in a random forest?', 'by aggregating the impurity decrease contributed by each feature across all trees', 'by counting the number of leaves', 'by measuring tree height', 'by the order features appear in the data', 'A', 'Random forests average the total impurity reduction each feature provides over all splits and trees to score importance.', 'ADVANCED', 3, 'MCQ', 1),
(3683, 108, 'A gradient boosting model trained with squared error performs poorly because a few extreme outliers dominate the residuals. What is a likely cause?', 'the trees are too shallow', 'the learning rate is zero', 'the data has no noise', 'the squared error loss amplifies the influence of the outliers', 'D', 'Squared error is strongly affected by large residuals, so a few outliers can dominate the loss and the updates.', 'ADVANCED', 3, 'MCQ', 1),
(3684, 108, 'On structured tabular data, which statement comparing XGBoost and random forest is generally true?', 'random forest always wins', 'they are identical', 'with careful tuning, gradient boosting often achieves the best accuracy but is more sensitive to hyperparameters', 'XGBoost cannot handle trees', 'C', 'Gradient boosting often edges out random forests on tabular data but requires more careful hyperparameter tuning.', 'ADVANCED', 3, 'MCQ', 1),
(3685, 108, 'A decision tree must handle features with missing values. Which technique is commonly used?', 'delete the whole column', 'surrogate splits, imputation, or a dedicated missing-value branch', 'replace missing values with the target', 'never split on that feature', 'B', 'Surrogate splits, imputation and missing-value branches are standard ways for trees to exploit data with missing values.', 'ADVANCED', 3, 'MCQ', 1),
(3686, 108, 'What typically happens to a decision tree grown to maximum depth with no pruning?', 'it overfits, memorizing noise in the training set', 'it always generalizes better', 'it becomes a random forest', 'it returns constant predictions', 'A', 'An unpruned maximum-depth tree splits until each leaf is pure, memorizing noise rather than learning general patterns.', 'ADVANCED', 3, 'MCQ', 1),
(3687, 108, 'In a random forest, what are the out-of-bag samples of a tree?', 'the samples used to train that tree', 'the test set', 'the root node samples', 'the training samples not included in that tree bootstrap sample, used for a validation estimate', 'D', 'Out-of-bag samples are the training rows left out of a tree bootstrap sample, providing an unbiased error estimate.', 'ADVANCED', 3, 'MCQ', 1),
(3688, 108, 'During gradient boosting, what do subsequent weak learners focus on?', 'random noise', 'samples already correctly classified', 'the residuals or errors left by the current ensemble', 'the root node', 'C', 'Each new weak learner fits the residual errors of the current ensemble, progressively reducing them.', 'ADVANCED', 3, 'MCQ', 1),
(3689, 108, 'A bank requires a fully auditable, interpretable model for credit decisions. Which option is the best fit?', 'a 500-tree random forest', 'a single, pruned decision tree', 'a deep neural network', 'a k-NN model with millions of neighbors', 'B', 'A single small decision tree can be read directly and explained, which is why it is preferred when interpretability is critical.', 'ADVANCED', 3, 'MCQ', 1),
(3690, 108, 'Why does random feature selection at each split in a random forest help overall accuracy?', 'it always trains faster', 'it guarantees no overfitting', 'it removes the need for labels', 'it decorrelates the trees, so the ensemble averaging reduces variance', 'D', 'Random feature subsets make trees less correlated, so averaging them reduces variance more effectively.', 'ADVANCED', 3, 'MCQ', 1),
(3691, 109, 'What type of machine learning is clustering?', 'supervised learning', 'reinforcement learning', 'unsupervised learning', 'semi-supervised learning', 'C', 'Clustering discovers groups in unlabeled data, which makes it an unsupervised learning task.', 'BEGINNER', 1, 'MCQ', 1),
(3692, 109, 'In k-means clustering, what does the letter k represent?', 'the number of features', 'the number of iterations', 'the number of training samples', 'the number of clusters to find', 'D', 'The k in k-means is the number of clusters the algorithm must partition the data into.', 'BEGINNER', 1, 'MCQ', 1),
(3693, 109, 'What is a centroid in k-means?', 'the mean position of the points in a cluster', 'the smallest point in a cluster', 'the farthest point in a cluster', 'the first point in the dataset', 'A', 'A centroid is the arithmetic mean of all the points currently assigned to a cluster, acting as its center.', 'BEGINNER', 1, 'MCQ', 1),
(3694, 109, 'Which of the following is a clustering algorithm?', 'linear regression', 'k-means', 'k-nearest neighbors', 'logistic regression', 'B', 'k-means partitions data into clusters, so it is a clustering algorithm.', 'BEGINNER', 1, 'MCQ', 1),
(3695, 109, 'What is the main purpose of principal component analysis (PCA)?', 'to classify samples', 'to cluster samples', 'to reduce the number of features while retaining most variance', 'to predict continuous values', 'C', 'PCA projects data onto a few orthogonal directions of maximum variance to reduce the feature count.', 'BEGINNER', 1, 'MCQ', 1),
(3696, 109, 'What do the principal components produced by PCA represent?', 'the mean of the data', 'the labels of the data', 'the number of clusters', 'directions of maximum variance in the data', 'D', 'Each principal component is a direction along which the data varies the most.', 'BEGINNER', 1, 'MCQ', 1),
(3697, 109, 'Which statement best describes how k-means assigns a data point to a cluster?', 'it assigns the point to the cluster with the nearest centroid', 'it assigns the point randomly', 'it uses the majority class', 'it trains a decision tree', 'A', 'k-means repeatedly assigns each point to the cluster whose centroid is closest, then updates the centroids.', 'BEGINNER', 1, 'MCQ', 1),
(3698, 109, 'A company wants to divide its customers into groups by buying behavior without labels. Which method fits best?', 'linear regression', 'clustering', 'classification', 'logistic regression', 'B', 'Clustering finds natural groups in unlabeled customer data, which is exactly what the company needs.', 'BEGINNER', 1, 'MCQ', 1),
(3699, 109, 'Which of the following is NOT a clustering algorithm?', 'k-means', 'DBSCAN', 'linear regression', 'hierarchical clustering', 'C', 'Linear regression predicts a numeric target and is not a clustering algorithm.', 'BEGINNER', 1, 'MCQ', 1),
(3700, 109, 'In k-means, the final result depends heavily on the positions of which objects?', 'the initial centroids', 'the leaves of a tree', 'the support vectors', 'the confusion matrix', 'A', 'Different initial centroid placements can lead k-means to different local optima, so initialization matters.', 'BEGINNER', 1, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(3701, 109, 'In the elbow method, what is plotted to help choose the number of clusters?', 'the within-cluster sum of squared distances against k', 'accuracy against k', 'the number of features against k', 'silhouette score against the number of features', 'A', 'The elbow method plots within-cluster inertia against k and picks the k at the bend of the curve.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3702, 109, 'Which statement about k-means and the choice of initial centroids is true?', 'results never depend on initialization', 'k-means always converges to the global optimum', 'poor initialization can lead to poor local optima', 'initialization is irrelevant', 'C', 'k-means is prone to converging to poor local optima, so a bad initial placement of centroids hurts the result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3703, 109, 'For clustering sparse text documents, which similarity or distance measure is often preferred over plain Euclidean distance?', 'Hamming distance', 'cosine similarity', 'edit distance', 'Manhattan distance', 'B', 'Cosine similarity ignores the magnitude of the vectors, making it well suited to high-dimensional sparse text.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3704, 109, 'PCA reduces a dataset from 20 features to 5 components. What does this achieve?', 'it guarantees perfect classification', 'it removes all information', 'it increases the number of samples', 'it retains most of the variance in a lower-dimensional space', 'D', 'PCA keeps the directions of greatest variance, so 5 components can capture most of the information in the original 20 features.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3705, 109, 'What does a dendrogram represent in hierarchical clustering?', 'the tree of merge operations and the similarity levels at which clusters combine', 'the confusion matrix', 'the centroid positions', 'the eigen values only', 'A', 'A dendrogram records the sequence and distances of cluster merges, showing the hierarchy at all levels.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3706, 109, 'What does the silhouette score measure?', 'the number of clusters', 'the variance of each feature', 'how similar each point is to its own cluster compared to the nearest other cluster', 'the training accuracy', 'C', 'The silhouette score compares within-cluster cohesion to between-cluster separation for each point.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3707, 109, 'Which geometric assumption does k-means implicitly make about the clusters it finds?', 'clusters are always long and thin', 'clusters are roughly spherical and convex', 'clusters are always linear', 'clusters can have any shape', 'B', 'k-means assigns points to the nearest centroid, which produces spherical, convex, roughly equal-sized clusters.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3708, 109, 'After PCA, what is the correlation between two distinct principal components?', 'very high', '1', 'random', 'zero, because the components are orthogonal', 'D', 'Principal components are orthogonal by construction, so distinct components are uncorrelated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3709, 109, 'Why should features be scaled before applying k-means?', 'features with larger ranges would otherwise dominate the distance calculations', 'scaling is only needed for trees', 'scaling makes the data categorical', 'scaling always creates more clusters', 'A', 'k-means relies on distances, so unscaled large-range features would dominate the assignment of points to clusters.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3710, 109, 'In k-means with k = 3, a point is exactly equidistant from two centroids. What typically happens?', 'the point is discarded', 'it is assigned to one of the tied centroids by the tie-breaking rule', 'k is increased', 'the algorithm stops', 'B', 'Ties are broken deterministically, so the point is simply assigned to one of the equally close centroids.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3711, 109, 'A k-means model is run on customer data containing strong outliers. What is the most likely problem?', 'the outliers drag the centroids toward them, distorting the clusters', 'the outliers make the model a regression', 'the outliers are ignored completely', 'the outliers always form their own perfect cluster', 'A', 'Because k-means uses means, distant outliers pull centroids away from the main data and distort the clusters.', 'ADVANCED', 3, 'MCQ', 1),
(3712, 109, 'A scientist needs to visualize a high-dimensional dataset in 2D for exploratory analysis. Which choice is most appropriate?', 'PCA always, because it is fastest', 't-SNE for revealing local structure, while PCA captures global variance', 'k-means for visualization', 'a decision tree for visualization', 'B', 't-SNE reveals local groupings in 2D, while PCA preserves global variance, and the choice depends on which structure matters.', 'ADVANCED', 3, 'MCQ', 1),
(3713, 109, 'Compared with PCA, when would an autoencoder be a better dimensionality-reduction choice?', 'never, PCA is always better', 'when the data is small', 'when the underlying data has nonlinear structure that linear projections miss', 'when labels are present', 'C', 'Autoencoders learn nonlinear transformations, so they can capture structure that linear PCA cannot.', 'ADVANCED', 3, 'MCQ', 1),
(3714, 109, 'Data arrives as a continuous stream and must be clustered online. Which approach is most suitable?', 'recompute k-means from scratch every second', 'use a one-time PCA', 'train a decision tree', 'use an incremental method such as mini-batch k-means', 'D', 'Mini-batch k-means updates centroids incrementally as new batches arrive, which suits streaming data.', 'ADVANCED', 3, 'MCQ', 1),
(3715, 109, 'What problem does k-means++ initialization specifically address?', 'the sensitivity of k-means to poor initial centroid placement', 'the slow speed of Euclidean distance', 'the lack of labels', 'the need for feature scaling', 'A', 'k-means++ spreads out the initial centroids, which reduces the chance of converging to a poor local optimum.', 'ADVANCED', 3, 'MCQ', 1),
(3716, 109, 'The explained variance ratio of a PCA component tells you what?', 'the number of components', 'the proportion of total variance in the data that the component captures', 'the number of clusters', 'the accuracy of a classifier', 'B', 'Each component ratio reports how much of the total variance of the dataset that component accounts for.', 'ADVANCED', 3, 'MCQ', 1),
(3717, 109, 'What is a key advantage of DBSCAN over k-means?', 'it always runs faster', 'it requires the number of clusters', 'it can discover clusters of arbitrary shape and label points as noise', 'it never needs a distance metric', 'C', 'DBSCAN grows clusters from dense regions, so it handles arbitrary shapes and flags sparse points as noise.', 'ADVANCED', 3, 'MCQ', 1),
(3718, 109, 'In very high-dimensional spaces, distance-based clustering often fails. Which effect describes this best?', 'the elbow method', 'the bootstrap effect', 'the silhouette effect', 'distance concentration, where all pairwise distances become nearly equal', 'D', 'In high dimensions pairwise distances converge to similar values, so distance-based separation becomes unreliable.', 'ADVANCED', 3, 'MCQ', 1),
(3719, 109, 'A dataset has no ground-truth labels, yet a team must judge whether clustering results are good. Which type of metric should they use?', 'an internal metric such as the silhouette score', 'accuracy', 'precision and recall', 'the R-squared value', 'A', 'Internal metrics like the silhouette score evaluate clustering quality using only the data itself when no labels exist.', 'ADVANCED', 3, 'MCQ', 1),
(3720, 109, 'A dataset contains nested groups that are themselves grouped. Which approach best reveals the structure at multiple levels?', 'a single k-means run', 'logistic regression', 'hierarchical clustering and cutting the dendrogram at different levels', 'a random forest', 'C', 'Hierarchical clustering builds a tree of merges, so cutting the dendrogram at different heights reveals nested groupings.', 'ADVANCED', 3, 'MCQ', 1),
(3721, 110, 'What is overfitting in machine learning?', 'the model learns the training data so well that it fails to generalize to new data', 'the model is too simple to learn the data', 'the model ignores all features', 'the model has no parameters', 'A', 'Overfitting means the model captures noise in the training set and performs poorly on unseen data.', 'BEGINNER', 1, 'MCQ', 1),
(3722, 110, 'What is underfitting?', 'the model memorizes the training set', 'the model has too many parameters', 'the model is too simple to capture the underlying pattern and performs poorly on training and test data', 'the model always predicts the majority class', 'C', 'Underfitting happens when the model is too simple to learn even the training data, so it performs poorly everywhere.', 'BEGINNER', 1, 'MCQ', 1),
(3723, 110, 'What is the purpose of a test set?', 'to train the model', 'to estimate how well the model generalizes to unseen data', 'to tune hyperparameters only', 'to build features', 'B', 'The test set is held out during training and is used to estimate how well the model performs on new data.', 'BEGINNER', 1, 'MCQ', 1),
(3724, 110, 'In binary classification, what does the accuracy metric measure?', 'the number of false positives', 'the number of features', 'the training loss', 'the proportion of all predictions that were correct', 'D', 'Accuracy is the fraction of all predictions that matched the true labels.', 'BEGINNER', 1, 'MCQ', 1),
(3725, 110, 'What does precision measure in a binary classifier?', 'of the samples predicted positive, how many truly are positive', 'of the positive samples, how many were found', 'the number of negative samples', 'the training speed', 'A', 'Precision is the ratio of true positives to all samples predicted as positive, showing how trustworthy positive predictions are.', 'BEGINNER', 1, 'MCQ', 1),
(3726, 110, 'What does recall (sensitivity) measure?', 'of the predicted positives, how many are correct', 'the accuracy', 'of the actual positive samples, how many the model found', 'the number of false positives', 'C', 'Recall is the fraction of actual positive samples that the model successfully identified.', 'BEGINNER', 1, 'MCQ', 1),
(3727, 110, 'What is a confusion matrix?', 'a table of features', 'a table showing counts of predicted versus actual classes', 'a list of hyperparameters', 'a plot of the loss curve', 'B', 'A confusion matrix tabulates predicted classes against actual classes, revealing where the model confuses classes.', 'BEGINNER', 1, 'MCQ', 1),
(3728, 110, 'What is k-fold cross-validation?', 'training on the full dataset only', 'a regularization method', 'a feature selection method', 'splitting data into k folds and training k times, validating on a different fold each time', 'D', 'k-fold cross-validation trains k times, each time holding out a different fold for validation.', 'BEGINNER', 1, 'MCQ', 1),
(3729, 110, 'What is the purpose of a validation set?', 'to tune hyperparameters and select between models during development', 'to report the final accuracy', 'to store unused data', 'to be used only at prediction time', 'A', 'The validation set is used during development to tune hyperparameters and compare candidate models.', 'BEGINNER', 1, 'MCQ', 1),
(3730, 110, 'Which situation is a classic sign of overfitting?', 'high training error and high test error', 'very high training accuracy but much lower test accuracy', 'equal train and test error', 'a model that never improves', 'B', 'A large gap between high training accuracy and lower test accuracy is the classic signature of overfitting.', 'BEGINNER', 1, 'MCQ', 1),
(3731, 110, 'A classifier makes 90 correct predictions out of 100 total predictions. What is its accuracy?', '90 percent', '10 percent', '100 percent', '50 percent', 'A', 'Accuracy is the ratio of correct predictions to total predictions, which is 90 / 100 = 90 percent.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3732, 110, 'A logistic regression model decision threshold is raised from 0.5 to 0.8. What is the typical effect on recall?', 'recall increases', 'recall decreases because fewer samples are classified as positive', 'recall stays the same', 'recall becomes negative', 'B', 'A higher threshold means fewer positive predictions, so fewer true positives are found and recall drops.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3733, 110, 'A model scores 99 percent accuracy on its training set but 70 percent on a held-out test set. What is most likely happening?', 'underfitting', 'the model is perfect', 'overfitting', 'the test set is corrupted beyond repair', 'C', 'The large drop from training to test accuracy indicates the model memorized the training set and failed to generalize.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3734, 110, 'A classifier has precision 0.8 and recall 0.8. What is its F1 score?', '0.64', '1.6', '0.4', '0.8', 'D', 'The F1 score is the harmonic mean, computed as 2 * 0.8 * 0.8 / (0.8 + 0.8) = 0.8.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3735, 110, 'With 5-fold cross-validation, how many times does each training sample appear in a validation set?', 'exactly once', 'five times', 'never', 'twice', 'A', 'Each sample falls in exactly one of the five folds, so it is used for validation exactly once.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3736, 110, 'What does the ROC curve plot?', 'precision against recall', 'true positive rate against false positive rate across thresholds', 'accuracy against epoch', 'loss against learning rate', 'B', 'The ROC curve shows the tradeoff between true positive rate and false positive rate as the threshold varies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3737, 110, 'A binary classifier has 50 true positives and 10 false positives. What is its precision?', '50 percent', '10 percent', 'approximately 83 percent', '100 percent', 'C', 'Precision is 50 / (50 + 10) = 50 / 60, which is approximately 83 percent.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3738, 110, 'A binary classifier has 50 true positives and 10 false negatives. What is its recall?', '10 percent', '50 percent', '100 percent', 'approximately 83 percent', 'D', 'Recall is 50 / (50 + 10) = 50 / 60, which is approximately 83 percent.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3739, 110, 'For a perfectly balanced binary classification problem, what is the expected accuracy of a model that guesses randomly?', '50 percent', '100 percent', '25 percent', '75 percent', 'A', 'With two balanced classes, random guessing is correct about half the time, giving roughly 50 percent accuracy.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3740, 110, 'Which change is most likely to reduce overfitting in a high-capacity model?', 'add more training epochs', 'remove the test set', 'apply regularization or increase the amount of training data', 'increase model complexity', 'C', 'Regularization constrains the model and more data gives it real signal, both of which reduce overfitting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3741, 110, 'In a dataset where only 1 percent of transactions are fraudulent, a model that always predicts not fraud achieves 99 percent accuracy. Why is this misleading?', 'accuracy is the only valid metric', 'the model is clearly perfect', 'the confusion matrix is empty', 'accuracy ignores class imbalance, so precision, recall and AUC should be used', 'D', 'With extreme class imbalance accuracy is misleading, so metrics that focus on the minority class are needed.', 'ADVANCED', 3, 'MCQ', 1),
(3742, 110, 'When evaluating a time-series forecasting model, why should random k-fold cross-validation be avoided?', 'k-fold is always the best choice', 'time series has no labels', 'random splits leak future information into training, so time-based or forward-chaining splits are needed', 'k-fold only works for classification', 'C', 'Random splits put future data into training folds, leaking information, so time-aware splits must be used.', 'ADVANCED', 3, 'MCQ', 1),
(3743, 110, 'A feature engineering step uses the target variable to fill in missing values before splitting the data. What has been introduced?', 'a better model', 'data leakage that inflates the reported performance', 'noise reduction', 'a larger test set', 'B', 'Using target information when creating features leaks knowledge into the model and inflates its measured performance.', 'ADVANCED', 3, 'MCQ', 1),
(3744, 110, 'An interviewer asks about the difference between a validation set and a test set. What is the best answer?', 'the validation set guides model selection and hyperparameter tuning, while the test set gives the final unbiased estimate of generalization', 'they are the same thing', 'the test set is used for tuning', 'the validation set reports the final accuracy', 'A', 'Validation guides model development, while the untouched test set provides the final unbiased performance estimate.', 'ADVANCED', 3, 'MCQ', 1),
(3745, 110, 'A project has only 200 labeled samples and must estimate model quality. Which validation strategy is most appropriate?', 'a single fixed train-test split', 'hold out 80 percent as test', 'use only the training accuracy', 'leave-one-out or repeated k-fold cross-validation to use the small data efficiently', 'D', 'With so few samples, leave-one-out or repeated k-fold makes the most of the data instead of wasting a large held-out chunk.', 'ADVANCED', 3, 'MCQ', 1),
(3746, 110, 'During training, validation loss decreases then begins to rise while training loss keeps falling. What is happening?', 'the model is underfitting', 'the learning rate is too low', 'the model is overfitting, and early stopping on validation loss is warranted', 'the data is corrupted', 'C', 'Falling training loss with rising validation loss means the model is overfitting, so training should stop at the best validation point.', 'ADVANCED', 3, 'MCQ', 1),
(3747, 110, 'Which statement correctly describes the bias-variance tradeoff?', 'high bias models overfit', 'a high-variance model tends to overfit while a high-bias model tends to underfit', 'bias and variance are unrelated', 'variance is always zero', 'B', 'High variance corresponds to overfitting and high bias to underfitting, and the two must be balanced.', 'ADVANCED', 3, 'MCQ', 1),
(3748, 110, 'What is a distinctive property of L1 (lasso) regularization compared with L2?', 'L1 pushes many coefficients to exactly zero, producing sparse models', 'L1 never changes the coefficients', 'L1 only works on trees', 'L1 increases variance', 'A', 'The L1 penalty forces many coefficients to exactly zero, which performs feature selection and yields sparse models.', 'ADVANCED', 3, 'MCQ', 1),
(3749, 110, 'Early stopping is applied to a gradient boosting model. When should training be stopped?', 'never', 'after a fixed number of features', 'when training loss reaches zero', 'as soon as the validation metric stops improving and starts degrading', 'D', 'Training should halt when the validation metric peaks, because further boosting only overfits.', 'ADVANCED', 3, 'MCQ', 1),
(3750, 110, 'For a multiclass problem with 5 classes, what does the confusion matrix look like?', 'a 2 by 2 table', 'a 5 by 5 table showing predicted versus actual counts for all class pairs', 'a single number', 'a vector of length 5', 'B', 'A multiclass confusion matrix is a table of size classes by classes, comparing every predicted and actual class pair.', 'ADVANCED', 3, 'MCQ', 1),
(3751, 111, 'What is the fundamental processing unit of a neural network called?', 'neuron', 'weight', 'kernel', 'loss', 'A', 'A neuron is the basic computational unit that combines its inputs and produces an output.', 'BEGINNER', 1, 'MCQ', 1),
(3752, 111, 'Which value determines the strength of the connection between two neurons?', 'bias', 'weight', 'activation', 'loss', 'B', 'Weights scale the input signals before they are summed inside a neuron, so they determine connection strength.', 'BEGINNER', 1, 'MCQ', 1),
(3753, 111, 'Which parameter lets a neuron shift its decision boundary without depending on any input?', 'learning rate', 'bias', 'momentum', 'epoch', 'C', 'The bias adds a constant offset so the neuron can activate even when all inputs are zero.', 'BEGINNER', 1, 'MCQ', 1),
(3754, 111, 'Which layer of a neural network receives the raw input data?', 'hidden layer', 'output layer', 'input layer', 'loss layer', 'D', 'The input layer holds the raw features that are fed into the network.', 'BEGINNER', 1, 'MCQ', 1),
(3755, 111, 'Why does a neural network need a nonlinear activation function?', 'to learn complex nonlinear relationships between inputs and outputs', 'to make the network run faster', 'to reduce the number of parameters', 'to initialize all weights to zero', 'A', 'Without nonlinearity, stacked linear layers would collapse into a single linear transformation, limiting the model.', 'BEGINNER', 1, 'MCQ', 1),
(3756, 111, 'Which layers of a network learn intermediate representations of the data?', 'input layers', 'hidden layers', 'loss layers', 'label layers', 'B', 'Hidden layers sit between input and output and transform the data into progressively more abstract features.', 'BEGINNER', 1, 'MCQ', 1),
(3757, 111, 'What does the learning rate control during gradient descent?', 'the number of layers in the network', 'the size of the dataset', 'how large a step the weights take with each update', 'the number of output classes', 'C', 'The learning rate scales the gradient update, so a large rate takes big steps and a small rate takes small steps.', 'BEGINNER', 1, 'MCQ', 1),
(3758, 111, 'What is one complete pass through the entire training dataset called?', 'batch', 'iteration', 'epoch', 'gradient', 'D', 'An epoch is one full traversal of the training data, typically split into multiple batches.', 'BEGINNER', 1, 'MCQ', 1),
(3759, 111, 'What is a group of training examples processed together before updating the weights called?', 'a batch', 'an epoch', 'a weight', 'a feature', 'A', 'A batch is a fixed number of samples whose gradients are aggregated into a single weight update.', 'BEGINNER', 1, 'MCQ', 1),
(3760, 111, 'What does the loss function quantify during training?', 'the number of epochs', 'how far the model predictions are from the true targets', 'the learning rate', 'the size of the hidden layer', 'B', 'The loss is a scalar that measures the discrepancy between predictions and ground-truth labels.', 'BEGINNER', 1, 'MCQ', 1),
(3761, 111, 'A perceptron computes a weighted sum of its inputs and passes the result through a step function. What kind of model is this structure?', 'a linear classifier', 'a nonlinear regression model', 'a convolutional network', 'a recurrent network', 'A', 'A single perceptron can only separate classes with a hyperplane, so it is a linear classifier.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3762, 111, 'Consider a single neuron with weights 2 and 3, inputs 1 and 2, and bias 0. What is its weighted sum before activation?', '5', '8', '6', '9', 'B', 'The weighted sum is 2 times 1 plus 3 times 2 plus 0, which equals 8.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3763, 111, 'A neuron has a weighted sum of 0.7 and a sigmoid activation. Approximately what is its output?', '0.5', '1.0', '0.67', '0.0', 'C', 'sigmoid(0.7) is about 0.668, which rounds to 0.67.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3764, 111, 'If the learning rate is set too high, what is a common consequence during training?', 'training converges faster reliably', 'the loss decreases monotonically', 'the weights grow slowly', 'the loss may oscillate or diverge', 'D', 'An oversized learning rate makes gradient steps overshoot the minimum, causing oscillation or divergence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3765, 111, 'Given a weight of 0.5, a gradient of -0.4, and a learning rate of 0.1, what is the updated weight?', '0.54', '0.46', '0.9', '0.1', 'A', 'The update rule w = w - lr * gradient gives 0.5 - 0.1 * (-0.4) = 0.54.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3766, 111, 'Which statement about a model that underfits the training data is true?', 'it memorizes the training set', 'it performs well on the training set but poorly on new data', 'it fails to capture even the patterns in the training data', 'it has low bias', 'B', 'Underfitting means the model is too simple to learn the training patterns themselves.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3767, 111, 'Which statement about a model that overfits is true?', 'it generalizes better than underfit models', 'it captures noise in the training data', 'it performs well on training data but poorly on unseen data', 'it has high bias and low variance', 'C', 'Overfitting is when the model memorizes training noise and therefore generalizes poorly to new data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3768, 111, 'Which rule updates a weight w given its gradient dL/dw and learning rate lr?', 'w = w + lr * (dL/dw)', 'w = lr * (dL/dw)', 'w = w - (dL/dw)', 'w = w - lr * (dL/dw)', 'D', 'Gradient descent moves the weight opposite to the gradient, giving w = w - lr * (dL/dw).', 'INTERMEDIATE', 2, 'MCQ', 1),
(3769, 111, 'A network has 3 input features, a hidden layer of 4 neurons, and 2 output neurons. How many weights connect the input to the hidden layer?', '12', '8', '6', '24', 'A', 'Each of the 4 hidden neurons receives 3 inputs, so there are 3 times 4 = 12 weights.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3770, 111, 'What does a softmax activation function produce at the output layer?', 'a single real value', 'a probability distribution over the classes', 'a fixed binary decision', 'the raw weighted sum', 'B', 'Softmax converts the output scores into nonnegative values that sum to one, forming a probability distribution.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3771, 111, 'A deep network minimizes loss on training data but fails badly on validation data. How is this best described?', 'overfitting', 'underfitting', 'converged', 'regularized', 'A', 'Performing well on training data while generalizing poorly is the classic signature of overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3772, 111, 'Which technique reduces overfitting by randomly dropping neurons during each training iteration?', 'batch normalization', 'dropout', 'gradient clipping', 'data augmentation', 'B', 'Dropout randomly zeroes a fraction of neurons each pass, forcing the network to learn redundant representations.', 'ADVANCED', 3, 'MCQ', 1),
(3773, 111, 'In the context of a single-layer perceptron, which statement about the XOR problem is true?', 'XOR is linearly separable and solvable', 'XOR can be solved by any perceptron', 'XOR is not linearly separable and cannot be solved by a single perceptron', 'XOR requires no activation function', 'C', 'XOR''s classes cannot be separated by a single hyperplane, so a single perceptron cannot solve it.', 'ADVANCED', 3, 'MCQ', 1),
(3774, 111, 'What is the main purpose of batch normalization in a deep network?', 'to increase the learning rate by normalizing layer inputs', 'to reduce the dataset size', 'to replace the activation function', 'to remove all biases', 'D', 'Batch normalization normalizes each layer''s activations, which stabilizes and speeds up training.', 'ADVANCED', 3, 'MCQ', 1),
(3775, 111, 'Which problem does gradient descent face when the loss surface contains many local minima and plateaus?', 'the optimizer may get stuck in a poor local minimum', 'the loss always reaches zero', 'the weights become integers', 'the network loses its hidden layers', 'A', 'Saddle points and local minima can trap gradient descent away from the global optimum.', 'ADVANCED', 3, 'MCQ', 1),
(3776, 111, 'A model has very high bias and low variance. Which condition is it most likely in?', 'overfit', 'underfit', 'perfectly calibrated', 'variance-optimal', 'B', 'High bias and low variance indicate a too-simple model that underfits the data.', 'ADVANCED', 3, 'MCQ', 1),
(3777, 111, 'Why does deep learning commonly require large amounts of labeled data?', 'because networks have no parameters', 'because all models are supervised', 'because deep networks have many parameters that must be learned from examples', 'because data is free', 'C', 'The large number of parameters in deep models needs many examples to be fit without severe overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3778, 111, 'Which statement about the vanishing gradient problem in very deep networks is correct?', 'gradients always grow without bound', 'it is solved by removing all nonlinearities', 'gradients become extremely small in early layers, slowing learning', 'it only affects single-layer networks', 'D', 'Repeated multiplication of small derivatives shrinks gradients so early layers learn very slowly.', 'ADVANCED', 3, 'MCQ', 1),
(3779, 111, 'A model performs well on training data but poorly on test data. Which approach most directly addresses the issue?', 'adding dropout or regularization to reduce overfitting', 'increasing the number of epochs', 'removing the hidden layers', 'increasing the learning rate', 'A', 'Regularization and dropout directly combat overfitting by constraining model complexity.', 'ADVANCED', 3, 'MCQ', 1),
(3780, 111, 'Which of the following is a transfer learning strategy for image classification?', 'train from scratch on every new task', 'use a pretrained backbone and fine-tune only the final layers', 'remove the activation functions', 'halve the learning rate for every epoch automatically', 'B', 'Transfer learning reuses features learned on a large dataset and adapts a pretrained model to a new task.', 'ADVANCED', 3, 'MCQ', 1),
(3781, 112, 'What is backpropagation used for in a neural network?', 'to compute the gradient of the loss with respect to the weights', 'to store the training data', 'to initialize the weights', 'to load the model', 'A', 'Backpropagation efficiently computes how each weight contributes to the loss so the weights can be updated.', 'BEGINNER', 1, 'MCQ', 1),
(3782, 112, 'Which mathematical rule is the basis of the chain of gradient computations in backpropagation?', 'the chain rule', 'the product rule for counting', 'Bayes theorem', 'the binomial theorem', 'B', 'Backpropagation applies the chain rule to propagate error derivatives backward through the layers.', 'BEGINNER', 1, 'MCQ', 1),
(3783, 112, 'What does the derivative of the loss with respect to a weight represent?', 'the weight itself', 'the number of training examples', 'how much a small change in that weight changes the loss', 'the activation value', 'C', 'The gradient measures the sensitivity of the loss to that weight, guiding the update direction.', 'BEGINNER', 1, 'MCQ', 1),
(3784, 112, 'During the backward pass, in which order are gradients computed through the layers?', 'input to output', 'output to input', 'random order', 'all at once', 'D', 'Gradients propagate from the output layer back toward the input layer.', 'BEGINNER', 1, 'MCQ', 1),
(3785, 112, 'Which activation function squashes its input to a value between 0 and 1?', 'sigmoid', 'ReLU', 'softmax', 'tanh', 'A', 'The sigmoid function maps any real input into the interval (0, 1).', 'BEGINNER', 1, 'MCQ', 1),
(3786, 112, 'Which activation function outputs the input directly for positive values and zero for negative values?', 'sigmoid', 'ReLU', 'tanh', 'leaky ReLU with large slope', 'B', 'ReLU returns x when x is positive and 0 otherwise.', 'BEGINNER', 1, 'MCQ', 1),
(3787, 112, 'Which activation function squashes values to the range -1 to 1?', 'sigmoid', 'ReLU', 'tanh', 'step', 'C', 'The hyperbolic tangent (tanh) maps inputs to the interval (-1, 1).', 'BEGINNER', 1, 'MCQ', 1),
(3788, 112, 'What is the main benefit of the ReLU activation compared with sigmoid?', 'it is always negative', 'it cannot be computed', 'it avoids exponential operations and mitigates vanishing gradients for positive inputs', 'it is a probabilistic function', 'D', 'ReLU is cheap to compute and has a constant gradient of 1 for positive inputs, avoiding saturation.', 'BEGINNER', 1, 'MCQ', 1),
(3789, 112, 'What problem does the sigmoid activation often cause in deep networks?', 'vanishing gradients', 'exploding gradients only', 'too fast convergence', 'zero parameters', 'A', 'Sigmoid saturates at large magnitudes, making its derivative near zero and shrinking gradients through layers.', 'BEGINNER', 1, 'MCQ', 1),
(3790, 112, 'What does the softmax activation compute?', 'a single binary output', 'probabilities that sum to one across the output classes', 'the average of all inputs', 'the maximum value', 'B', 'Softmax turns a vector of scores into a probability distribution over classes.', 'BEGINNER', 1, 'MCQ', 1),
(3791, 112, 'What is the derivative of ReLU at x = 5?', '1', '0', '5', 'undefined', 'A', 'For any positive input, the derivative of ReLU is 1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3792, 112, 'What is the derivative of ReLU at x = -2?', '1', '0', '-2', 'undefined', 'B', 'For negative inputs ReLU outputs 0 and its derivative is 0.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3793, 112, 'What is the derivative of the sigmoid function at x = 0?', '0', '1', '0.25', '0.5', 'C', 'sigmoid(0) is 0.5, and its derivative is sigmoid times (1 - sigmoid), which equals 0.25.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3794, 112, 'For a linear layer y = Wx + b, what is the derivative of the loss with respect to the weights W given the upstream gradient dL/dy?', 'dL/dy', 'dL/dy * x^T', 'dL/dy * W', 'x^T * W', 'D', 'For y = Wx + b, the gradient with respect to W is the upstream gradient dL/dy multiplied by the transpose of x.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3795, 112, 'A hidden neuron uses sigmoid and its pre-activation value is 0. What local gradient is passed on during the backward pass?', '0.25', '0.5', '1', '0', 'A', 'With sigmoid the local gradient is sigmoid(0) times (1 - sigmoid(0)), which is 0.5 * 0.5 = 0.25.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3796, 112, 'Which problem does the leaky ReLU activation specifically aim to fix in standard ReLU?', 'exploding gradients', 'dying ReLU, where many neurons output zero permanently', 'slow matrix multiplication', 'sigmoid saturation', 'B', 'Leaky ReLU gives negative inputs a small slope so those neurons keep receiving gradients.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3797, 112, 'Why is cross-entropy loss often paired with a softmax output layer?', 'it always returns zero', 'it cancels the exponential in softmax, giving stable gradients', 'it ignores the labels', 'it makes the network linear', 'C', 'The combination of softmax and cross-entropy simplifies to a numerically stable form whose gradient is just the prediction minus the one-hot target.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3798, 112, 'In a neural network, what does the derivative of the loss with respect to an activation represent?', 'a weight', 'the learning rate', 'the number of epochs', 'how much the loss changes when that activation changes', 'D', 'The upstream gradient measures the sensitivity of the loss to the activation, which is propagated further back.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3799, 112, 'Which condition makes the gradient of tanh close to zero?', 'when the input magnitude is large, saturating the function', 'when the input is exactly zero', 'when the learning rate is high', 'when the batch is small', 'A', 'tanh saturates at large positive or negative inputs, making its derivative approach zero.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3800, 112, 'For a ReLU neuron that always receives negative inputs, what is the effect on its weights during training?', 'they update normally', 'the gradient is always zero, so the neuron stops learning', 'they double in value', 'the neuron becomes the output', 'B', 'If the neuron is always inactive, its ReLU derivative is 0 and no gradient flows to its weights.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3801, 112, 'In the cross-entropy plus softmax combination, what is the gradient of the loss with respect to the logits?', 'softmax output minus one-hot target', 'softmax output plus the target', 'the raw logits', 'one-hot target minus softmax output', 'A', 'The elegant result is dL/dz = softmax(z) - y, which is both simple and numerically stable.', 'ADVANCED', 3, 'MCQ', 1),
(3802, 112, 'Which technique mitigates vanishing gradients in very deep networks by preserving a near-unit gradient path?', 'random weight initialization only', 'residual connections that add the layer input to its output', 'removing all biases', 'reducing the batch size', 'B', 'Residual (skip) connections let gradients flow around layers, which supports very deep training.', 'ADVANCED', 3, 'MCQ', 1),
(3803, 112, 'Which initializer is commonly chosen for ReLU networks to prevent vanishing or exploding activations?', 'He initialization', 'zeros', 'constant initialization', 'random labels', 'C', 'He initialization scales weights based on the fan-in so ReLU activations keep a healthy variance.', 'ADVANCED', 3, 'MCQ', 1),
(3804, 112, 'What is the purpose of gradient clipping during training of deep networks?', 'to increase the learning rate', 'to delete parameters', 'to prevent the weights from becoming too small', 'to cap the gradient magnitude and avoid exploding updates', 'D', 'Clipping rescales gradients that exceed a threshold, preventing huge updates from destabilizing training.', 'ADVANCED', 3, 'MCQ', 1),
(3805, 112, 'Why is a plain sigmoid activation generally discouraged in the hidden layers of very deep networks?', 'its saturated derivative causes vanishing gradients', 'it is cheaper than ReLU', 'it guarantees faster convergence', 'it has no derivative', 'A', 'Sigmoid''s derivative becomes vanishingly small when activations saturate, starving early layers of gradient.', 'ADVANCED', 3, 'MCQ', 1),
(3806, 112, 'A regression network uses a linear output activation with mean squared error loss. What does the gradient with respect to the output equal, up to scaling?', 'the prediction plus the target', 'the prediction minus the target', 'the sigmoid of the prediction', 'the squared prediction', 'B', 'For mean squared error, the derivative is 2 times (prediction minus target).', 'ADVANCED', 3, 'MCQ', 1),
(3807, 112, 'During backpropagation through a skip connection, how is the gradient for the earlier layer computed?', 'only through the skip', 'only through the main path', 'as the sum of the gradients along both the main path and the skip connection', 'as the product of the two paths', 'C', 'The add node in a residual block splits the incoming gradient equally across both branches, so they sum.', 'ADVANCED', 3, 'MCQ', 1),
(3808, 112, 'Which statement about the vanishing gradient problem and activation functions is correct?', 'ReLU eliminates all gradient issues', 'saturating activations like sigmoid and tanh contribute to vanishing gradients in deep networks', 'activation functions do not affect gradients', 'vanishing gradients only occur at the output layer', 'D', 'Saturated activations shrink the local derivatives, and their repeated multiplication causes vanishing gradients.', 'ADVANCED', 3, 'MCQ', 1),
(3809, 112, 'An engineer notices that a very deep ReLU network has exploding loss values. Which technique is most appropriate to address the issue?', 'gradient clipping to limit update magnitudes', 'removing the activation functions', 'using a larger batch', 'increasing the number of layers', 'A', 'Exploding updates are handled by capping gradient norms, which stabilizes training.', 'ADVANCED', 3, 'MCQ', 1),
(3810, 112, 'Why is softmax a poor choice for a hidden layer activation compared with ReLU?', 'it is faster to compute', 'its output is coupled across neurons and it can cause saturation and vanishing gradients', 'it always produces negative values', 'it has no gradient', 'B', 'Softmax normalizes across a layer, making individual neuron outputs interdependent and introducing saturation issues.', 'ADVANCED', 3, 'MCQ', 1),
(3811, 113, 'What type of layer is the core building block of a CNN for extracting local features from images?', 'convolutional layer', 'fully connected layer', 'dropout layer', 'embedding layer', 'A', 'Convolutional layers apply filters across the image to detect local patterns such as edges.', 'BEGINNER', 1, 'MCQ', 1),
(3812, 113, 'What is a filter (or kernel) in a convolutional layer?', 'a pooling operation', 'a small grid of weights slid across the input', 'the output image', 'a loss function', 'B', 'A kernel is a small weight matrix that slides over the input to produce feature maps.', 'BEGINNER', 1, 'MCQ', 1),
(3813, 113, 'Which operation does a convolutional layer perform between the input and the filter?', 'matrix inversion', 'elementwise division', 'a sliding dot product (convolution or correlation)', 'random shuffling', 'C', 'The filter is multiplied elementwise with each input patch and summed, giving a scalar response per location.', 'BEGINNER', 1, 'MCQ', 1),
(3814, 113, 'What does the stride of a convolution control?', 'the number of filters', 'the activation function', 'the padding value', 'how many pixels the filter moves at each step', 'D', 'The stride sets the step size of the sliding window, affecting the output spatial size.', 'BEGINNER', 1, 'MCQ', 1),
(3815, 113, 'What is zero padding in a convolution used for?', 'to preserve the spatial dimensions of the feature map', 'to increase the number of filters', 'to add more classes', 'to slow down training', 'A', 'Zero padding surrounds the input with zeros so the output can keep the same height and width.', 'BEGINNER', 1, 'MCQ', 1),
(3816, 113, 'What is the purpose of a pooling layer in a CNN?', 'to add more parameters', 'to downsample the feature map and add translation invariance', 'to compute the loss', 'to initialize filters', 'B', 'Pooling reduces spatial resolution and makes features more robust to small shifts.', 'BEGINNER', 1, 'MCQ', 1),
(3817, 113, 'Which pooling operation returns the maximum value in each window?', 'average pooling', 'min pooling', 'max pooling', 'global normalization', 'C', 'Max pooling takes the largest value inside each window of the feature map.', 'BEGINNER', 1, 'MCQ', 1),
(3818, 113, 'Which type of layer is usually placed at the end of a CNN to produce class scores?', 'convolutional layer', 'pooling layer', 'activation layer', 'fully connected layer', 'D', 'The fully connected layer flattens the feature maps and maps them to the output classes.', 'BEGINNER', 1, 'MCQ', 1),
(3819, 113, 'What is a feature map in a CNN?', 'the output of a convolution, capturing the response to a particular filter', 'the input image', 'the loss curve', 'the weight initializer', 'A', 'Each filter produces a feature map highlighting where its learned pattern appears in the input.', 'BEGINNER', 1, 'MCQ', 1),
(3820, 113, 'How many parameters does a single 3x3 filter have, ignoring the bias?', '9', '3', '6', '27', 'B', 'A 3x3 filter has 3 times 3 = 9 weights.', 'BEGINNER', 1, 'MCQ', 1),
(3821, 113, 'An input of size 32x32 is convolved with ten 3x3 filters, stride 1 and no padding. What is the spatial size of the resulting feature maps?', '30x30', '32x32', '31x31', '34x34', 'A', 'With padding 0 and stride 1, the output size is 32 - 3 + 1 = 30 on each side.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3822, 113, 'An input of size 32x32 is convolved with 3x3 filters, stride 1 and padding 1. What is the output size?', '30x30', '32x32', '31x31', '34x34', 'B', 'With padding 1, the output size is (32 + 2*1 - 3) / 1 + 1 = 32, preserving the spatial size.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3823, 113, 'An input of size 28x28 is convolved with a 5x5 filter, stride 1 and no padding. What is the output size?', '28x28', '27x27', '24x24', '26x26', 'C', 'The output is 28 - 5 + 1 = 24 on each side.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3824, 113, 'An input of size 16x16 is processed by 2x2 max pooling with stride 2. What is the output size?', '16x16', '10x10', '14x14', '8x8', 'D', 'Max pooling with a 2x2 window and stride 2 halves the dimensions to 8x8.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3825, 113, 'An input has 32 channels and is processed by a 1x1 convolution with 64 filters. How many channels does the output have?', '64', '32', '1', '96', 'A', 'The number of filters determines the output channel count, so it is 64.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3826, 113, 'Which statement about parameter sharing in a CNN is correct?', 'each input pixel gets a unique weight', 'the same filter weights are shared across all spatial positions', 'filters are shared only across color channels', 'there is no sharing in CNNs', 'B', 'A single filter slides across the entire input, reusing the same weights everywhere and cutting the parameter count.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3827, 113, 'Which statement about a 1x1 convolution is correct?', 'it has no effect', 'it only changes spatial size', 'it performs channel mixing with a weighted combination of input channels', 'it replaces pooling', 'C', 'A 1x1 convolution combines information across channels at each spatial location, changing the channel dimension.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3828, 113, 'An input of size 6x6 is processed by a 3x3 filter with stride 2 and no padding. What is the output size?', '3x3', '4x4', '2x2', '5x5', 'D', 'The output is floor((6 - 3) / 2) + 1 = 2, giving a 2x2 map.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3829, 113, 'What is the receptive field of a single neuron in the first convolutional layer that uses 3x3 filters?', '3x3', '1x1', '6x6', '9x9', 'A', 'Each neuron in the first layer sees a 3x3 patch of the input, which is its receptive field.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3830, 113, 'Which of the following best describes how the early layers of a CNN typically behave after training on images?', 'they detect class labels', 'they detect low-level features such as edges and colors', 'they compute the loss', 'they act as output layers', 'B', 'Early layers learn simple features like edges and gradients, while deeper layers learn more abstract patterns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3831, 113, 'For a modern deep CNN classifier with limited data, which strategy is most effective for reducing overfitting?', 'data augmentation plus dropout and regularization', 'removing the pooling layers', 'increasing the number of filters', 'using only fully connected layers', 'A', 'Augmentation and regularization directly combat overfitting with limited data.', 'ADVANCED', 3, 'MCQ', 1),
(3832, 113, 'Why did VGG-style networks replace large 7x7 filters with stacks of 3x3 filters?', '3x3 filters are easier to visualize', 'several 3x3 layers give a large receptive field with fewer parameters and more nonlinearity', '3x3 filters remove the need for padding', 'they speed up data loading', 'B', 'Two stacked 3x3 layers have the receptive field of a 5x5 filter but use fewer parameters and add nonlinearity.', 'ADVANCED', 3, 'MCQ', 1),
(3833, 113, 'What is the purpose of global average pooling before the classification head of a CNN?', 'to add fully connected parameters', 'to compress each feature map to a single value, reducing parameters and overfitting', 'to double the resolution', 'to perform the convolution', 'C', 'Global average pooling averages each feature map into one value, eliminating large fully connected layers.', 'ADVANCED', 3, 'MCQ', 1),
(3834, 113, 'In a classification CNN, which component converts the final feature maps into a vector of class probabilities?', 'the pooling layer', 'the data loader', 'the flattening plus fully connected layers and a softmax', 'the batch normalization only', 'D', 'The maps are flattened and passed through a dense layer followed by softmax to produce probabilities.', 'ADVANCED', 3, 'MCQ', 1),
(3835, 113, 'You need a model that outputs a dense per-pixel label for every image. Which architecture is most appropriate?', 'an encoder-decoder structure with upsampling layers', 'a plain dense classifier', 'a single fully connected layer', 'a random forest', 'A', 'Encoder-decoder architectures recover spatial resolution with upsampling to produce per-pixel outputs.', 'ADVANCED', 3, 'MCQ', 1),
(3836, 113, 'Why does max pooling provide translation invariance compared with using no pooling?', 'it increases parameters', 'it keeps the strongest feature response regardless of small positional shifts', 'it removes the filters', 'it makes the network deeper automatically', 'B', 'By taking the maximum over a window, max pooling tolerates small shifts in where a feature appears.', 'ADVANCED', 3, 'MCQ', 1),
(3837, 113, 'In a fully convolutional network, what is the role of transposed convolution (deconvolution) layers?', 'they reduce resolution', 'they upsample feature maps back to a higher resolution', 'they replace the loss', 'they add parameters only', 'C', 'Transposed convolutions learn to upsample coarse feature maps to the original spatial resolution.', 'ADVANCED', 3, 'MCQ', 1),
(3838, 113, 'Which statement about depthwise separable convolutions is correct?', 'they always use 7x7 filters', 'they factor a standard convolution into a depthwise and a pointwise step, reducing parameters', 'they are slower than standard convolutions', 'they remove all channels', 'D', 'Depthwise separable convolutions split filtering per channel and then mix channels with 1x1 convolutions, reducing cost.', 'ADVANCED', 3, 'MCQ', 1),
(3839, 113, 'An engineer is designing a lightweight CNN for mobile devices. Which choice most reduces the computational cost?', 'using depthwise separable convolutions and fewer channels', 'doubling the filter sizes', 'increasing the input resolution', 'adding more dense layers', 'A', 'Depthwise separable convolutions and smaller channel counts cut both parameters and FLOPs dramatically.', 'ADVANCED', 3, 'MCQ', 1),
(3840, 113, 'How does batch normalization interact with the output of a convolutional layer?', 'it normalizes across the entire dataset once', 'it normalizes the feature maps using the mean and variance of the current batch per channel', 'it replaces the activation', 'it removes the bias term only', 'B', 'Batch norm normalizes each channel across the batch during training, stabilizing the distribution of activations.', 'ADVANCED', 3, 'MCQ', 1),
(3841, 114, 'What type of neural network is designed to process sequential data such as time series or text?', 'recurrent neural network', 'fully connected network', 'autoencoder', 'perceptron', 'A', 'RNNs keep a hidden state that evolves over time, letting them process sequences.', 'BEGINNER', 1, 'MCQ', 1),
(3842, 114, 'Which component of an RNN carries information from one time step to the next?', 'the loss', 'the hidden state', 'the softmax', 'the pooling layer', 'B', 'The hidden state is passed along and updated at every time step, carrying memory of the past.', 'BEGINNER', 1, 'MCQ', 1),
(3843, 114, 'In an RNN, how does the network share weights across time steps?', 'each time step has unique weights', 'it does not share weights', 'the same weight matrices are reused at every time step', 'weights are randomly reset each step', 'C', 'Weight sharing means the RNN learns one transition function applied at every time step.', 'BEGINNER', 1, 'MCQ', 1),
(3844, 114, 'What is the input to an RNN at each time step typically composed of?', 'the entire sequence', 'the class label', 'a random value', 'one element (token) of the sequence and the previous hidden state', 'D', 'At each step the RNN consumes the current token together with the previous hidden state.', 'BEGINNER', 1, 'MCQ', 1),
(3845, 114, 'Which problem do RNNs famously suffer from when trained on long sequences?', 'vanishing or exploding gradients', 'too few parameters', 'no weight sharing', 'oversized datasets', 'A', 'Long backpropagation through time multiplies gradients repeatedly, causing them to vanish or explode.', 'BEGINNER', 1, 'MCQ', 1),
(3846, 114, 'Which type of layer is commonly used to model text as a sequence of tokens?', 'convolutional layer only', 'recurrent layer such as LSTM or GRU', 'pooling layer', 'dropout layer', 'B', 'Recurrent layers are designed to capture dependencies across a sequence of tokens.', 'BEGINNER', 1, 'MCQ', 1),
(3847, 114, 'What does an embedding layer do for text inputs?', 'it resizes the image', 'it counts words', 'it maps each token to a dense vector of real numbers', 'it performs pooling', 'C', 'Embeddings convert discrete tokens into dense continuous vectors that carry semantic information.', 'BEGINNER', 1, 'MCQ', 1),
(3848, 114, 'In the context of RNNs, what is backpropagation through time (BPTT)?', 'a pooling strategy', 'backpropagation applied by unrolling the RNN over the sequence', 'a data augmentation method', 'a weight initializer', 'D', 'BPTT unrolls the RNN into a deep network over time and backpropagates through it.', 'BEGINNER', 1, 'MCQ', 1),
(3849, 114, 'Which RNN variant uses a gating mechanism to control what information is stored and forgotten?', 'LSTM', 'perceptron', 'CNN', 'autoencoder', 'A', 'The LSTM uses input, forget, and output gates to manage its long-term memory.', 'BEGINNER', 1, 'MCQ', 1),
(3850, 114, 'What type of problem is next-word prediction in a language model?', 'regression', 'sequence modeling', 'image segmentation', 'clustering', 'B', 'Predicting the next token in a sequence is a classic sequence-modeling task.', 'BEGINNER', 1, 'MCQ', 1),
(3851, 114, 'In an RNN layer, if the sequence length is 10 and the hidden size is 64, how many values does the final hidden state contain?', '64', '10', '640', '6400', 'A', 'The hidden state is a vector of size equal to the hidden dimension, which is 64.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3852, 114, 'An RNN has an input dimension of 20 and a hidden size of 50. What is the size of the input-to-hidden weight matrix Wxh?', '20x50', '50x20', '20x20', '50x50', 'B', 'Wxh maps inputs of dimension 20 to hidden states of dimension 50, so it is 50 by 20.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3853, 114, 'Which gating choice in an LSTM determines how much of the old cell state is kept?', 'input gate', 'output gate', 'forget gate', 'tanh gate', 'C', 'The forget gate outputs a value between 0 and 1 that scales how much old memory is retained.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3854, 114, 'Which situation best justifies using an LSTM instead of a plain RNN?', 'the data has no temporal order', 'the sequence is very short', 'the task has no sequence structure', 'the sequences are long and contain long-range dependencies', 'D', 'LSTM gates mitigate vanishing gradients, allowing long-range dependencies to be learned.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3855, 114, 'During training, what is the effect of unrolling an RNN over a 100-token sequence for backpropagation?', 'it creates a 100-layer deep network for the backward pass, which can be memory-hungry', 'it creates a 1-layer network', 'it removes the hidden state', 'it doubles the number of parameters', 'A', 'BPTT treats the unrolled sequence as a deep network, so long sequences require substantial memory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3856, 114, 'For a sentiment classification task that reads an entire movie review, which output is typically taken from the RNN?', 'the first hidden state', 'the final hidden state, followed by a classifier', 'every embedding', 'the loss only', 'B', 'The final hidden state summarizes the processed sequence and is fed to the classifier.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3857, 114, 'What is the main difference between a GRU and an LSTM?', 'GRUs have no hidden state', 'GRUs combine the forget and input gates into a single update gate and have fewer parameters', 'LSTMs have no gates', 'GRUs cannot process text', 'C', 'The GRU uses update and reset gates instead of three LSTM gates, making it cheaper with fewer parameters.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3858, 114, 'In sequence-to-sequence models, what role does the encoder play?', 'it decodes the output', 'it computes the loss', 'it samples noise', 'it compresses the input sequence into a context representation', 'D', 'The encoder maps the input sequence into a context vector that the decoder then conditions on.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3859, 114, 'Which technique directly helps RNNs handle vanishing gradients when training on long sequences?', 'using LSTM or GRU gated units and gradient clipping', 'removing the hidden state', 'using only one time step', 'replacing tokens with images', 'A', 'Gated units preserve gradient flow, and clipping handles exploding gradients for stable training.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3860, 114, 'Which of the following is the most appropriate application of a many-to-many RNN?', 'image classification', 'machine translation', 'single-number regression', 'clustering points', 'B', 'Translation maps an input sequence to an output sequence, a many-to-many sequence task.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3861, 114, 'A sentiment model performs well on short reviews but poorly on long ones. Which change most directly addresses long-range dependencies?', 'switch to a bidirectional LSTM with gated units to capture context from both directions', 'increase the batch size', 'use only the first word', 'remove the embedding layer', 'A', 'A bidirectional LSTM captures context from both directions and its gates handle long-range dependencies better.', 'ADVANCED', 3, 'MCQ', 1),
(3862, 114, 'In an encoder-decoder model, why does a plain RNN encoder struggle with very long source sentences?', 'it is too fast', 'the fixed-size context vector becomes a bottleneck and information is lost', 'the embeddings are too large', 'it cannot read text', 'B', 'Compressing a long sequence into one fixed vector loses information, limiting quality on long inputs.', 'ADVANCED', 3, 'MCQ', 1),
(3863, 114, 'Which mechanism addressed the information bottleneck of the encoder-decoder model?', 'dropout', 'attention, which lets the decoder focus on relevant parts of the input sequence', 'max pooling', 'data augmentation', 'C', 'Attention creates a weighted sum over all encoder states for each decoding step, removing the fixed-vector bottleneck.', 'ADVANCED', 3, 'MCQ', 1),
(3864, 114, 'Which statement about teacher forcing during RNN training is correct?', 'it stops all training', 'it is not used in sequence models', 'it feeds the true previous token to the model instead of its own prediction, speeding convergence', 'it doubles the sequence length', 'D', 'Teacher forcing provides the ground-truth token at each step, which stabilizes and accelerates training.', 'ADVANCED', 3, 'MCQ', 1),
(3865, 114, 'A character-level RNN is trained to generate text on a small dataset. What is the most likely failure mode?', 'the model may memorize the training text and repeat it verbatim', 'the model becomes an encoder', 'the loss becomes negative', 'the model loses its embedding layer', 'A', 'With few examples, a generative RNN can easily overfit and simply reproduce the training sequences.', 'ADVANCED', 3, 'MCQ', 1),
(3866, 114, 'Why does a bidirectional RNN need sequences padded to the same length within a batch?', 'because GPUs require square inputs', 'because recurrent layers in a batch are processed as tensors of equal length', 'because padding reduces parameters', 'because RNNs cannot handle variable lengths at all', 'B', 'Batching requires tensors of equal length, so shorter sequences are padded and often masked.', 'ADVANCED', 3, 'MCQ', 1),
(3867, 114, 'When computing the loss for a padded sequence, why should padding tokens be masked?', 'to increase the loss', 'they contribute no information, and including them would bias the loss and gradients', 'to make the model faster', 'to add more training examples', 'C', 'Masking prevents padding tokens from contributing loss or gradient updates, keeping the loss meaningful.', 'ADVANCED', 3, 'MCQ', 1),
(3868, 114, 'Which of the following best describes the attention weights computed in a standard attention layer?', 'they are random', 'they are always equal', 'they sum to one over the encoder positions and indicate relevance', 'they are negative for all tokens', 'D', 'Attention weights form a probability distribution over the source positions, weighting how relevant each one is.', 'ADVANCED', 3, 'MCQ', 1),
(3869, 114, 'In a text-generation RNN at inference time, why is temperature-based sampling often preferred over always choosing the most probable token?', 'sampling with temperature adds controlled randomness, producing more diverse and natural text', 'temperature always gives the same output', 'sampling is faster', 'temperature removes the embedding layer', 'A', 'Adjusting temperature changes the sharpness of the softmax, trading off diversity against repetitiveness.', 'ADVANCED', 3, 'MCQ', 1),
(3870, 114, 'Which architecture is the direct descendant of sequence modeling that now dominates modern language models?', 'pure RNN with sigmoid', 'the Transformer, based on self-attention without recurrence', 'a single perceptron', 'a shallow autoencoder', 'B', 'Transformers replace recurrence with self-attention, enabling parallelization and scaling to huge models.', 'ADVANCED', 3, 'MCQ', 1),
(3871, 115, 'Which Python library is a popular open-source deep learning framework from Google?', 'TensorFlow', 'Pandas', 'Matplotlib', 'Requests', 'A', 'TensorFlow is Google''s open-source framework for building and training neural networks.', 'BEGINNER', 1, 'MCQ', 1),
(3872, 115, 'Which Python deep learning framework is known for its dynamic computation graph?', 'TensorFlow 1.x static graphs', 'PyTorch', 'Numpy', 'Scikit-learn', 'B', 'PyTorch builds the computation graph dynamically, making it easy to debug and experiment with.', 'BEGINNER', 1, 'MCQ', 1),
(3873, 115, 'What is a tensor in deep learning frameworks?', 'a string', 'a multi-dimensional array of numerical values', 'a configuration file', 'a loss function', 'C', 'Tensors generalize scalars, vectors, and matrices to arbitrary dimensions and are the core data structure.', 'BEGINNER', 1, 'MCQ', 1),
(3874, 115, 'Which structure is used by PyTorch to wrap a dataset and enable efficient batching and shuffling?', 'DataFrame', 'DataLoader', 'List', 'Queue', 'D', 'The DataLoader handles batching, shuffling, and parallel loading of data for training.', 'BEGINNER', 1, 'MCQ', 1),
(3875, 115, 'Which framework component automatically computes gradients for a computation?', 'automatic differentiation (autograd)', 'the data loader', 'the loss function', 'the optimizer', 'A', 'Autograd records operations on tensors and computes gradients via automatic differentiation.', 'BEGINNER', 1, 'MCQ', 1),
(3876, 115, 'Which function is commonly used in PyTorch to initialize a tensor with random values?', 'torch.zeros', 'torch.rand', 'torch.ones', 'torch.eye', 'B', 'torch.rand creates a tensor filled with values sampled uniformly from the interval 0 to 1.', 'BEGINNER', 1, 'MCQ', 1),
(3877, 115, 'Which framework component applies weight updates during training?', 'the data loader', 'the loss function', 'the optimizer', 'the dataset', 'C', 'The optimizer, such as SGD or Adam, uses computed gradients to update the model weights.', 'BEGINNER', 1, 'MCQ', 1),
(3878, 115, 'What is the purpose of a loss function in a training loop?', 'to load data', 'to measure how far predictions are from the targets so gradients can be computed', 'to set the learning rate', 'to shuffle batches', 'D', 'The loss quantifies the prediction error, and its gradient drives the weight updates.', 'BEGINNER', 1, 'MCQ', 1),
(3879, 115, 'Which statement about training on a GPU versus a CPU is correct?', 'GPUs accelerate the massively parallel matrix operations used in deep learning', 'GPUs are always slower', 'GPUs cannot run neural networks', 'training is identical', 'A', 'The thousands of GPU cores handle the parallel tensor operations that dominate deep learning computation.', 'BEGINNER', 1, 'MCQ', 1),
(3880, 115, 'In PyTorch, how do you compute the gradient of a loss with respect to the model parameters?', 'loss.max()', 'loss.backward()', 'loss.forward()', 'loss.eval()', 'B', 'Calling backward() on the loss runs autograd and populates each parameter''s gradient.', 'BEGINNER', 1, 'MCQ', 1),
(3881, 115, 'In a PyTorch training loop, what is the correct purpose of calling optimizer.zero_grad()?', 'to clear previously accumulated gradients before the new backward pass', 'to set the loss to zero', 'to delete the model', 'to reload the data', 'A', 'Without zeroing, gradients from the previous batch would accumulate into the current update.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3882, 115, 'Which operation does optimizer.step() perform in PyTorch?', 'it evaluates the model', 'it applies the gradient-based parameter update', 'it resets the dataloader', 'it prints the loss', 'B', 'step() updates each parameter using its stored gradient and the optimizer rule.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3883, 115, 'Which statement about the model.train() and model.eval() modes in PyTorch is correct?', 'they do nothing', 'train() enables dropout and batch norm updates, while eval() disables them', 'both disable dropout', 'eval() enables dropout', 'C', 'Training mode enables training-only layers, while eval mode freezes them for consistent inference.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3884, 115, 'What is the purpose of a validation set used during training?', 'to train the model further', 'to store the best weights', 'to monitor generalization and tune hyperparameters without touching the test set', 'to increase the learning rate', 'D', 'Validation data lets you detect overfitting and select hyperparameters while keeping the test set untouched.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3885, 115, 'How does torch.no_grad() affect a forward pass during inference?', 'it disables gradient tracking, saving memory and speeding computation', 'it enables gradients', 'it doubles the memory', 'it resets the model', 'A', 'With no_grad(), the computation graph is not built, so inference uses less memory and runs faster.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3886, 115, 'Which data preprocessing step converts raw category labels into model-ready tensors for classification?', 'label encoding into integer class indices', 'deleting the labels', 'sorting the labels', 'multiplying the labels', 'B', 'Labels are mapped to integer indices, and often to one-hot vectors, before training.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3887, 115, 'What is the purpose of learning rate scheduling during training?', 'to increase the dataset size', 'to lower the loss to zero immediately', 'to decrease the learning rate over time for finer convergence', 'to remove the optimizer', 'C', 'Schedules such as cosine annealing or step decay shrink the learning rate to refine convergence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3888, 115, 'Which practice is recommended when the model''s training loss plateaus while validation loss increases?', 'increase the learning rate dramatically', 'keep training forever', 'stop training or early stop based on validation performance', 'remove the validation set', 'D', 'A rising validation loss signals overfitting, so early stopping preserves the best checkpoint.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3889, 115, 'Why is data normalization, such as scaling inputs to zero mean and unit variance, helpful for training?', 'it speeds up convergence and improves numerical stability', 'it adds more data', 'it removes the need for an optimizer', 'it always guarantees perfect accuracy', 'A', 'Well-scaled inputs make the loss surface easier to traverse and gradients more stable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3890, 115, 'Which metric is most appropriate to monitor when training a classifier on a highly imbalanced dataset?', 'accuracy alone', 'precision, recall, and F1 score', 'the learning rate', 'the batch size', 'B', 'With imbalance, accuracy is misleading, while precision, recall, and F1 reveal how well minority classes are handled.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3891, 115, 'A training run shows very high accuracy on training data but low accuracy on validation data. Which technique should be applied first?', 'add regularization such as dropout or weight decay', 'increase the batch size', 'increase the number of epochs', 'remove the validation set', 'A', 'This is overfitting, and regularization directly constrains the model''s capacity to reduce it.', 'ADVANCED', 3, 'MCQ', 1),
(3892, 115, 'Which choice is most appropriate for a fully supervised classification task with a single label per image?', 'mean squared error loss', 'cross-entropy loss', 'an autoencoder loss', 'a contrastive loss for ranking', 'B', 'Cross-entropy loss is the standard objective for single-label classification.', 'ADVANCED', 3, 'MCQ', 1),
(3893, 115, 'During distributed training on multiple GPUs, why do gradients need to be synchronized with an all-reduce?', 'to increase the batch size', 'to make each GPU compute a different model', 'so every GPU averages the gradients and updates identical weights', 'to slow down training', 'C', 'All-reduce averages gradients across workers so all replicas stay in sync during updates.', 'ADVANCED', 3, 'MCQ', 1),
(3894, 115, 'Which set of hyperparameters is most likely to be tuned together when a model overfits?', 'the dataset file format', 'dropout rate, weight decay, and model size', 'the GPU vendor', 'the color scheme of plots', 'D', 'These regularization-related hyperparameters directly control the model''s tendency to memorize.', 'ADVANCED', 3, 'MCQ', 1),
(3895, 115, 'Why is mixed-precision training with float16 and float32 beneficial on modern GPUs?', 'it reduces memory use and speeds up computation while keeping a float32 master copy for stability', 'it always halves accuracy', 'it removes the need for an optimizer', 'it only works for images', 'A', 'FP16 halves memory and doubles throughput, while the FP32 master weights preserve training stability.', 'ADVANCED', 3, 'MCQ', 1),
(3896, 115, 'What is the purpose of a learning rate warmup phase at the start of training large models?', 'to reduce the dataset', 'to prevent early instability by starting with small steps before increasing the learning rate', 'to remove the optimizer', 'to freeze all layers', 'B', 'Warmup avoids large initial updates that can destabilize training, especially with big batch sizes.', 'ADVANCED', 3, 'MCQ', 1),
(3897, 115, 'Which statement about checkpointing during training is correct?', 'it is unnecessary', 'checkpoints are saved periodically so training can resume and the best model can be restored', 'it reduces the model size permanently', 'it deletes old weights', 'C', 'Checkpointing captures weights and optimizer state, enabling resumption and best-model selection.', 'ADVANCED', 3, 'MCQ', 1),
(3898, 115, 'Which technique is most appropriate for a class-imbalanced dataset where the minority class is critical, such as fraud detection?', 'random sampling without replacement', 'using weighted loss or oversampling the minority class', 'ignoring the minority class', 'using accuracy as the only metric', 'D', 'Class weights or oversampling rebalance the training signal toward the minority class.', 'ADVANCED', 3, 'MCQ', 1),
(3899, 115, 'An engineer wants to reproduce an experiment exactly. Which practice is most important?', 'setting a fixed random seed for all randomness sources', 'increasing the batch size', 'using more epochs', 'changing the loss function', 'A', 'Seeding the random number generators for data, weight initialization, and dropout makes runs reproducible.', 'ADVANCED', 3, 'MCQ', 1),
(3900, 115, 'In PyTorch, how do you move a model and its tensors to run on the GPU?', 'model.speed()', 'model.to(''cuda'') and tensor.to(''cuda'')', 'model.move()', 'model.cpu()', 'B', 'The .to() method transfers modules and tensors to the specified device such as a CUDA GPU.', 'ADVANCED', 3, 'MCQ', 1),
(3901, 116, 'What is raw data?', 'data that has already been analyzed', 'unprocessed data collected directly from a source', 'data stored only in a database', 'data that contains no errors', 'A', 'Raw data refers to unprocessed, original data exactly as it was collected from its source before any transformation.', 'BEGINNER', 1, 'MCQ', 1),
(3902, 116, 'What is data cleaning primarily concerned with?', 'creating brand new datasets from scratch', 'detecting and correcting errors and inconsistencies in data', 'designing charts for a report', 'training machine learning models', 'B', 'Data cleaning focuses on fixing or removing errors, inconsistencies, and inaccuracies so the dataset is reliable for analysis.', 'BEGINNER', 1, 'MCQ', 1),
(3903, 116, 'What is a missing value in a dataset?', 'a value that equals zero', 'a value recorded outside its expected range', 'a field for which no data was recorded', 'a value stored as text', 'C', 'A missing value means no observation was recorded for that field, often represented as NaN or a blank cell.', 'BEGINNER', 1, 'MCQ', 1),
(3904, 116, 'What does the acronym CSV stand for?', 'Comma Separated Values', 'Common Standard Values', 'Character Sequence Vector', 'Compressed System Variables', 'D', 'CSV stands for Comma Separated Values, a plain-text format where each line is a record and fields are separated by commas.', 'BEGINNER', 1, 'MCQ', 1),
(3905, 116, 'Which of the following is an example of a data source?', 'an API endpoint that returns JSON records', 'a line chart', 'a decision tree', 'a pivot table', 'A', 'An API endpoint that returns JSON records is a live data source, whereas charts and trees are derived outputs.', 'BEGINNER', 1, 'MCQ', 1),
(3906, 116, 'What is data preprocessing?', 'the final presentation of results', 'the series of steps that transform raw data into a clean usable format', 'the storage of data in the cloud', 'the training of a model', 'B', 'Data preprocessing covers the steps such as cleaning, transforming, and encoding that turn raw data into a usable form.', 'BEGINNER', 1, 'MCQ', 1),
(3907, 116, 'What is a duplicate record?', 'a record identical to another record in the dataset', 'a record with many missing fields', 'a record outside the normal range', 'a record encrypted for security', 'C', 'A duplicate record is an exact or near-exact copy of another row, which can bias summaries if not removed.', 'BEGINNER', 1, 'MCQ', 1),
(3908, 116, 'Which of the following best describes structured data?', 'data stored in free-form paragraphs', 'data organized in a predefined tabular format with rows and columns', 'data collected from images', 'data streamed in real time only', 'D', 'Structured data fits neatly into a tabular format with defined rows and columns, such as a relational table.', 'BEGINNER', 1, 'MCQ', 1),
(3909, 116, 'What does it mean when a dataset has inconsistent formatting?', 'values representing the same thing appear in different formats', 'the data contains no errors', 'the data is encrypted', 'the data is sorted alphabetically', 'A', 'Inconsistent formatting means the same information appears in multiple formats, so it cannot be compared directly.', 'BEGINNER', 1, 'MCQ', 1),
(3910, 116, 'What is data imputation commonly used to address?', 'outlier removal', 'missing values', 'data encryption', 'feature selection', 'B', 'Imputation fills in missing values using statistics such as the mean, median, or mode.', 'BEGINNER', 1, 'MCQ', 1),
(3911, 116, 'A sales dataset stores prices as ''USD'', ''$'', and plain numbers. What is the best first cleaning step?', 'standardize the currency format to a single representation', 'delete every row containing ''$''', 'convert the price column to text', 'ignore the column in all analysis', 'A', 'Standardizing the currency format to one representation lets every price be compared and aggregated correctly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3912, 116, 'A dataset has 5% of the age column missing. Which imputation approach is most reasonable?', 'delete the entire dataset', 'replace missing ages with the column median', 'replace every missing age with 100', 'leave the missing values blank in all analysis', 'B', 'The median is robust to skew and outliers, making it a sensible choice for imputing a numeric column like age.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3913, 116, 'A date column mixes ''2024-01-05'', ''05/01/2024'', and ''January 5, 2024''. What data quality problem is this?', 'duplicate detection', 'outlier removal', 'inconsistent date formatting', 'missing value handling', 'C', 'Multiple date formats for the same concept mean the column cannot be parsed or sorted consistently until normalized.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3914, 116, 'A customer table has 10,000 rows and 1,200 are exact duplicates. Which strategy is best?', 'keep one copy of each duplicate group after verifying they are truly identical', 'keep all duplicates to preserve volume', 'delete the entire table', 'randomly remove 1,200 rows', 'D', 'After confirming rows are genuinely identical, keeping one copy removes redundancy without losing information.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3915, 116, 'A weight column contains negative values such as -5 kg. What should you do?', 'investigate whether the negatives are valid measurements or entry errors before deciding', 'average them with the positive values', 'convert negatives to text', 'leave them untouched in every analysis', 'A', 'The correct action is to determine the cause of the negatives, since valid negatives differ from entry errors.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3916, 116, 'Which scenario is best handled by a LEFT JOIN rather than an inner join?', 'you only want rows present in both tables', 'you want to keep all rows from the left table even without matches', 'you want to merge tables without any key', 'you want to remove all missing values', 'B', 'A LEFT JOIN preserves every row of the left table, filling unmatched right-table fields with NULL.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3917, 116, 'City names contain trailing spaces like ''New York   ''. Which cleaning step removes them?', 'trimming whitespace', 'normalizing case', 'removing duplicates', 'scaling the values', 'C', 'Trimming removes leading and trailing whitespace so identical city names compare equal.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3918, 116, 'A survey column has values ''Y'', ''yes'', and ''1'' meaning the same response. What is recommended?', 'keep them as three separate categories', 'standardize all values to one binary representation', 'delete the column', 'convert all values to uppercase only', 'D', 'Standardizing all spellings to one representation makes the column a clean binary variable for analysis.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3919, 116, 'When loading a large CSV with pandas, which argument most consistently handles missing data markers?', 'na_values so blanks and markers are parsed as NaN', 'index_col to set the index', 'skipfooter to ignore footer rows', 'engine to change parsing speed only', 'A', 'The na_values argument tells pandas which strings should be treated as missing values on load.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3920, 116, 'A dataset mixes temperatures in Celsius and Fahrenheit. What is the proper cleaning step?', 'average the two units together', 'convert all values to one consistent unit before analysis', 'keep both units exactly as they are', 'delete the temperature data', 'B', 'Analysis is only valid when all measurements share one unit, so every value must be converted to a single scale.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3921, 116, 'A team drops every row with missing values and the model gets worse. What is the most likely cause?', 'dropping rows introduced selection bias by removing a non-random subset', 'models always prefer fewer rows', 'missing values always improve performance', 'the data no longer fits in memory', 'A', 'Missing values are rarely missing at random, so dropping those rows can bias the remaining sample and hurt generalization.', 'ADVANCED', 3, 'MCQ', 1),
(3922, 116, 'You must clean a stream of 1 million records per hour with a strict latency budget. Which design is best?', 'run all cleaning as one monthly batch', 'incrementally clean and validate records in the streaming pipeline as they arrive', 'skip cleaning entirely to save time', 'store raw data and never transform it', 'B', 'Incremental streaming cleaning keeps latency low because each record is processed as it arrives rather than in large batches.', 'ADVANCED', 3, 'MCQ', 1),
(3923, 116, 'A column has 98% missing values. What is the most defensible decision?', 'impute the column with its mean', 'impute the column with its mode', 'drop the column because it carries almost no information and risks adding noise', 'fill every value with zero', 'C', 'A column with 98% missingness carries almost no signal and imputing it would mostly inject noise, so dropping it is defensible.', 'ADVANCED', 3, 'MCQ', 1),
(3924, 116, 'Which approach best handles outliers in a salary dataset published in a public report?', 'silently remove all outliers', 'report both raw and outlier-adjusted statistics so the impact is visible', 'replace outliers with the maximum value', 'round all salaries to the nearest thousand', 'D', 'Reporting both versions lets readers see how outliers influence the statistics instead of hiding the decision.', 'ADVANCED', 3, 'MCQ', 1),
(3925, 116, 'A pipeline fails at 2am because of malformed records. Which practice prevents silent data corruption?', 'schema validation that rejects malformed records early with clear alerts', 'swallowing all parse errors', 'writing everything to one log without checks', 'increasing parallelism', 'A', 'Early schema validation rejects malformed records at the source and raises alerts before bad data propagates downstream.', 'ADVANCED', 3, 'MCQ', 1),
(3926, 116, 'You must merge data from three legacy systems with no shared primary key. Which technique is most appropriate?', 'join on the name field alone', 'fuzzy matching on multiple identifying fields with a confidence threshold and manual review', 'random sampling of rows', 'concatenating all rows into one table', 'B', 'Without a shared key, fuzzy matching on several identifiers with a confidence threshold and human review is the standard robust approach.', 'ADVANCED', 3, 'MCQ', 1),
(3927, 116, 'A regression target has 40% missing rows that are simply dropped. Why is this a concern?', 'dropping target rows is always safe', 'the remaining rows may not be representative, biasing the coefficient estimates', 'more rows always make models worse', 'missing targets cannot affect any analysis', 'C', 'If missingness relates to the outcome, dropping those rows creates a biased sample and skews the regression estimates.', 'ADVANCED', 3, 'MCQ', 1),
(3928, 116, 'Which data quality dimension is violated when one customer appears with three different name spellings?', 'timeliness', 'accuracy', 'completeness', 'consistency', 'D', 'Consistency requires that the same entity is represented the same way; different spellings violate this dimension.', 'ADVANCED', 3, 'MCQ', 1),
(3929, 116, 'A medical dataset contains birth dates in the future. What is the best response?', 'flag them as invalid and investigate the root cause of the entry error before correcting', 'replace them with today''s date', 'ignore them entirely', 'subtract one year from each value', 'A', 'Future birth dates are invalid values, so the source of the entry error must be found and corrected.', 'ADVANCED', 3, 'MCQ', 1),
(3930, 116, 'An income column mixes hourly wages and annual salaries. What is the correct cleaning strategy?', 'treat every value as annual income', 'convert all values to a single comparable unit such as annual income', 'drop the column', 'sort the column and keep only the median', 'B', 'Mixing units makes income incomparable, so all values must be converted to one unit before analysis.', 'ADVANCED', 3, 'MCQ', 1),
(3931, 117, 'Which chart type is best for showing the distribution of a single continuous variable?', 'histogram', 'pie chart', 'line chart', 'scatter plot', 'A', 'A histogram bins the range of a continuous variable and shows how often values fall in each bin.', 'BEGINNER', 1, 'MCQ', 1),
(3932, 117, 'What is the x-axis of a standard bar chart usually called?', 'the legend', 'the category axis', 'the value axis', 'the series title', 'B', 'In a bar chart the categories are placed along the category axis, which is usually the x-axis.', 'BEGINNER', 1, 'MCQ', 1),
(3933, 117, 'Which plot is best for showing the relationship between two continuous variables?', 'scatter plot', 'bar chart', 'pie chart', 'histogram', 'C', 'A scatter plot places each observation by its two numeric coordinates, revealing relationships and patterns.', 'BEGINNER', 1, 'MCQ', 1),
(3934, 117, 'What is the purpose of a chart legend?', 'to identify what each series or color represents', 'to display the raw data values', 'to set the scale of the axes', 'to compress the image size', 'D', 'The legend maps colors, symbols, or patterns to the categories they represent so readers can decode the chart.', 'BEGINNER', 1, 'MCQ', 1),
(3935, 117, 'Which Python library is the most widely used for creating static plots?', 'Matplotlib', 'NumPy', 'SciPy', 'Requests', 'A', 'Matplotlib is the foundational plotting library in Python, and most other plotting tools build on it.', 'BEGINNER', 1, 'MCQ', 1),
(3936, 117, 'What does a pie chart divide a whole into?', 'bars of equal length', 'segments proportional to the parts of a whole', 'points along a line', 'bins of equal width', 'B', 'A pie chart slices a circle into wedges whose sizes are proportional to each category''s share of the total.', 'BEGINNER', 1, 'MCQ', 1),
(3937, 117, 'What is the purpose of axis labels in a plot?', 'to make the plot more colorful', 'to describe what each axis measures', 'to store the underlying data', 'to resize the figure', 'C', 'Axis labels tell the reader what quantity and unit each axis represents.', 'BEGINNER', 1, 'MCQ', 1),
(3938, 117, 'Which chart is most appropriate for showing a trend over time?', 'pie chart', 'histogram', 'bar chart', 'line chart', 'D', 'A line chart connects observations in time order, making trends and changes easy to follow.', 'BEGINNER', 1, 'MCQ', 1),
(3939, 117, 'In a box plot, which line inside the box represents the median?', 'the middle line inside the box', 'the top whisker end', 'the bottom whisker end', 'the mean point', 'A', 'The line inside the box marks the median, the middle value of the sorted data.', 'BEGINNER', 1, 'MCQ', 1),
(3940, 117, 'What do the whiskers of a box plot show?', 'the exact values of all points', 'the spread of data beyond the box up to typical extremes', 'the number of records', 'the chart title', 'B', 'Whiskers extend from the box to the furthest data points that are not considered outliers.', 'BEGINNER', 1, 'MCQ', 1),
(3941, 117, 'A bar chart with 40 categories is too cluttered to read. Which approach is best?', 'group rare categories into an Other bucket', 'make the bars smaller', 'add a 3D effect', 'sort the categories randomly', 'A', 'Binning rare categories into an Other bucket reduces clutter while preserving the important structure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3942, 117, 'A scatter plot of two variables shows a tight diagonal band. What does this suggest?', 'the variables are unrelated', 'there is a strong linear relationship between them', 'both variables are categorical', 'the date encoding is wrong', 'B', 'Points lying close to a straight diagonal indicate a strong linear association between the two variables.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3943, 117, 'You need to compare the medians and spreads of five groups. Which plot is best?', 'a pie chart', 'a single bar chart', 'grouped box plots', 'a histogram of all groups combined', 'C', 'Box plots show median, quartiles, and whiskers for each group, making side-by-side comparison easy.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3944, 117, 'A line chart plots monthly points at equal spacing even though the real time gaps differ. What is wrong?', 'the time axis should reflect the true time intervals', 'line charts cannot display time', 'the y-axis must be logarithmic', 'nothing is wrong', 'D', 'Equal spacing misrepresents the actual timing, so the axis must be scaled to the real intervals.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3945, 117, 'Two series on one chart have very different scales. What is recommended?', 'use two y-axes with clear labels or separate panels', 'multiply one series by a hidden constant', 'plot only the larger series', 'round all values to integers', 'A', 'Dual axes or separate panels let each series use an appropriate scale without flattening the other.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3946, 117, 'Sorting the bars of a bar chart from tallest to shortest makes what easier?', 'computing the mean', 'comparing ranks', 'detecting missing values', 'fitting a regression line', 'B', 'Ordered bars let the reader instantly compare which categories rank highest and lowest.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3947, 117, 'Which visual encoding is most accurate for reading numeric magnitudes?', 'color hue', 'area', 'position along a common scale', 'opacity', 'C', 'Humans judge positions along a shared scale far more accurately than areas, colors, or opacity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3948, 117, 'A histogram with far too many bins shows what problem?', 'the bars become wide and hide detail', 'the shape becomes noisy with little clear structure', 'the median is removed', 'the data is deleted', 'D', 'Too many bins fragment the counts so the underlying shape is obscured by noise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3949, 117, 'In a stacked bar chart, what does the height of one segment represent?', 'the contribution of that category to the total of the bar', 'the median of all bars', 'the overall total', 'the number of bins', 'A', 'Each segment''s height shows how much that category contributes to the stacked total of its bar.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3950, 117, 'Which plot best shows the joint distribution of two categorical variables?', 'a line chart', 'a heatmap of counts or proportions', 'a box plot', 'a single bar chart', 'B', 'A heatmap displays the count or proportion for every combination of the two categories in a grid.', 'INTERMEDIATE', 2, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(3951, 117, 'A dashboard encodes a continuous value with a rainbow colormap. Why is this a problem?', 'rainbow colormaps are not perceptually uniform and can mislead ordering and magnitude', 'they use too few colors', 'they only work for discrete data', 'they cannot be rendered by browsers', 'A', 'Perceptually non-uniform colormaps distort how differences in value are perceived, so the rainbow is discouraged.', 'ADVANCED', 3, 'MCQ', 1),
(3952, 117, 'You must show 12 months of revenue for 30 product lines on one chart. Which design is best?', 'a single pie chart', 'small multiples with one panel per product line', 'one stacked bar with 30 segments', 'a 3D pie chart', 'B', 'Small multiples let each series have its own readable panel while keeping a consistent scale for comparison.', 'ADVANCED', 3, 'MCQ', 1),
(3953, 117, 'Which chart choice is considered deceptive when comparing proportions of a whole?', 'a simple bar chart', 'a horizontal bar chart', 'a 3D pie chart', 'a heatmap', 'C', 'The 3D effect distorts segment sizes and angles, making proportions hard to compare accurately.', 'ADVANCED', 3, 'MCQ', 1),
(3954, 117, 'An analyst starts a bar chart''s y-axis at 80 instead of 0 to emphasize small differences. Why is this criticized?', 'it makes the bars taller', 'it exaggerates small differences and can mislead readers', 'it always hides important data', 'it changes the colors used', 'D', 'Truncating the y-axis exaggerates visual differences, which can mislead readers about the true magnitude of change.', 'ADVANCED', 3, 'MCQ', 1),
(3955, 117, 'A time series has 50,000 points and plotting all of them produces a black mass. What is the best fix?', 'bin or downsample the data and plot aggregate trends', 'increase the point size', 'use a pie chart', 'remove the time axis', 'A', 'Downsampling or binning reduces overplotting while still conveying the overall trend and variability.', 'ADVANCED', 3, 'MCQ', 1),
(3956, 117, 'For a colorblind audience, which practice is essential in a chart?', 'use red and green only', 'use shape or pattern in addition to color', 'rely exclusively on color hue', 'remove the legend', 'B', 'Adding shapes or patterns means the chart is readable even without color distinction.', 'ADVANCED', 3, 'MCQ', 1),
(3957, 117, 'Two series have wildly different units, millions and cents. What is recommended?', 'merge them into one average', 'use dual axes with clearly labeled scales or separate subplots', 'plot only the cents series', 'use a pie chart', 'C', 'Dual axes with explicit labels or separate subplots keep each series legible on its own scale.', 'ADVANCED', 3, 'MCQ', 1),
(3958, 117, 'Which practice is the strongest guard against chartjunk and misleading visuals?', 'minimize non-data ink and follow the data-ink ratio', 'add as many decorations as possible', 'use 3D effects everywhere', 'animate every chart', 'D', 'Removing unnecessary ink keeps the focus on the data, following the data-ink ratio principle.', 'ADVANCED', 3, 'MCQ', 1),
(3959, 117, 'Why is a static chart library that saves images still valuable in an automated reporting pipeline?', 'it integrates easily with scheduled batch scripts and document generation', 'it cannot produce any charts', 'it is always slower than interactive tools', 'it requires a web browser', 'A', 'Static images are simple to embed into scheduled reports and documents without interactive infrastructure.', 'ADVANCED', 3, 'MCQ', 1),
(3960, 117, 'A map encodes a metric with bubble area, but many small values make comparison hard. What is better?', 'use filled regions colored by the value rather than bubble area', 'make all bubbles the same size', 'double the legend size', 'remove the map', 'B', 'Colored regions encode value by color intensity, avoiding the perceptual bias of comparing areas.', 'ADVANCED', 3, 'MCQ', 1),
(3961, 118, 'What is the mean of a dataset?', 'the sum of all values divided by the number of values', 'the middle value when the data is sorted', 'the most frequently occurring value', 'the largest value in the data', 'A', 'The mean is the arithmetic average, computed by dividing the total of all values by the count.', 'BEGINNER', 1, 'MCQ', 1),
(3962, 118, 'What is the median of a dataset?', 'the average of all values', 'the middle value when the data is sorted', 'the most frequent value', 'the maximum value', 'B', 'The median is the middle value of the ordered data, splitting the dataset into two equal halves.', 'BEGINNER', 1, 'MCQ', 1),
(3963, 118, 'What is the mode of a dataset?', 'the mean of the data', 'the middle value of the sorted data', 'the value that occurs most frequently', 'the difference between the largest and smallest', 'C', 'The mode is the value that appears most often in the dataset.', 'BEGINNER', 1, 'MCQ', 1),
(3964, 118, 'What does the standard deviation measure?', 'the most frequent value', 'the number of data points', 'the middle value', 'the average distance of values from the mean', 'D', 'Standard deviation summarizes how spread out the values are around the mean.', 'BEGINNER', 1, 'MCQ', 1),
(3965, 118, 'What is the range of a dataset?', 'the difference between the largest and smallest values', 'the average of all values', 'the middle value', 'the most frequent value', 'A', 'The range is computed as the maximum minus the minimum value.', 'BEGINNER', 1, 'MCQ', 1),
(3966, 118, 'What is a population in statistics?', 'a small subset chosen for a study', 'the entire group of individuals or items being studied', 'the median value', 'a sample of the data', 'B', 'A population is the complete set of entities that the analysis is concerned with.', 'BEGINNER', 1, 'MCQ', 1),
(3967, 118, 'What is a sample in statistics?', 'the entire population', 'the average of the data', 'a subset of the population used to draw inferences', 'a histogram of the data', 'C', 'A sample is a subset drawn from the population that is used to make inferences about it.', 'BEGINNER', 1, 'MCQ', 1),
(3968, 118, 'What is the variance of a dataset?', 'the square root of the standard deviation', 'the range divided by two', 'the sum of all values', 'the square of the standard deviation', 'D', 'Variance is the average squared deviation from the mean, which equals the standard deviation squared.', 'BEGINNER', 1, 'MCQ', 1),
(3969, 118, 'What is a histogram used to estimate?', 'the shape of the distribution of a continuous variable', 'the relationship between two variables', 'the exact count of records', 'the total sum of all values', 'A', 'A histogram shows how a continuous variable is distributed across bins of values.', 'BEGINNER', 1, 'MCQ', 1),
(3970, 118, 'What is the standard error of the mean?', 'the mean of the sample', 'the standard deviation of the sampling distribution of the mean', 'the range of the sample', 'the mode of the sample', 'B', 'The standard error measures how much the sample mean varies across repeated samples.', 'BEGINNER', 1, 'MCQ', 1),
(3971, 118, 'What is the mean of the values 4, 8, 6, 10, and 7?', '7', '8', '6', '9', 'A', 'The sum is 35 and there are 5 values, so 35 / 5 equals 7.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3972, 118, 'What is the median of 3, 7, 1, 9, and 5?', '5', '3', '7', '1', 'B', 'Sorted as 1, 3, 5, 7, 9, the middle value is 5.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3973, 118, 'What is the mode of 2, 3, 3, 5, 5, 5, and 8?', '5', '3', '2', '8', 'C', 'The value 5 occurs three times, more than any other value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3974, 118, 'A hypothesis test returns a p-value of 0.03 at the 0.05 significance level. What is the correct decision?', 'fail to reject the null hypothesis', 'accept the null hypothesis', 'declare the data invalid', 'reject the null hypothesis because 0.03 is less than 0.05', 'D', 'Because the p-value of 0.03 is below the 0.05 threshold, the result is significant and the null hypothesis is rejected.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3975, 118, 'What is the range of 12, 7, 19, 3, and 21?', '18', '19', '21', '12', 'A', 'The maximum is 21 and the minimum is 3, so the range is 21 - 3 = 18.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3976, 118, 'A dataset has a mean of 50 and a standard deviation of 4. How many standard deviations above the mean is the value 58?', '1.5', '2', '3', '0.5', 'B', 'The z-score is (58 - 50) / 4 = 8 / 4 = 2 standard deviations above the mean.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3977, 118, 'If the standard deviation of a dataset is 5, what is its variance?', '5', '10', '25', '2.5', 'C', 'Variance is the standard deviation squared, so 5 squared equals 25.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3978, 118, 'A 95% confidence interval for a mean is reported as 10 +/- 2. What does this mean?', 'there is a 95% chance the sample mean equals 10', 'the estimation procedure will capture the population mean in about 95% of repeated samples', '95% of the data lies between 8 and 12', 'the population mean is certainly 10', 'D', 'A confidence interval describes the long-run success rate of the estimation procedure, not the probability for one specific interval.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3979, 118, 'What is the interquartile range of a dataset?', 'the difference between the third quartile and the first quartile', 'the difference between the maximum and the minimum', 'the mean minus the median', 'the square of the standard deviation', 'A', 'The IQR measures the spread of the middle 50% of the data as Q3 minus Q1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3980, 118, 'A study finds a correlation of 0.9 between ice cream sales and temperature. What conclusion is justified?', 'ice cream sales cause higher temperatures', 'there is a strong positive linear relationship between the two variables', 'there is no relationship at all', 'the data must be invalid', 'B', 'A correlation of 0.9 indicates a strong positive linear association, but correlation alone does not imply causation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(3981, 118, 'A trial reports a p-value of 0.04 but a tiny effect size. Why might a statistician question the practical importance?', 'statistical significance does not imply practical significance, and a tiny effect may be meaningless', 'p-values are always the final word', 'effect sizes are irrelevant to interpretation', 'a p-value below 0.05 guarantees a large effect', 'A', 'Significance only shows the result is unlikely under the null; a tiny effect may have no real-world importance.', 'ADVANCED', 3, 'MCQ', 1),
(3982, 118, 'Which distribution best models the count of rare, independent defects in a large batch?', 'the uniform distribution', 'the Poisson distribution', 'the normal distribution', 'the chi-square distribution', 'B', 'The Poisson distribution models counts of rare events occurring independently over a fixed interval or batch.', 'ADVANCED', 3, 'MCQ', 1),
(3983, 118, 'To compare the means of two independent samples with unknown but assumed equal variances, which test is most appropriate?', 'the paired t-test', 'the chi-square test of independence', 'the independent samples t-test', 'ANOVA', 'C', 'The independent samples t-test compares two group means under the equal-variance assumption.', 'ADVANCED', 3, 'MCQ', 1),
(3984, 118, 'Why is running three separate t-tests to compare three group means worse than a single ANOVA?', 't-tests run slower', 'ANOVA always rejects the null', 'multiple comparisons inflate the family-wise Type I error rate', 't-tests cannot be computed on groups', 'D', 'Each t-test carries a chance of a false positive, so several tests together inflate the overall Type I error rate.', 'ADVANCED', 3, 'MCQ', 1),
(3985, 118, 'An income dataset is right-skewed with one enormous outlier. Which measure of central tendency is most robust?', 'the median', 'the mean', 'the range', 'the variance', 'A', 'The median depends only on the middle of the data, so extreme outliers barely affect it.', 'ADVANCED', 3, 'MCQ', 1),
(3986, 118, 'Which assumption is most important before running a standard t-test?', 'the data must be categorical', 'the data should be approximately normally distributed', 'the variance must be zero', 'the sample size must exceed 1000', 'B', 'The t-test assumes the data are roughly normal, especially for small samples, so the sampling distribution of the mean is well behaved.', 'ADVANCED', 3, 'MCQ', 1),
(3987, 118, 'A regression coefficient has a 95% confidence interval from 0.02 to 0.04. What does this indicate?', 'the effect is exactly 0.03', 'the effect is definitely large', 'the effect is statistically significant but small in magnitude', 'the model is invalid', 'C', 'Since the interval excludes zero the effect is significant, but the small values show the effect is weak.', 'ADVANCED', 3, 'MCQ', 1),
(3988, 118, 'According to the Central Limit Theorem, the sampling distribution of the mean becomes approximately what as the sample size grows?', 'normal', 'uniform', 'binomial', 'exponential', 'D', 'Regardless of the population''s shape, the distribution of sample means approaches normality for large samples.', 'ADVANCED', 3, 'MCQ', 1),
(3989, 118, 'To compare observed and expected counts in a contingency table, which test is used?', 'the chi-square test of independence', 'the z-test for a single mean', 'the paired t-test', 'linear regression', 'A', 'The chi-square test compares observed frequencies against expected frequencies under independence.', 'ADVANCED', 3, 'MCQ', 1),
(3990, 118, 'A model has an R-squared of 0.9 in training but 0.4 on held-out data. What is the most likely explanation?', 'the model is underfit', 'overfitting: the model memorized the training data', 'R-squared always drops on test sets', 'the test set is corrupted', 'B', 'A large gap between training and test R-squared is the classic signature of overfitting.', 'ADVANCED', 3, 'MCQ', 1),
(3991, 119, 'What is exploratory data analysis (EDA)?', 'the process of analyzing datasets to summarize their main characteristics, often with visuals', 'the process of deploying models to production', 'the process of writing user documentation', 'the process of collecting data from APIs', 'A', 'EDA is the initial investigation that uses summaries and plots to understand the structure and quirks of the data.', 'BEGINNER', 1, 'MCQ', 1),
(3992, 119, 'Which of the following is a common tool used during EDA?', 'summary statistics and plots', 'only SQL database indexes', 'only cloud storage buckets', 'only network firewalls', 'B', 'EDA relies on summary statistics and visualizations to inspect the data.', 'BEGINNER', 1, 'MCQ', 1),
(3993, 119, 'Which pandas method produces summary statistics for the numeric columns of a DataFrame?', 'describe()', 'print()', 'head()', 'rename()', 'C', 'describe() returns count, mean, standard deviation, minimum, quartiles, and maximum for numeric columns.', 'BEGINNER', 1, 'MCQ', 1),
(3994, 119, 'What does the pandas head() method return?', 'the last few rows of the DataFrame', 'a summary of missing values', 'the column names', 'the first few rows of the DataFrame', 'D', 'head() shows the first n rows, which is a quick way to peek at the data.', 'BEGINNER', 1, 'MCQ', 1),
(3995, 119, 'What is the purpose of a correlation matrix in EDA?', 'to show pairwise correlations between numeric variables', 'to list every missing value', 'to delete irrelevant columns', 'to sort the rows of the data', 'A', 'A correlation matrix displays the strength and direction of linear association between each pair of numeric variables.', 'BEGINNER', 1, 'MCQ', 1),
(3996, 119, 'Which pandas attribute shows the data type of every column?', 'shape', 'dtypes', 'sample', 'dropna', 'B', 'The dtypes attribute reports the type, such as int64 or object, for each column.', 'BEGINNER', 1, 'MCQ', 1),
(3997, 119, 'What does the shape attribute of a DataFrame return?', 'the sum of all values', 'the mean of each column', 'the number of rows and columns as a tuple', 'the first row as a Series', 'C', 'shape returns a tuple (rows, columns) describing the dimensions of the DataFrame.', 'BEGINNER', 1, 'MCQ', 1),
(3998, 119, 'What is a pair plot used for?', 'showing pairwise relationships between several numeric variables at once', 'drawing a single pie chart', 'removing outliers', 'renaming columns', 'D', 'A pair plot grids scatter plots and histograms for every pair of selected numeric variables.', 'BEGINNER', 1, 'MCQ', 1),
(3999, 119, 'What does the pandas info() method show?', 'a concise summary including column names, non-null counts, and data types', 'the first plot', 'the correlation matrix only', 'the index values only', 'A', 'info() prints a compact overview that quickly reveals missing counts and column types.', 'BEGINNER', 1, 'MCQ', 1),
(4000, 119, 'What is value_counts() most commonly used for in EDA?', 'computing the mean of a column', 'counting the occurrences of each unique value in a column', 'filling missing values', 'standardizing a column', 'B', 'value_counts() tallies how often each distinct value appears, which is essential for categorical columns.', 'BEGINNER', 1, 'MCQ', 1),
(4001, 119, 'During EDA a histogram of a column shows two distinct peaks. What does this suggest?', 'the data may combine two subgroups or populations', 'the data is perfectly uniform', 'the column has zero variance', 'every value is an error', 'A', 'A bimodal distribution usually signals that the data mixes two underlying groups with different centers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4002, 119, 'Two features have a correlation of -0.95. What does this imply for modeling?', 'the features are independent', 'one feature must be deleted at random', 'the features are strongly negatively related and may cause multicollinearity', 'the data cannot be modeled', 'B', 'A correlation near -1 means the features move in opposite directions and are nearly redundant, which can inflate model variance.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4003, 119, 'You find 30% of a key column is missing. Which EDA step should come first?', 'investigate whether the missingness is random or systematic', 'delete the entire dataset', 'fill the column with random numbers', 'ignore the missingness', 'C', 'Determining how and why values are missing guides whether imputation, deletion, or a model for missingness is appropriate.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4004, 119, 'A scatter plot of two features shows a clear U-shaped relationship. What does this imply for a linear model?', 'a linear model will be perfect', 'a linear model may fit poorly and a transformation could help', 'the features are exact duplicates', 'no analysis is possible', 'D', 'A curved pattern violates linearity, so a linear fit is weak and transformations or nonlinear models may capture the relationship.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4005, 119, 'Which visualization is most efficient for spotting outliers in many numeric columns at once?', 'a grid of box plots', 'a single pie chart', 'a line chart', 'a histogram of one column', 'A', 'Box plots mark points beyond the whiskers, so a grid of them reveals outliers across columns quickly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4006, 119, 'A categorical column has 100 distinct values. Which EDA summary is most useful first?', 'the mean of the column', 'value_counts() to examine the frequency distribution', 'a correlation matrix', 'a pair plot', 'B', 'value_counts() shows how common each category is and reveals imbalanced or near-constant categories.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4007, 119, 'A column is constant across every row. What is the main implication?', 'it is the most important feature', 'it must be one-hot encoded', 'it carries no information for prediction and is often dropped', 'it causes all values to be missing', 'C', 'A constant column has zero variance, so it cannot help distinguish any outcome and is typically removed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4008, 119, 'A log transformation is most helpful for which type of variable discovered during EDA?', 'a right-skewed variable with a long tail', 'a binary variable', 'a perfectly normal variable', 'a categorical variable', 'D', 'Log transforms compress a long right tail and make strongly skewed data more symmetric.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4009, 119, 'Which EDA finding best indicates a potential data leakage problem?', 'a feature that would not be available at prediction time', 'a feature with many missing values', 'a highly skewed feature', 'a numeric feature with a large mean', 'A', 'If a feature encodes future or target information, the model would look great in training but fail in production.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4010, 119, 'A box plot for transaction amounts shows many points above the upper whisker. What is most appropriate?', 'delete them all immediately', 'investigate whether they are genuine large transactions or errors', 'divide them all by 1000', 'leave them untouched forever', 'B', 'High-value outliers may be legitimate, so they must be examined before any removal or transformation decision.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4011, 119, 'You have 500 features and a small dataset. Which EDA approach best identifies which features matter before modeling?', 'univariate and bivariate analysis combined with correlation checks and domain review', 'randomly select 10 features', 'train a model on all features immediately', 'delete every numeric feature', 'A', 'Systematic univariate and bivariate exploration narrows down useful features while domain knowledge validates relevance.', 'ADVANCED', 3, 'MCQ', 1),
(4012, 119, 'An anomaly in a feature appears only on certain dates. Which EDA technique would reveal this?', 'grouping the data by date and comparing distributions per group', 'a single histogram of all data', 'a correlation matrix', 'dropping the date column', 'B', 'Grouping by date lets you compare per-day distributions and spot when the anomaly appears.', 'ADVANCED', 3, 'MCQ', 1),
(4013, 119, 'To compare the distribution of a numeric feature across four customer segments, which visualization is most informative?', 'grouped box plots or violin plots', 'a single pie chart', 'one line chart', 'an ungrouped scatter plot', 'C', 'Grouped box or violin plots display the full distribution for each segment side by side.', 'ADVANCED', 3, 'MCQ', 1),
(4014, 119, 'When EDA reveals heavy multicollinearity, which downstream design decision is most justified?', 'keep all correlated features unchanged', 'use feature selection or regularization to reduce redundant predictors', 'double the number of features', 'remove the target variable', 'D', 'Reducing redundant predictors stabilizes estimates, and regularization can also handle correlated features.', 'ADVANCED', 3, 'MCQ', 1),
(4015, 119, 'House prices show a strong seasonal pattern in sales volume. How should this be captured during EDA?', 'plot the time series and decompose it into trend and seasonality', 'ignore the date column', 'convert all dates to text', 'combine all dates into one group', 'A', 'Decomposing the series separates the seasonal component so it can be modeled explicitly.', 'ADVANCED', 3, 'MCQ', 1),
(4016, 119, 'For a credit risk model, the default rate in your sample is 1%. Which key consideration arises?', 'the sample is too large', 'class imbalance must be handled, for example with resampling or class weights', 'defaults should be deleted', 'no modeling is possible', 'B', 'With 1% positives the model can trivially predict the majority class, so imbalance must be addressed explicitly.', 'ADVANCED', 3, 'MCQ', 1),
(4017, 119, 'Which set of EDA outputs most directly supports scaling one feature with MinMax but not another?', 'inspecting the ranges and distributions of each feature', 'the correlation matrix only', 'the value counts of the target', 'the number of missing rows', 'C', 'Features with very different ranges or with bounds may need scaling, which is decided by examining each distribution.', 'ADVANCED', 3, 'MCQ', 1),
(4018, 119, 'A derived feature correlates 0.999 with the target. What is the most important concern?', 'the feature is useless', 'leakage, because the feature may encode information unavailable at prediction time', 'the data is too small', 'the model will underfit', 'D', 'A near-perfect correlation often means the feature was derived from the target or future information, causing leakage.', 'ADVANCED', 3, 'MCQ', 1),
(4019, 119, 'Which ordered EDA checklist is the most sensible first pass over a dataset?', 'shape and dtypes, missing values, duplicates, distributions, correlations', 'correlations, then everything else', 'plotting everything at once', 'deleting columns first', 'A', 'Starting from structure and quality checks, then moving to distributions and relationships, catches problems early.', 'ADVANCED', 3, 'MCQ', 1),
(4020, 119, 'When preparing an EDA report for non-technical stakeholders, what is the best practice?', 'dump every raw table and code output', 'focus on a few clear, annotated visualizations that answer their questions', 'show every correlation coefficient', 'skip visuals entirely', 'B', 'Clear annotated visuals communicate findings far better than raw output for a non-technical audience.', 'ADVANCED', 3, 'MCQ', 1),
(4021, 120, 'What three characteristics are most often used to describe big data?', 'volume, velocity, and variety', 'speed, size, and color', 'schema, index, and key', 'rows, columns, and cells', 'A', 'Big data is classically defined by volume, velocity, and variety, sometimes extended with veracity and value.', 'BEGINNER', 1, 'MCQ', 1),
(4022, 120, 'In the context of big data, what does velocity refer to?', 'the total amount of data', 'the speed at which data is generated and processed', 'the range of data types', 'the accuracy of the data', 'B', 'Velocity captures how quickly data is produced and must be processed.', 'BEGINNER', 1, 'MCQ', 1),
(4023, 120, 'Which tool is commonly used for distributed processing of very large datasets?', 'Apache Spark', 'Microsoft Word', 'Notepad', 'VLC Media Player', 'C', 'Apache Spark runs computations in parallel across a cluster, which is how very large datasets are processed.', 'BEGINNER', 1, 'MCQ', 1),
(4024, 120, 'What is a data warehouse primarily designed for?', 'streaming video', 'rendering graphics', 'compiling source code', 'storing cleaned structured data for analysis and reporting', 'D', 'A data warehouse organizes structured, often cleansed data to support business intelligence and reporting.', 'BEGINNER', 1, 'MCQ', 1),
(4025, 120, 'What does MLOps stand for?', 'machine learning operations', 'multi-layer optimization', 'matrix learning protocols', 'machine logic production', 'A', 'MLOps is the practice of applying DevOps principles to build, deploy, and maintain machine learning systems.', 'BEGINNER', 1, 'MCQ', 1),
(4026, 120, 'What is model versioning in MLOps?', 'deleting old models automatically', 'tracking and managing different versions of a trained model', 'renaming models to shorter names', 'training models more quickly', 'B', 'Model versioning records which model produced which outputs, enabling rollback and audit.', 'BEGINNER', 1, 'MCQ', 1),
(4027, 120, 'What is a batch job in data processing?', 'processing a single record in real time', 'processing a collection of records together at scheduled intervals', 'saving a file to disk', 'loading a web page', 'C', 'A batch job processes a group of records at once, typically on a schedule rather than in real time.', 'BEGINNER', 1, 'MCQ', 1),
(4028, 120, 'Which of the following is an example of unstructured data?', 'a table of sales records', 'a CSV file with fixed columns', 'a relational database table', 'free-form text documents and images', 'D', 'Unstructured data has no predefined format, such as emails, images, and free-form text.', 'BEGINNER', 1, 'MCQ', 1),
(4029, 120, 'What is the purpose of an ML pipeline?', 'to automate the sequence of steps from raw data to a deployed model', 'to draw charts', 'to clean only one column', 'to store passwords', 'A', 'An ML pipeline chains stages such as ingestion, preprocessing, training, and evaluation into an automated workflow.', 'BEGINNER', 1, 'MCQ', 1),
(4030, 120, 'What is model drift in MLOps?', 'when the model is retrained', 'when the model is deleted', 'when the performance of a deployed model degrades as the data changes', 'when the model is too large to load', 'B', 'Model drift occurs when the real-world data diverges from the training distribution, degrading predictions over time.', 'BEGINNER', 1, 'MCQ', 1),
(4031, 120, 'A system must analyze millions of log lines arriving every second. Which approach is most appropriate?', 'stream processing that handles records as they arrive', 'a nightly batch job', 'manual analysis in a spreadsheet', 'printing all logs to a text file', 'A', 'Stream processing keeps up with the rate of arrival, while batch jobs would lag behind the live data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4032, 120, 'A model is retrained weekly but nobody knows which version produced last month''s predictions. What is missing?', 'more GPUs', 'model versioning and experiment tracking', 'a faster internet connection', 'manual retraining every day', 'B', 'Experiment tracking and versioning record exactly which model and data produced each result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4033, 120, 'Which concept describes splitting a large dataset across many machines to process parts in parallel?', 'single-threaded computing', 'manual copying', 'distributed computing', 'serial processing', 'C', 'Distributed computing partitions data and work across nodes so large jobs finish in parallel.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4034, 120, 'A model works in training but fails in production because the input format changed. Which practice prevents this?', 'training for more epochs', 'removing all logs', 'renaming the model', 'input validation and monitoring in the serving layer', 'D', 'Validating and monitoring inputs at serving time catches format changes before they corrupt predictions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4035, 120, 'What is the main difference between a data lake and a data warehouse?', 'a lake stores raw data in native format while a warehouse stores processed structured data', 'a lake is always faster', 'a warehouse stores only images', 'there is no difference', 'A', 'Data lakes preserve raw data of any type, whereas warehouses hold transformed, schema-defined data for analytics.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4036, 120, 'Which component continuously delivers a trained model to a serving environment?', 'a text editor', 'a CI/CD pipeline with automated model deployment', 'a spreadsheet', 'a web browser', 'B', 'A CI/CD pipeline automates the build, test, and deployment of models to production environments.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4037, 120, 'An organization has 5 TB of customer data. What benefit does Apache Spark provide over a single-machine pandas workload?', 'automatic data cleaning', 'distributed in-memory processing across a cluster for scalability', 'better looking charts', 'a built-in relational database', 'C', 'Spark scales by distributing computation across a cluster, so datasets far larger than one machine can be processed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4038, 120, 'A production model''s accuracy drops from 90% to 75% over three months. Which monitoring concept applies?', 'overfitting during training', 'underfitting', 'model drift, requiring retraining with recent data', 'data normalization', 'D', 'Gradual performance decay as the world changes is model drift, which retraining on fresh data addresses.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4039, 120, 'What is the purpose of a feature store in MLOps?', 'to provide a shared, consistent repository of engineered features for training and serving', 'to host webpages', 'to store raw logs only', 'to compile models', 'A', 'A feature store ensures training and serving use identical feature definitions, preventing train-serve skew.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4040, 120, 'Which practice is most important for reproducible model training runs?', 'pinning the versions of code, data, and libraries for each run', 'training on random data', 'deleting old runs', 'running every job manually', 'B', 'Pinning dependencies and data snapshots means any run can be exactly reproduced later.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4041, 120, 'A bank must explain every credit decision to regulators. Which MLOps design decision is most important?', 'model explainability and audit trails that record inputs, outputs, and versions', 'training the largest possible model', 'removing all logging', 'deploying only on one server', 'A', 'Regulatory requirements demand that each decision be explainable and traceable to a specific model and inputs.', 'ADVANCED', 3, 'MCQ', 1),
(4042, 120, 'Training and serving compute a feature differently, silently corrupting predictions. What is the industry-standard fix?', 'compute features once in a shared feature store used by both sides', 'duplicate the code by hand', 'disable all validation', 'use different features in each', 'B', 'A shared feature store guarantees identical feature values in training and serving, eliminating train-serve skew.', 'ADVANCED', 3, 'MCQ', 1),
(4043, 120, 'Kafka delivers events with at-least-once semantics. Which concern follows?', 'duplicate events may occur and downstream logic must be idempotent', 'no events ever arrive', 'events are always perfectly ordered', 'processing becomes impossible', 'C', 'At-least-once delivery can replay events, so consumers must tolerate or deduplicate duplicates idempotently.', 'ADVANCED', 3, 'MCQ', 1),
(4044, 120, 'Which strategy best handles sudden spikes in inference traffic without paying for idle capacity?', 'buying one permanently large server', 'queueing all requests forever', 'rejecting all requests', 'horizontal autoscaling that adds replicas based on load', 'D', 'Horizontal autoscaling adds serving instances during spikes and removes them when load drops.', 'ADVANCED', 3, 'MCQ', 1),
(4045, 120, 'A model is retrained nightly. Why is automated drift detection with rollback important?', 'a bad retraining run is caught quickly and the previous model is restored', 'retraining should never be monitored', 'rollback is technically impossible', 'drift never affects deployed models', 'A', 'Automated monitoring flags bad runs and rollback restores the last good model to protect production users.', 'ADVANCED', 3, 'MCQ', 1),
(4046, 120, 'To guarantee a pipeline rerun from the same snapshot produces identical results, what must be controlled?', 'random seeds, dependency versions, and the ordering of operations', 'only the file size', 'the number of clusters', 'the dashboard color', 'B', 'Controlling randomness, dependency versions, and deterministic ordering makes a rerun reproducible.', 'ADVANCED', 3, 'MCQ', 1),
(4047, 120, 'Which architecture is best for a low-latency real-time recommendation service?', 'a nightly batch scoring job', 'a precomputed model served through an optimized inference endpoint with cached features', 'manual lookups in a spreadsheet', 'training a new model per request', 'C', 'Serving a prepared model through an optimized endpoint with cached features keeps response latency very low.', 'ADVANCED', 3, 'MCQ', 1),
(4048, 120, 'A platform serves models for several teams. Which practice best isolates failures and resource use?', 'per-team namespaces with quotas, separate services, and centralized monitoring', 'one shared container with no limits', 'running everything on a single process', 'disabling all logging', 'D', 'Isolated namespaces and quotas contain a team''s failures and usage so they cannot affect others.', 'ADVANCED', 3, 'MCQ', 1),
(4049, 120, 'During canary deployment of a new model version, what is the purpose of routing a small fraction of traffic to it?', 'to compare its behavior with the stable version on live traffic before full rollout', 'to save bandwidth', 'to hide the model from users', 'to increase overall latency', 'A', 'A canary exposes the new model to a small slice of traffic so its live behavior can be validated before full rollout.', 'ADVANCED', 3, 'MCQ', 1),
(4050, 120, 'An organization collects unbounded IoT sensor data. Which storage choice best separates hot analysis from cold archival?', 'keep everything in memory', 'tiered storage with fast access for recent data and cheaper storage for archives', 'delete old data immediately', 'store all data on tape only', 'B', 'Tiered storage balances cost and access speed by keeping hot data fast and cold data cheap.', 'ADVANCED', 3, 'MCQ', 1),
(4051, 121, 'What does NLP stand for in artificial intelligence?', 'Natural Language Processing', 'Neural Language Programming', 'Natural Logic Processing', 'Neural Linear Programming', 'A', 'NLP is the branch of AI concerned with understanding and generating human language.', 'BEGINNER', 1, 'MCQ', 1),
(4052, 121, 'What is tokenization in NLP?', 'removing stop words', 'splitting text into smaller units called tokens', 'translating text between languages', 'tagging words with their parts of speech', 'B', 'Tokenization breaks a text into smaller units such as words, which are then analyzed.', 'BEGINNER', 1, 'MCQ', 1),
(4053, 121, 'What is a token in natural language processing?', 'a whole document', 'a list of documents', 'a single word or subword unit extracted from text', 'a punctuation mark only', 'C', 'A token is a meaningful unit, typically a word or subword, produced by splitting text.', 'BEGINNER', 1, 'MCQ', 1),
(4054, 121, 'Which of the following is an example of a corpus in NLP?', 'a single sentence', 'a tokenizer', 'a word embedding vector', 'a large collection of documents used for training models', 'D', 'A corpus is a large, structured collection of texts used for training and evaluation.', 'BEGINNER', 1, 'MCQ', 1),
(4055, 121, 'What are stop words in NLP?', 'common words like ''the'' and ''and'' that are often removed before analysis', 'rare technical terms kept for analysis', 'punctuation marks used to split sentences', 'numbers that must be normalized to words', 'A', 'Stop words are very frequent, low-information words that are usually filtered out.', 'BEGINNER', 1, 'MCQ', 1),
(4056, 121, 'Which step typically comes first in a basic NLP pipeline?', 'object detection', 'tokenization', 'image segmentation', 'speech synthesis', 'B', 'Tokenization is the first step because every later analysis operates on the tokens.', 'BEGINNER', 1, 'MCQ', 1),
(4057, 121, 'Which of the following is a basic NLP task?', 'edge detection', 'image classification', 'word tokenization', 'motion tracking', 'C', 'Word tokenization is a fundamental NLP task, unlike the vision tasks listed.', 'BEGINNER', 1, 'MCQ', 1),
(4058, 121, 'What is a document in NLP terminology?', 'a binary pixel array', 'a single character', 'a neural network layer', 'a body of text treated as a single unit of analysis', 'D', 'A document is any self-contained unit of text that is analyzed as a whole.', 'BEGINNER', 1, 'MCQ', 1),
(4059, 121, 'Which character is most commonly used to separate words during tokenization?', 'a space', 'a comma', 'a semicolon', 'a tab', 'A', 'Whitespace tokenization splits text on space characters, the most common word delimiter.', 'BEGINNER', 1, 'MCQ', 1),
(4060, 121, 'What is the output of a basic word tokenizer?', 'a single token', 'a sequence of tokens', 'a labeled image', 'a sorted list of characters', 'B', 'A tokenizer returns an ordered sequence of tokens derived from the input text.', 'BEGINNER', 1, 'MCQ', 1),
(4061, 121, 'How many tokens does whitespace tokenization produce for the sentence ''The quick brown fox jumps''?', '3', '4', '6', '5', 'D', 'There are exactly five words separated by spaces, so five tokens are produced.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4062, 121, 'The sentence ''She said, Hello!'' with punctuation removed contains how many word tokens?', '4', '5', '3', '2', 'C', 'After removing the comma and exclamation mark the tokens are She, said and Hello, which is three.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4063, 121, 'What is a subword tokenizer such as BPE mainly used for?', 'to merge sentences into paragraphs', 'to split words into smaller meaningful pieces to handle rare and out-of-vocabulary words', 'to remove all punctuation from the text', 'to count how many documents exist in a corpus', 'B', 'Subword tokenizers break words into smaller pieces so that rare and unseen words can still be represented.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4064, 121, 'What is the difference between stemming and lemmatization?', 'stemming chops endings without a vocabulary, while lemmatization uses a dictionary to return base forms', 'lemmatization is faster than stemming', 'stemming always produces valid English words', 'they are two names for the same operation', 'A', 'Stemming applies crude rules, while lemmatization consults a lexicon to produce real base forms.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4065, 121, 'For the string ''New York is a city'', if ''New York'' is kept as a single token, how many tokens result?', '2', '3', '5', '4', 'D', 'The tokens are New York, is, a and city, giving four tokens in total.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4066, 121, 'A corpus has 1000 documents and each document averages 120 tokens. Approximately how many tokens are in the corpus?', '100000', '120000', '1200', '1000', 'B', 'Multiplying 1000 documents by 120 tokens gives about 120000 tokens.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4067, 121, 'What is a common problem with whitespace tokenization of text like ''can''t'' or ''U.S.A.''?', 'it splits words into characters', 'it is extremely slow on short text', 'contractions and abbreviations are split into fragments that lose meaning', 'it always merges multiple words together', 'C', 'Whitespace tokenization leaves apostrophes and periods attached, breaking contractions and abbreviations incorrectly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4068, 121, 'What does the choice between word-level and subword-level tokenization mainly affect?', 'the vocabulary size and the handling of rare or unseen words', 'the color depth of the image', 'the length of the document in characters only', 'the number of sentences in the document', 'A', 'Subword tokenization shrinks the vocabulary and gives a way to represent words that were never seen in training.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4069, 121, 'Why might lowercase normalization be applied during tokenization?', 'to increase model accuracy for named entities', 'to keep proper nouns distinct', 'to preserve punctuation', 'to reduce the vocabulary size by treating words case-insensitively', 'D', 'Lowercasing collapses ''The'' and ''the'' into one token, shrinking the vocabulary.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4070, 121, 'Which of the following is a widely used multilingual subword tokenization algorithm?', 'ImageNet', 'Eigenfaces', 'Byte Pair Encoding (BPE)', 'K-means clustering', 'C', 'BPE learns a subword vocabulary from byte statistics and works across many languages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4071, 121, 'Why is standard whitespace tokenization problematic when building a tokenizer for Twitter data?', 'the whitespace is always reliable on Twitter', 'tweets contain hashtags, mentions, emojis and URLs that need special handling', 'tweets are too short to tokenize', 'tokenizers cannot run on social media text', 'B', 'Social media text is full of hashtags, mentions, emojis and URLs that require custom rules.', 'ADVANCED', 3, 'MCQ', 1),
(4072, 121, 'How many sentences should a correct sentence tokenizer output for ''Dr. Smith went to Washington. He met Sen. Adams.''?', '2', '3', '4', '5', 'A', 'There are two real sentences because the periods in ''Dr.'' and ''Sen.'' are abbreviations, not sentence boundaries.', 'ADVANCED', 3, 'MCQ', 1),
(4073, 121, 'What is a key advantage of subword tokenization such as WordPiece over plain word-level tokenization for neural models?', 'it removes all ambiguity from text', 'it makes every token a full dictionary word', 'it always increases the sequence length', 'it balances a fixed vocabulary with the ability to represent rare and unseen words', 'D', 'Subword tokenization keeps the vocabulary bounded while still covering rare and unknown words.', 'ADVANCED', 3, 'MCQ', 1),
(4074, 121, 'At a scale of 10 million documents, which factor most limits the throughput of a Python regex-based tokenizer on a single CPU?', 'the color of the corpus text', 'the output file format', 'the sequential regex processing speed on a single CPU', 'the length of the tokenizer source code', 'C', 'Regex matching runs sequentially on one CPU and becomes a bottleneck for very large corpora.', 'ADVANCED', 3, 'MCQ', 1),
(4075, 121, 'In Byte Pair Encoding, what does the merge step do?', 'it removes the rarest characters from the text', 'it repeatedly merges the most frequent adjacent pairs of tokens into new tokens', 'it translates the text to another language', 'it sorts the vocabulary in alphabetical order', 'B', 'BPE iteratively merges the most frequent adjacent token pairs to grow its subword vocabulary.', 'ADVANCED', 3, 'MCQ', 1),
(4076, 121, 'Why might a tokenizer that strips all punctuation hurt a sentiment analysis model?', 'punctuation like ''!!!'' carries sentiment information and emojis may be lost', 'punctuation is always neutral in meaning', 'stripping punctuation speeds up the model', 'punctuation never appears in reviews', 'A', 'Exclamation marks and emojis encode strong sentiment, so removing them destroys signal.', 'ADVANCED', 3, 'MCQ', 1),
(4077, 121, 'What is the key algorithmic difference between BPE and WordPiece?', 'they are identical algorithms', 'WordPiece merges random pairs', 'BPE works only on English text', 'BPE merges the most frequent byte pair, while WordPiece merges the pair that maximizes language-model likelihood', 'D', 'BPE is driven by raw pair frequency, whereas WordPiece chooses pairs that best improve the model likelihood.', 'ADVANCED', 3, 'MCQ', 1),
(4078, 121, 'When tokenizing source code identifiers like ''user_id'' or ''camelCase'', which preprocessing helps the most?', 'lowercasing every character', 'removing all letters', 'splitting on underscores and detecting camel-case boundaries', 'translating identifiers to English words', 'C', 'Splitting on underscores and detecting case transitions recovers the meaningful word components.', 'ADVANCED', 3, 'MCQ', 1),
(4079, 121, 'An out-of-vocabulary word appears during inference that the model never saw in training. With subword tokenization, how is it typically handled?', 'the word is dropped from the output', 'it is represented by composing its known subword pieces', 'the model must be retrained', 'the whole sentence is discarded', 'B', 'The word is covered by combining its subword units, which is exactly why subword tokenization is used.', 'ADVANCED', 3, 'MCQ', 1),
(4080, 121, 'What trade-off must be made when choosing the vocabulary size of a BPE tokenizer?', 'a larger vocabulary gives shorter sequences but needs more parameters and memory', 'a larger vocabulary always improves accuracy without cost', 'a smaller vocabulary gives shorter sequences', 'vocabulary size has no effect on the model', 'A', 'Bigger vocabularies encode text more compactly but require a larger embedding table and more memory.', 'ADVANCED', 3, 'MCQ', 1),
(4081, 122, 'What does TF stand for in the TF-IDF weighting scheme?', 'image frequency', 'inverse feature map', 'term frequency, how often a term appears in a document', 'tensor flow', 'C', 'Term frequency counts how many times a term occurs within a single document.', 'BEGINNER', 1, 'MCQ', 1),
(4082, 122, 'What does IDF stand for in the TF-IDF weighting scheme?', 'a deep network', 'a pooling layer', 'a token', 'inverse document frequency, how rare a term is across the corpus', 'D', 'Inverse document frequency measures how rare a term is across all documents in the corpus.', 'BEGINNER', 1, 'MCQ', 1),
(4083, 122, 'Which of the following is a bag-of-words representation of a text?', 'a vector counting how many times each vocabulary word appears in a text', 'a list of all sentences', 'an image of pixel intensities', 'a sorted set of unique characters', 'A', 'The bag-of-words model represents text as a vector of word counts without regard to order.', 'BEGINNER', 1, 'MCQ', 1),
(4084, 122, 'What is an n-gram?', 'a machine learning model', 'a contiguous sequence of n items from a text', 'a type of neural network', 'a database index', 'B', 'An n-gram is any contiguous sequence of n tokens drawn from a piece of text.', 'BEGINNER', 1, 'MCQ', 1),
(4085, 122, 'Which of the following is a unigram feature?', 'a paragraph', 'a chapter', 'the word ''cat'' in a sentence', 'an entire corpus', 'C', 'A unigram is a single word, so the word ''cat'' is an example of a unigram feature.', 'BEGINNER', 1, 'MCQ', 1),
(4086, 122, 'What is a document-term matrix?', 'a matrix of pixel values', 'a confusion matrix', 'a covariance matrix', 'a matrix where rows are documents and columns are vocabulary terms', 'D', 'A document-term matrix records the weight of each vocabulary term for each document.', 'BEGINNER', 1, 'MCQ', 1),
(4087, 122, 'What is TF-IDF weighting used for?', 'to weight the importance of a term for a document relative to the corpus', 'to compress images', 'to detect faces', 'to translate languages', 'A', 'TF-IDF assigns higher weights to terms that are frequent in a document but rare across the corpus.', 'BEGINNER', 1, 'MCQ', 1),
(4088, 122, 'What does stemming do in text processing?', 'removes all vowels', 'reduces words to their root form, such as ''running'' to ''run''', 'adds prefixes to words', 'sorts words alphabetically', 'B', 'Stemming strips affixes so that inflected forms collapse to a common root.', 'BEGINNER', 1, 'MCQ', 1),
(4089, 122, 'Which of the following is a bigram of the sentence ''I love NLP''?', 'I love NLP', 'love NLP', 'NLP I', 'I NLP love', 'C', 'A bigram is a sequence of two adjacent words, and ''love NLP'' fits that definition.', 'BEGINNER', 1, 'MCQ', 1),
(4090, 122, 'What is text normalization?', 'training a neural network', 'compressing images', 'parsing a web page', 'converting text to a standard form such as lowercasing and removing punctuation', 'D', 'Normalization brings text into a consistent form so that later features are cleaner.', 'BEGINNER', 1, 'MCQ', 1),
(4091, 122, 'In a 15-word document, the word ''cat'' appears 3 times. What is the raw term frequency of ''cat''?', '3', '4', '15', '0', 'A', 'Term frequency is simply the count of the term in the document, which is 3.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4092, 122, 'A term appears in 2 of 10 documents. What is its document frequency?', '1', '2', '10', '8', 'B', 'Document frequency is the number of documents containing the term, which is 2.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4093, 122, 'Which term will TF-IDF weight higher for a document: ''the'' appearing many times or a rare domain term appearing once?', 'the word ''the''', 'both equally', 'the rare domain term, because IDF rewards rarity', 'neither, because TF-IDF ignores frequency', 'C', 'The rare term has a high IDF, so TF-IDF rewards it even though it appears only once.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4094, 122, 'What are the bigrams of the sentence ''the cat sat on the mat''?', 'cat, mat, sat, the', 'the cat sat on the mat', 'the, cat', 'the cat, cat sat, sat on, on the, the mat', 'D', 'Each adjacent pair forms a bigram, giving five bigrams for this six-word sentence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4095, 122, 'With TF-IDF, what happens to terms that appear in every document, such as ''the''?', 'their IDF becomes near zero, so they receive low weight', 'their IDF becomes very large', 'their TF is set to zero', 'they are removed from the vocabulary permanently', 'A', 'A term in all documents has a document frequency equal to the corpus size, making its IDF near zero.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4096, 122, 'How many unigrams does the string ''I love NLP'' produce after whitespace tokenization?', '1', '3', '5', '2', 'B', 'The string splits into the three words I, love and NLP, giving three unigrams.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4097, 122, 'What information does the bag-of-words representation lose?', 'the total word count', 'the document length', 'word order and grammar', 'the encoding used', 'C', 'Bag-of-words only keeps counts, so the order in which words appear is discarded.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4098, 122, 'What is the difference between term frequency and document frequency?', 'they are identical', 'document frequency counts within a document', 'term frequency counts across documents', 'term frequency counts within a document; document frequency counts across documents', 'D', 'Term frequency is per-document, while document frequency is a count of documents containing the term.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4099, 122, 'Why is stop word removal often applied before building TF-IDF features?', 'to remove very common words that carry little discriminative value', 'to keep every word in the vocabulary', 'to shorten the documents', 'to improve spelling', 'A', 'Stop words are common and uninformative, so removing them reduces noise in the feature space.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4100, 122, 'In the IDF formula log(N/df), what happens to the value as df approaches N?', 'the value approaches infinity', 'the value approaches 0', 'the value stays at 1', 'the value becomes negative', 'B', 'When a term appears in nearly all N documents, N/df approaches 1 and its log approaches 0.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4101, 122, 'When building TF-IDF vectors for 50k documents with a large vocabulary, why is a sparse matrix preferred over a dense one?', 'sparse matrices are always slower', 'dense matrices are always smaller', 'documents cannot be stored in matrices', 'most entries are zero and a sparse representation saves memory', 'D', 'Each document uses only a few of the vocabulary terms, so a sparse matrix avoids storing mostly zero entries.', 'ADVANCED', 3, 'MCQ', 1),
(4102, 122, 'A corpus has 1000 documents and the term ''data'' appears in 250 of them. Ignoring smoothing, what is the IDF term for ''data''?', 'log(250)', 'log(1000)', 'log(4)', '250', 'C', 'The IDF is log(1000/250), which simplifies to log(4).', 'ADVANCED', 3, 'MCQ', 1),
(4103, 122, 'Why are character n-grams preferred over word n-grams for noisy social media text?', 'they capture long-range syntax perfectly', 'they are robust to spelling variations and abbreviations', 'they ignore all meaning', 'they always produce exactly one feature per sentence', 'B', 'Character n-grams tolerate misspellings and shorthand because they match on character substrings.', 'ADVANCED', 3, 'MCQ', 1),
(4104, 122, 'Which normalization of TF-IDF document vectors often improves the performance of text classifiers?', 'L2 (Euclidean) normalization of each document vector', 'removing all numeric features', 'increasing the vocabulary size randomly', 'using only the first character of each word', 'A', 'L2 normalization makes all documents unit-length, which stabilizes similarity and many classifiers.', 'ADVANCED', 3, 'MCQ', 1),
(4105, 122, 'After computing TF-IDF vectors, which similarity measure is most commonly used to compare two documents?', 'Euclidean distance only', 'Manhattan distance only', 'Hamming distance', 'cosine similarity', 'D', 'Cosine similarity measures the angle between vectors and is standard for TF-IDF comparisons.', 'ADVANCED', 3, 'MCQ', 1),
(4106, 122, 'A term appears frequently in every document of a corpus. How is its TF-IDF weight best described?', 'very high, because it appears often', 'exactly zero, always', 'very low, because IDF approaches zero', 'undefined', 'C', 'Because the term is in all documents its IDF is near zero, pulling the whole weight down.', 'ADVANCED', 3, 'MCQ', 1),
(4107, 122, 'With 1 million documents and a vocabulary of 100k terms, what is the memory concern with a dense document-term matrix?', 'it would fit in a few megabytes', 'a dense matrix would need 100 billion entries, which is infeasible', 'sparse matrices cannot store 1 million documents', 'the vocabulary must be reduced to 100 terms', 'B', 'A dense matrix would hold 1 million times 100k, or 100 billion, entries, which is far too large.', 'ADVANCED', 3, 'MCQ', 1),
(4108, 122, 'What is a serious problem with pure bag-of-words features for sentiment analysis?', 'it ignores negation, so ''not good'' looks like ''good''', 'it always knows the word order', 'it cannot count words', 'it only uses nouns', 'A', 'Without word order, the phrase ''not good'' is reduced to the positive word ''good''.', 'ADVANCED', 3, 'MCQ', 1),
(4109, 122, 'What is the effect of using sublinear term-frequency scoring such as 1 + log(tf)?', 'it boosts rare terms more', 'it removes all terms', 'it doubles every term frequency', 'it dampens the effect of very high term frequencies', 'D', 'The log transform compresses large counts so that very frequent terms do not dominate.', 'ADVANCED', 3, 'MCQ', 1),
(4110, 122, 'A TF-IDF model trained on English news is applied to code-mixed Hindi-English text. What is the most likely problem?', 'English is easier to tokenize', 'news text has no punctuation', 'the vocabulary and IDF statistics do not match the target domain', 'code-mixed text is always perfectly tokenized', 'C', 'Domain mismatch means the learned vocabulary and IDF weights do not fit the new data.', 'ADVANCED', 3, 'MCQ', 1),
(4111, 123, 'How is an image represented for a computer vision system?', 'a list of words', 'a 2D grid of pixel intensity values', 'a graph of characters', 'a collection of audio samples', 'B', 'A digital image is stored as a two-dimensional grid of pixel values.', 'BEGINNER', 1, 'MCQ', 1),
(4112, 123, 'What is a pixel?', 'the smallest unit of an image, holding a brightness or color value', 'a line of text', 'a neural network', 'a whole photo', 'A', 'A pixel is the smallest addressable element of an image, storing intensity or color.', 'BEGINNER', 1, 'MCQ', 1),
(4113, 123, 'What does RGB stand for?', 'Random, Gray, Black', 'Red, Gray, Blue', 'Green, Red, Binary', 'Red, Green, Blue', 'D', 'RGB is the color model built from the three additive primary colors red, green and blue.', 'BEGINNER', 1, 'MCQ', 1),
(4114, 123, 'A grayscale image typically has how many color channels?', 'three', 'two', 'one', 'four', 'C', 'Grayscale images use a single channel that holds the intensity of each pixel.', 'BEGINNER', 1, 'MCQ', 1),
(4115, 123, 'What is image classification?', 'finding the subject''s age', 'assigning a label to an entire image', 'predicting the next word', 'translating speech to text', 'B', 'Image classification assigns one class label to the whole image.', 'BEGINNER', 1, 'MCQ', 1),
(4116, 123, 'What is object detection?', 'locating objects in an image and classifying them', 'converting text to speech', 'summarizing a document', 'clustering documents', 'A', 'Object detection finds bounding boxes around objects and labels each one.', 'BEGINNER', 1, 'MCQ', 1),
(4117, 123, 'Which dataset is most commonly used for image classification benchmarks?', 'LibriSpeech', 'MSP-IMPROV', 'CoNLL-2003', 'ImageNet', 'D', 'ImageNet is the standard benchmark for image classification research.', 'BEGINNER', 1, 'MCQ', 1),
(4118, 123, 'How is an RGB image of height H and width W stored?', 'a single integer', 'a string of characters', 'a three-channel array of shape (H, W, 3)', 'a binary decision tree', 'C', 'An RGB image is a three-dimensional array with one channel per color.', 'BEGINNER', 1, 'MCQ', 1),
(4119, 123, 'What is image segmentation?', 'assigning one label to the whole image', 'classifying each pixel of an image into a category', 'finding the nearest image in a database', 'ranking documents by relevance', 'B', 'Segmentation labels every pixel so that different regions belong to different classes.', 'BEGINNER', 1, 'MCQ', 1),
(4120, 123, 'In a grayscale image, what does a pixel value of 0 represent?', 'black', 'white', 'red', 'transparent', 'A', 'In 8-bit grayscale, a value of 0 corresponds to the darkest intensity, black.', 'BEGINNER', 1, 'MCQ', 1),
(4121, 123, 'A 640x480 RGB image stored as unsigned 8-bit integers contains how many bytes?', '307200', '640', '921600', '480', 'C', '640 times 480 pixels times 3 channels gives 921600 bytes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4122, 123, 'A 512x512 grayscale image contains how many pixels?', '512', '1024', '51200', '262144', 'D', '512 multiplied by 512 equals 262144 pixels.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4123, 123, 'What does a kernel or filter in a convolutional layer do?', 'slides over the image to detect local features', 'labels each pixel manually', 'compresses the image to one byte', 'generates captions for the image', 'A', 'A filter slides across the image and computes weighted sums to detect local patterns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4124, 123, 'What is stride in a convolutional operation?', 'the number of filters', 'the step size by which the filter moves across the image', 'the number of channels', 'the learning rate', 'B', 'Stride controls how far the filter moves at each step across the input.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4125, 123, 'Why is padding used in convolution?', 'to increase the number of classes', 'to remove noise entirely', 'to preserve spatial dimensions and use edge pixels', 'to double the image size always', 'C', 'Padding adds a border of zeros so the output size is preserved and edge pixels are included.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4126, 123, 'A 5x5 image convolved with a 3x3 filter using stride 1 and no padding gives an output of what size?', '5x5', '4x4', '7x7', '3x3', 'D', 'Without padding, the output is (5-3+1) by (5-3+1), which is 3x3.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4127, 123, 'What is global average pooling commonly used for at the end of a classification CNN?', 'replacing the flatten-and-fully-connected block to produce a class score vector', 'blurring the input image', 'increasing the spatial resolution', 'reducing the number of classes', 'A', 'Global average pooling averages each feature map into a single value, creating a compact vector for classification while reducing parameters and overfitting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4128, 123, 'What does max pooling do?', 'averages all values in the image', 'takes the maximum value in each pooling window', 'takes the minimum value of the whole image', 'sums the pixel values', 'B', 'Max pooling keeps the largest value inside each small window of the feature map.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4129, 123, 'What is a convolution in image terms?', 'a bitwise OR of pixels', 'a random shuffle of pixels', 'an element-wise product and sum between a filter and an image patch', 'a simple pixel value swap', 'C', 'Convolution multiplies a filter elementwise with an image patch and sums the result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4130, 123, 'What does a larger receptive field allow a convolutional network to perceive?', 'a smaller output', 'fewer parameters', 'better color accuracy', 'more context from a larger region of the image', 'D', 'A larger receptive field lets deeper layers aggregate information from a wider image region.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4131, 123, 'Why do CNN feature maps typically increase in channels while shrinking in spatial size across layers?', 'to extract more abstract high-level features while keeping computation manageable', 'to preserve the original pixel values', 'to reduce the number of classes', 'to make the model smaller by removing layers', 'A', 'Deep layers encode richer abstractions in more channels while the smaller spatial size controls cost.', 'ADVANCED', 3, 'MCQ', 1),
(4132, 123, 'What is the receptive field of two stacked 3x3 filters compared with a single larger filter?', '3x3', '5x5', '9x9', '1x1', 'B', 'Two 3x3 filters cover a 5x5 region, matching one 5x5 filter with fewer parameters.', 'ADVANCED', 3, 'MCQ', 1),
(4133, 123, 'Why are 1x1 convolutions useful in modern CNNs?', 'they blur the image', 'they detect edges only', 'they mix channels cheaply to change the number of feature maps', 'they increase spatial resolution', 'C', 'A 1x1 convolution performs a linear combination of channels without changing spatial size.', 'ADVANCED', 3, 'MCQ', 1),
(4134, 123, 'What training problem does batch normalization primarily address?', 'overfitting', 'class imbalance', 'memory leaks', 'internal covariate shift by normalizing layer inputs to stabilize training', 'D', 'Batch normalization normalizes activations to keep layer inputs stable and training faster.', 'ADVANCED', 3, 'MCQ', 1),
(4135, 123, 'Which architecture introduced residual (skip) connections to combat vanishing gradients?', 'ResNet', 'LeNet-1', 'AlexNet without skip connections', 'a linear regression', 'A', 'ResNet''s skip connections let gradients flow directly through identity paths, enabling very deep networks.', 'ADVANCED', 3, 'MCQ', 1),
(4136, 123, 'What is transfer learning in computer vision?', 'training from scratch each time', 'fine-tuning a pretrained model on a new, often smaller dataset', 'removing all pretrained weights', 'using only random weights', 'B', 'Transfer learning reuses features learned on a large dataset and adapts them to a new task.', 'ADVANCED', 3, 'MCQ', 1),
(4137, 123, 'When fine-tuning a pretrained network on a small dataset, what should typically be done with the early layers?', 'reinitialize them randomly', 'delete them', 'freeze them since they capture generic features such as edges and textures', 'train them with a higher learning rate than the head', 'C', 'Early layers learn generic low-level features that transfer well, so they are usually frozen.', 'ADVANCED', 3, 'MCQ', 1),
(4138, 123, 'What does data augmentation do for a vision model?', 'labels each image by hand', 'compresses the model', 'removes the need for a test set', 'creates variations of the training images to improve generalization', 'D', 'Augmentation applies transforms like flips and crops to enlarge the training distribution.', 'ADVANCED', 3, 'MCQ', 1),
(4139, 123, 'Which of the following is an example of data augmentation for images?', 'random horizontal flip', 'random string replacement', 'random document merging', 'random audio mixing', 'A', 'Flipping an image horizontally is a classic augmentation that creates a new training sample.', 'ADVANCED', 3, 'MCQ', 1),
(4140, 123, 'What is the role of the final fully connected layer in a classification CNN?', 'applies a blur kernel', 'maps the learned features into class scores', 'detects corners only', 'reduces the number of images', 'B', 'The last layer projects the feature vector into a score for each class, which softmax then normalizes.', 'ADVANCED', 3, 'MCQ', 1),
(4141, 124, 'What is image resizing?', 'changing the file name', 'adding a watermark', 'converting to text', 'changing the width and height of an image', 'D', 'Resizing scales an image to new width and height dimensions.', 'BEGINNER', 1, 'MCQ', 1),
(4142, 124, 'What is an image filter?', 'a type of neural network', 'a file format', 'an operation that transforms pixel values, such as blur or sharpen', 'a list of class labels', 'C', 'A filter is an operation that transforms pixel values, for example to blur or sharpen.', 'BEGINNER', 1, 'MCQ', 1),
(4143, 124, 'What does image thresholding do?', 'detects faces', 'converts pixels into two classes based on an intensity threshold', 'merges two images', 'compresses the image into a zip file', 'B', 'Thresholding maps each pixel to one of two classes according to an intensity cutoff.', 'BEGINNER', 1, 'MCQ', 1),
(4144, 124, 'What is edge detection used for in image processing?', 'highlighting boundaries where intensity changes sharply', 'removing the background color', 'adding a caption', 'blurring the whole image', 'A', 'Edge detection locates boundaries where pixel intensity changes sharply.', 'BEGINNER', 1, 'MCQ', 1),
(4145, 124, 'What is an image histogram?', 'a sorted list of filenames', 'a matrix of gradients', 'a set of labels', 'a distribution of pixel intensity values', 'D', 'An image histogram shows how often each intensity value occurs.', 'BEGINNER', 1, 'MCQ', 1),
(4146, 124, 'What is contrast in an image?', 'the file size', 'the resolution', 'the difference in brightness between regions of an image', 'the number of colors in the RGB model', 'C', 'Contrast describes how much brightness differs between the light and dark areas of an image.', 'BEGINNER', 1, 'MCQ', 1),
(4147, 124, 'What is grayscale conversion?', 'adding a blue channel', 'converting a color image to a single intensity channel', 'rotating the image', 'splitting the image into two files', 'B', 'Grayscale conversion reduces an RGB image to a single luminance channel.', 'BEGINNER', 1, 'MCQ', 1),
(4148, 124, 'What is image cropping?', 'removing the region of the image outside a chosen rectangle', 'increasing the contrast', 'adding noise', 'converting to grayscale', 'A', 'Cropping keeps only the part of the image inside a selected rectangle.', 'BEGINNER', 1, 'MCQ', 1),
(4149, 124, 'What is brightness in image processing?', 'the number of edges', 'the image format', 'the resolution', 'the overall light intensity of an image', 'D', 'Brightness is the overall level of light intensity across an image.', 'BEGINNER', 1, 'MCQ', 1),
(4150, 124, 'What is the effect of applying a blur filter?', 'it sharpens every edge', 'it adds random noise', 'it smooths the image by averaging nearby pixels', 'it removes color entirely', 'C', 'Blurring averages neighboring pixel values, which smooths and softens the image.', 'BEGINNER', 1, 'MCQ', 1),
(4151, 124, 'An image is downsampled from 2000x2000 to 1000x1000. What happens to its spatial resolution?', 'the resolution stays the same', 'the resolution halves', 'the resolution doubles', 'the image becomes binary', 'B', 'Both dimensions are halved, so the spatial resolution is cut in half.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4152, 124, 'When a 3x3 average blur kernel is applied, what value is assigned to each output pixel?', 'the average of the 3x3 neighborhood', 'the maximum of the 3x3 neighborhood', 'the center pixel unchanged', 'the sum of all pixels in the image', 'A', 'The average filter replaces each pixel with the mean of its 3x3 neighborhood.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4153, 124, 'What does histogram equalization do to an image?', 'removes all low values', 'converts to binary', 'adds noise', 'redistributes intensities to improve contrast', 'D', 'Histogram equalization spreads out intensity values to enhance contrast.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4154, 124, 'Why is a low-pass filter (blur) applied before edge detection?', 'to increase the resolution', 'to add color', 'to reduce noise that would create false edges', 'to speed up edge detection by removing pixels', 'C', 'Blurring suppresses high-frequency noise that would otherwise create spurious edges.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4155, 124, 'Applying a binary threshold at 128 to a grayscale image produces how many distinct output intensity levels?', '256', 'two', '128', 'one', 'B', 'A binary threshold maps every pixel to one of two values, typically 0 or 255.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4156, 124, 'What does the Sobel operator compute?', 'image gradients used for edge detection', 'a histogram of colors', 'a machine learning classifier', 'a type of image compression', 'A', 'Sobel filters estimate the image gradient magnitude and direction for edge detection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4157, 124, 'Which morphological operation would you use to remove small white specks of noise from a binary image?', 'histogram equalization', 'gamma correction', 'color quantization', 'morphological opening', 'D', 'Opening applies erosion followed by dilation, which removes small bright specks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4158, 124, 'What does dilation do to a binary image?', 'shrinks white regions', 'removes all white pixels', 'expands white regions', 'converts to grayscale', 'C', 'Dilation grows the white regions by adding pixels to their boundaries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4159, 124, 'Why is the HSV color space often used instead of RGB for color thresholding?', 'to add more channels', 'to separate color hue from intensity for easier thresholding', 'to reduce the image to one pixel', 'to increase the file size', 'B', 'HSV isolates hue from illumination, so color regions can be selected by hue alone.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4160, 124, 'In the Canny edge detector, what does non-maximum suppression do?', 'thins edges by keeping only local maxima of gradient magnitude', 'blurs the gradient image', 'doubles the edge width', 'removes all edges', 'A', 'Non-maximum suppression keeps only the strongest gradient response along each edge direction.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4161, 124, 'A photograph has very poor contrast in the shadowed areas. Which technique best improves visibility?', 'grayscale conversion only', 'increasing brightness', 'histogram equalization or CLAHE', 'edge detection', 'C', 'CLAHE enhances local contrast, making details in dark regions visible.', 'ADVANCED', 3, 'MCQ', 1),
(4162, 124, 'For OCR of scanned documents, which preprocessing sequence typically helps the most?', 'color inversion and rotation', 'random cropping', 'adding noise', 'grayscale conversion, binarization and deskewing', 'D', 'Grayscale conversion, thresholding and correcting skew give a clean binary text image.', 'ADVANCED', 3, 'MCQ', 1),
(4163, 124, 'Among thousands of frames, which statistic is a good indicator that a frame is blurry?', 'low variance of the Laplacian', 'high saturation', 'high average brightness', 'large file size', 'A', 'A blurry image has weak high-frequency content, giving a low-variance Laplacian response.', 'ADVANCED', 3, 'MCQ', 1),
(4164, 124, 'A Gaussian filter with a larger sigma produces what effect?', 'sharper edges', 'more smoothing and a wider neighborhood influence', 'no change', 'a smaller image', 'B', 'Larger sigma widens the Gaussian, blending more distant pixels and smoothing more.', 'ADVANCED', 3, 'MCQ', 1),
(4165, 124, 'What is morphological erosion useful for?', 'expanding white regions', 'adding bright noise', 'removing small bright noise and shrinking white regions', 'doubling the resolution', 'C', 'Erosion shrinks white regions and removes small bright artifacts from binary images.', 'ADVANCED', 3, 'MCQ', 1),
(4166, 124, 'In a 60 fps video pipeline running on embedded hardware, which operation should be minimized to keep up with real time?', 'image saving', 'frame indexing', 'reading the frame counter', 'expensive full-image convolutions with large kernels', 'D', 'Large-kernel full-image convolutions are computationally heavy and strain real-time throughput.', 'ADVANCED', 3, 'MCQ', 1),
(4167, 124, 'Why is the L*a*b* color space sometimes preferred over RGB for image segmentation?', 'L*a*b* separates luminance from perceptually meaningful color channels', 'RGB is smaller than LAB', 'LAB cannot represent colors', 'LAB has fewer channels than grayscale', 'A', 'L*a*b* isolates lightness so that color distances match human perception better.', 'ADVANCED', 3, 'MCQ', 1),
(4168, 124, 'What is the purpose of Otsu''s method in image thresholding?', 'detecting faces', 'automatically choosing a threshold that minimizes within-class variance', 'converting to HSV', 'adding contrast', 'B', 'Otsu picks the threshold that best separates two intensity classes by minimizing within-class variance.', 'ADVANCED', 3, 'MCQ', 1),
(4169, 124, 'A camera produces 8-bit images but the useful intensities occupy only the 50-150 range. Which operation expands this range?', 'erosion', 'dilation', 'histogram stretching (min-max normalization)', 'binary opening', 'C', 'Min-max stretching rescales intensities so the full 0-255 range is used.', 'ADVANCED', 3, 'MCQ', 1),
(4170, 124, 'When merging several camera exposures into one HDR image, what is required before combining the frames?', 'downsampling each image', 'removing color', 'combining them randomly', 'aligning the images before merging to avoid ghosting', 'D', 'The frames must be aligned so that moving objects do not create ghost artifacts.', 'ADVANCED', 3, 'MCQ', 1),
(4171, 125, 'What is machine translation?', 'automatically translating text from one language to another', 'detecting faces in photos', 'compressing videos', 'generating music', 'A', 'Machine translation converts text from a source language into a target language automatically.', 'BEGINNER', 1, 'MCQ', 1),
(4172, 125, 'What is named entity recognition (NER)?', 'counting pixels', 'identifying entities such as persons, places and organizations in text', 'blurring images', 'recognizing speech', 'B', 'NER locates and classifies named entities such as people, places and organizations.', 'BEGINNER', 1, 'MCQ', 1),
(4173, 125, 'What is sentiment analysis?', 'detecting edges', 'predicting stock prices', 'determining the emotion or opinion expressed in text', 'classifying images', 'C', 'Sentiment analysis classifies the opinion or emotion expressed in a piece of text.', 'BEGINNER', 1, 'MCQ', 1),
(4174, 125, 'What is a chatbot?', 'a virus scanner', 'an image editor', 'a database', 'a program that holds a conversation with a user', 'D', 'A chatbot is a system designed to converse with users in natural language.', 'BEGINNER', 1, 'MCQ', 1),
(4175, 125, 'What is facial recognition?', 'identifying or verifying a person from their face', 'translating documents', 'tokenizing text', 'summarizing news', 'A', 'Facial recognition identifies or verifies individuals using features of their face.', 'BEGINNER', 1, 'MCQ', 1),
(4176, 125, 'What is image captioning?', 'converting speech to text', 'generating a natural language description of an image', 'detecting spam emails', 'clustering documents', 'B', 'Image captioning generates a natural language sentence describing an image''s content.', 'BEGINNER', 1, 'MCQ', 1),
(4177, 125, 'What is optical character recognition (OCR)?', 'recognizing faces', 'translating audio', 'extracting text from images or scanned documents', 'predicting movie ratings', 'C', 'OCR converts text embedded in images or scans into machine-readable characters.', 'BEGINNER', 1, 'MCQ', 1),
(4178, 125, 'What is the primary computer vision task in autonomous driving?', 'summarizing traffic reports', 'translating signs', 'playing chess', 'detecting and tracking objects such as cars and pedestrians', 'D', 'Self-driving systems rely heavily on detecting and tracking objects around the vehicle.', 'BEGINNER', 1, 'MCQ', 1),
(4179, 125, 'How can text be used in a recommendation system?', 'suggesting items using textual features such as reviews', 'rendering 3D scenes', 'detecting motion', 'encoding audio', 'A', 'Text like reviews and product descriptions provides features for recommending items.', 'BEGINNER', 1, 'MCQ', 1),
(4180, 125, 'What is text summarization?', 'converting a document to images', 'producing a shorter version that preserves the main points', 'translating a document', 'printing a document', 'B', 'Summarization condenses a document while keeping its most important information.', 'BEGINNER', 1, 'MCQ', 1),
(4181, 125, 'Which architecture is most commonly used for modern neural machine translation?', 'the Perceptron', 'Naive Bayes', 'K-means', 'the Transformer', 'D', 'Transformer-based models dominate state-of-the-art machine translation systems.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4182, 125, 'A review says ''The battery lasts long''. Which NLP task best extracts ''battery'' as the product aspect being discussed?', 'named entity recognition', 'machine translation', 'aspect-based sentiment analysis', 'text-to-speech', 'C', 'Aspect-based sentiment analysis identifies the specific product aspect and its sentiment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4183, 125, 'For recognizing handwritten digits such as in the MNIST dataset, which model type is standard?', 'a decision tree on raw pixels', 'a CNN', 'a logistic regression on pixels only', 'an A* search', 'B', 'CNNs learn spatial features and achieve the best accuracy on handwritten digit recognition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4184, 125, 'What is the primary input to a Transformer model for translation?', 'token embeddings plus positional encodings', 'only raw pixel values', 'only random numbers', 'a sorted list of words', 'A', 'Transformers take token embeddings combined with positional encodings to preserve word order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4185, 125, 'In a visual question answering (VQA) system, what are the two inputs?', 'two images', 'an audio clip and a video', 'a single text prompt', 'an image and a question in natural language', 'D', 'VQA takes an image and a natural language question and produces an answer.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4186, 125, 'What is zero-shot image classification using text descriptions?', 'detecting faces only', 'generating audio', 'classifying an image into classes never seen during training, using text descriptions', 'translating speech', 'C', 'A zero-shot model uses text descriptions of classes to recognize categories it never saw in training.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4187, 125, 'What does a CLIP-style multimodal model align?', 'audio and video embeddings', 'image and text embeddings in a shared space', 'two text embeddings', 'graph and tree embeddings', 'B', 'CLIP learns to place images and their text descriptions close together in one embedding space.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4188, 125, 'Which application benefits most from object detection rather than whole-image classification?', 'counting vehicles in a traffic image', 'assigning one label to a whole photo', 'translating a sign', 'summarizing a news article', 'A', 'Counting requires locating each vehicle, which object detection provides.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4189, 125, 'Which feature representation is commonly used for text spam filtering?', 'raw audio samples', 'pixel brightness values', 'edge maps', 'TF-IDF word vectors', 'D', 'TF-IDF word vectors convert message text into features that classifiers can use.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4190, 125, 'What is the output of a standard speech-to-text system?', 'an image caption', 'a translation', 'a text transcript of spoken audio', 'a video file', 'C', 'Speech-to-text transcribes audio into a written text transcript.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4191, 125, 'In a multimodal model with an image encoder and a text decoder, how are image features injected into the decoder?', 'by converting them to audio', 'by projecting them into the same embedding space as the text tokens', 'by averaging them with random noise', 'by encoding them as ASCII text', 'B', 'Projecting image features into the token embedding space lets the decoder attend to them like text tokens.', 'ADVANCED', 3, 'MCQ', 1),
(4192, 125, 'For real-time pedestrian detection in a car driving at 30 fps, which design trade-off dominates?', 'accuracy versus inference latency on embedded hardware', 'the color of the dashboard', 'the number of developers', 'the size of the training videos', 'A', 'The system must balance detection accuracy with the strict latency budget of the embedded platform.', 'ADVANCED', 3, 'MCQ', 1),
(4193, 125, 'Why does OCR frequently fail on low-contrast, rotated receipts?', 'OCR never fails', 'the camera is too expensive', 'receipts are too short', 'lack of preprocessing like binarization and deskewing hurts recognition', 'D', 'Poor contrast and rotation degrade recognition without binarization and deskewing.', 'ADVANCED', 3, 'MCQ', 1),
(4194, 125, 'A deployed sentiment model performs well in testing but accuracy drops on live customer reviews. What is the most likely cause?', 'the model is too large', 'the vocabulary is too small', 'domain shift, because the training reviews differ from live reviews', 'the reports are printed in color', 'C', 'Distribution shift between training and production data is the classic cause of this failure.', 'ADVANCED', 3, 'MCQ', 1),
(4195, 125, 'A system reads chest X-rays and produces a written finding. What is this task called?', 'speech recognition', 'report generation, an image captioning task applied to medicine', 'machine translation', 'tokenization', 'B', 'Generating textual findings from images is report generation, an image captioning application.', 'ADVANCED', 3, 'MCQ', 1),
(4196, 125, 'To support 50 languages with a single translation model, which approach is most efficient?', 'a multilingual transformer with a shared vocabulary', 'a separate model per word', 'an OCR system', 'a single language bag-of-words model', 'A', 'A multilingual transformer shares parameters and a vocabulary across all languages.', 'ADVANCED', 3, 'MCQ', 1),
(4197, 125, 'Why is retrieval-augmented generation (RAG) preferred over pure generation for factual chatbot answers?', 'it ignores the documents', 'it is always deterministic', 'it trains on images', 'it retrieves relevant documents to ground answers and reduce hallucination', 'D', 'RAG grounds answers in retrieved evidence, reducing hallucinated content.', 'ADVANCED', 3, 'MCQ', 1),
(4198, 125, 'A hate-speech detector has many false positives on sarcastic posts. Which improvement helps most?', 'using more stop words', 'removing all punctuation', 'including context and discourse features to capture sarcasm', 'labeling every post as positive', 'C', 'Sarcasm is often signaled by context, so discourse features help the model avoid false positives.', 'ADVANCED', 3, 'MCQ', 1),
(4199, 125, 'What is the purpose of attention in a translation Transformer?', 'to increase the sequence length', 'to let each output word focus on the most relevant input words', 'to translate without training', 'to remove all nouns', 'B', 'Attention weights let each generated word look at the most relevant source words.', 'ADVANCED', 3, 'MCQ', 1),
(4200, 125, 'When building an image search engine from product photos and text queries, what does the system embed?', 'both images and queries into a shared vector space for similarity search', 'only the text queries', 'only the product prices', 'a single hash of the catalog', 'A', 'Embedding both modalities in one space allows image and text similarity to be compared directly.', 'ADVANCED', 3, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(4201, 251, 'Which term describes data sets that are too large or complex for traditional tools to process?', 'Small data', 'Big data', 'Metadata', 'Data lake', 'B', 'Big data refers to datasets whose size and complexity exceed the processing capability of conventional database and analysis tools.', 'BEGINNER', 1, 'MCQ', 1),
(4202, 251, 'Which characteristic of big data describes the huge volume of data generated?', 'Volume', 'Variety', 'Velocity', 'Veracity', 'A', 'Volume is the amount of data produced, one of the three original V''s of big data alongside variety and velocity.', 'BEGINNER', 1, 'MCQ', 1),
(4203, 251, 'Which characteristic of big data refers to the different forms of data, such as text, images and video?', 'Velocity', 'Variety', 'Volume', 'Value', 'B', 'Variety captures the many formats big data arrives in, from structured records to unstructured multimedia.', 'BEGINNER', 1, 'MCQ', 1),
(4204, 251, 'Which characteristic of big data refers to the speed at which data is generated and processed?', 'Veracity', 'Volume', 'Velocity', 'Value', 'C', 'Velocity describes how quickly data streams in and must be analysed to remain useful.', 'BEGINNER', 1, 'MCQ', 1),
(4205, 251, 'Which of the following is a classic example of a source of big data?', 'Social media feeds', 'A single Excel sheet', 'A text file with 10 rows', 'A pocket calculator', 'A', 'Social media platforms generate enormous, high-speed streams of varied data, a hallmark of big data.', 'BEGINNER', 1, 'MCQ', 1),
(4206, 251, 'What does the term ''structured data'' refer to?', 'Data organised in a fixed schema such as tables with rows and columns', 'Random text documents', 'Raw video footage', 'Sensor noise', 'A', 'Structured data fits neatly into relational tables with predefined columns, types and relationships.', 'BEGINNER', 1, 'MCQ', 1),
(4207, 251, 'What is the approximate scale implied by the unit ''terabyte''?', '10^3 bytes', '10^6 bytes', '10^9 bytes', '10^12 bytes', 'D', 'A terabyte is about 10^12 bytes, while gigabytes, megabytes and kilobytes are progressively smaller units.', 'BEGINNER', 1, 'MCQ', 1),
(4208, 251, 'Which unit of data is the largest among the following?', 'Kilobyte', 'Gigabyte', 'Petabyte', 'Megabyte', 'C', 'A petabyte equals 1024 terabytes, making it the largest unit listed.', 'BEGINNER', 1, 'MCQ', 1),
(4209, 251, 'Which term describes raw data that has not yet been processed or given meaning?', 'Information', 'Knowledge', 'Raw data', 'Wisdom', 'C', 'Raw data consists of unprocessed facts and numbers that only become information once interpreted.', 'BEGINNER', 1, 'MCQ', 1),
(4210, 251, 'In the data-information-knowledge-wisdom hierarchy, which comes immediately before ''knowledge''?', 'Data', 'Wisdom', 'Information', 'Signals', 'C', 'The hierarchy progresses data to information to knowledge to wisdom, so information precedes knowledge.', 'BEGINNER', 1, 'MCQ', 1),
(4211, 251, 'An e-commerce firm must capture customer clicks within seconds to adjust recommendations in real time. Which V is under most pressure?', 'Volume', 'Velocity', 'Variety', 'Veracity', 'B', 'Needing to react within seconds makes processing speed, or velocity, the critical challenge.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4212, 251, 'A bank combines transaction logs, customer emails and call recordings for fraud detection. Which V is the main concern?', 'Velocity', 'Variety', 'Value', 'Volume', 'B', 'Mixing structured logs with unstructured emails and audio means handling a wide variety of data formats.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4213, 251, 'A hospital finds its patient records contain many missing and inconsistent fields. Which V is problematic?', 'Veracity', 'Velocity', 'Value', 'Volume', 'A', 'Veracity concerns the quality, accuracy and trustworthiness of data, which is weakened by missing and inconsistent entries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4214, 251, 'Which technology class is most commonly used to store massive volumes of semi-structured data like JSON documents?', 'Relational only', 'Key-value and document NoSQL stores', 'Single flat files', 'Punch cards', 'B', 'NoSQL stores such as document databases handle semi-structured JSON at scale far better than rigid relational schemas.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4215, 251, 'Which technique partitions data across many machines so each node processes only a portion?', 'Horizontal partitioning or sharding', 'Vertical merging', 'Full-table scanning on one server', 'Data deletion', 'A', 'Sharding splits rows across machines, distributing storage and computation across the cluster.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4216, 251, 'Why is scaling out (adding more commodity servers) often preferred over scaling up in big data?', 'Commodity hardware is cheaper and clusters can grow horizontally', 'One giant server is always cheaper', 'Scaling up never fails', 'Clusters cannot tolerate faults', 'A', 'Horizontal scaling uses inexpensive commodity nodes and can grow incrementally, unlike scaling up a single expensive machine.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4217, 251, 'Which of the following is a characteristic of ''unstructured'' data?', 'It has a fixed schema', 'It lacks a predefined data model', 'It always fits in tables', 'It is always numerical', 'B', 'Unstructured data such as free text or audio has no predefined model, making it harder to query directly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4218, 251, 'Which storage concept stores raw data in its native format until it is needed for analysis?', 'Data lake', 'OLTP database', 'Data warehouse', 'Cache', 'A', 'A data lake keeps raw, unprocessed data in its original form, deferring transformation until analysis time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4219, 251, 'Which statement best describes a data warehouse compared with a data lake?', 'It stores processed, structured data optimised for reporting', 'It stores raw data in any format', 'It cannot query data', 'It only handles streaming data', 'A', 'A data warehouse stores cleaned, structured, subject-oriented data tuned for business intelligence and reporting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4220, 251, 'A retail chain wants to store decades of purchase history and run daily summary reports. Which setup fits best?', 'A data warehouse for structured summaries', 'A single register tape', 'A printed ledger book', 'A set of paper receipts', 'A', 'A data warehouse consolidates historical structured data for fast analytical queries such as daily reports.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4221, 251, 'A firm finds its model quality degrades because two separate departments record the same customer differently. Which big data practice addresses this?', 'Data governance and master data management', 'Buying more storage', 'Deleting old records', 'Ignoring the mismatch', 'A', 'Data governance and master data management standardise entities and definitions across silos to improve consistency.', 'ADVANCED', 3, 'MCQ', 1),
(4222, 251, 'Which big data architecture ingests data into a raw zone, then transforms it into curated zones for analysts?', 'Multi-hop or medallion (bronze/silver/gold) architecture', 'Single flat-file repository', 'A standalone spreadsheet', 'A paper filing cabinet', 'A', 'Medallion architectures progressively refine data through bronze (raw), silver (cleaned) and gold (curated) layers.', 'ADVANCED', 3, 'MCQ', 1),
(4223, 251, 'Under the CAP theorem, which trade-off most affects a globally distributed customer profile service?', 'Guaranteeing strong consistency across regions versus always-available writes', 'Guaranteeing zero latency for reads', 'Storing data on a single node', 'Removing encryption', 'A', 'Distributed systems must choose between consistency and availability during partitions, which directly shapes cross-region designs.', 'ADVANCED', 3, 'MCQ', 1),
(4224, 251, 'Which big data challenge is most directly addressed by data provenance and lineage tracking?', 'Trusting where data came from and how it was transformed', 'Reducing storage cost', 'Speeding up sort operations', 'Minimising network bandwidth', 'A', 'Lineage records the origin and transformation history of data, building veracity and enabling audits.', 'ADVANCED', 3, 'MCQ', 1),
(4225, 251, 'A streaming recommender uses clicks from the last hour. This is an example of which big data processing mode?', 'Near-real-time stream processing', 'Batch processing run annually', 'Manual spreadsheet updates', 'Mainframe tape backup', 'A', 'Analysing a short rolling window of live events is characteristic of stream processing with low latency.', 'ADVANCED', 3, 'MCQ', 1),
(4226, 251, 'Which metric best indicates whether a big data pipeline is cost-effective per unit of useful output?', 'Useful data processed per unit cost', 'Raw bytes stored regardless of use', 'Number of servers purchased', 'Uptime of a single node', 'A', 'Value is measured by the useful insight extracted relative to cost, not by hoarding raw bytes.', 'ADVANCED', 3, 'MCQ', 1),
(4227, 251, 'Why is schema-on-read popular for exploratory analytics over raw big data?', 'It applies the schema only when reading, allowing flexible interpretation of messy data', 'It forces all data into one fixed table at write time', 'It eliminates the need for storage', 'It only works with relational SQL', 'A', 'Schema-on-read defers structure to query time, letting analysts adapt to varied and messy data without rigid ingestion.', 'ADVANCED', 3, 'MCQ', 1),
(4228, 251, 'Which practice most effectively reduces the risk of regulatory fines for storing personal big data?', 'Implementing retention policies and purpose-based data minimisation', 'Storing everything forever ''just in case''', 'Anonymising then ignoring access controls', 'Backing up all data to removable drives', 'A', 'Retention and minimisation align storage with legal purpose, shrinking exposure to regulatory penalties.', 'ADVANCED', 3, 'MCQ', 1),
(4229, 251, 'An IoT fleet produces telemetry that varies wildly in frequency. Which design choice best handles this variability?', 'Elastic auto-scaling of ingest and compute resources', 'A fixed cluster sized for peak load at all times', 'Rejecting data above a fixed rate', 'Relying on manual overnight transfers', 'A', 'Elastic scaling lets infrastructure grow and shrink with the data rate, avoiding both waste and overload.', 'ADVANCED', 3, 'MCQ', 1),
(4230, 251, 'Which combination of measures best guards a big data platform against both accidental loss and malicious tampering?', 'Replication plus encryption at rest and immutable audit logs', 'A single backup tape kept on site', 'Open network shares for everyone', 'Relying only on antivirus software', 'A', 'Replication protects availability, encryption protects confidentiality, and immutable logs detect tampering.', 'ADVANCED', 3, 'MCQ', 1),
(4231, 252, 'Which component of Hadoop stores data across a distributed cluster?', 'HDFS', 'Hive', 'Pig', 'Flume', 'A', 'The Hadoop Distributed File System (HDFS) provides fault-tolerant storage spread over many machines.', 'BEGINNER', 1, 'MCQ', 1),
(4232, 252, 'Which Hadoop component schedules and monitors jobs across the cluster?', 'HDFS', 'YARN', 'HBase', 'ZooKeeper', 'B', 'YARN (Yet Another Resource Negotiator) manages resources and schedules application tasks on the cluster.', 'BEGINNER', 1, 'MCQ', 1),
(4233, 252, 'What is the default block size of HDFS in most modern distributions?', '64 MB', '128 MB', '1 KB', '4 KB', 'B', 'Modern Hadoop defaults to 128 MB blocks, up from the older 64 MB default, to reduce metadata overhead.', 'BEGINNER', 1, 'MCQ', 1),
(4234, 252, 'How does HDFS provide fault tolerance?', 'By replicating each block across multiple DataNodes', 'By storing everything on one disk', 'By keeping no backups', 'By using only RAID 0', 'A', 'HDFS copies each block to multiple DataNodes, typically three, so a failed node does not lose data.', 'BEGINNER', 1, 'MCQ', 1),
(4235, 252, 'Which HDFS node stores the actual data blocks?', 'NameNode', 'DataNode', 'Secondary NameNode', 'JobTracker', 'B', 'DataNodes are the worker machines that physically store and serve data blocks.', 'BEGINNER', 1, 'MCQ', 1),
(4236, 252, 'Which HDFS node keeps the file system metadata such as the block-to-file mapping?', 'NameNode', 'DataNode', 'TaskTracker', 'Gateway', 'A', 'The NameNode holds the namespace and metadata mapping files to their blocks.', 'BEGINNER', 1, 'MCQ', 1),
(4237, 252, 'Which command copies a file from the local machine into HDFS?', 'hdfs dfs -put', 'hdfs dfs -get', 'rm', 'cp -r /home', 'A', 'The -put command uploads a local file or directory into the HDFS filesystem.', 'BEGINNER', 1, 'MCQ', 1),
(4238, 252, 'Which command reads a file from HDFS to the local machine?', 'hdfs dfs -put', 'hdfs dfs -get', 'hdfs dfs -mkdir', 'touch', 'B', 'The -get command copies an HDFS file or directory down to the local filesystem.', 'BEGINNER', 1, 'MCQ', 1),
(4239, 252, 'Which HDFS command creates a new directory?', 'hdfs dfs -mkdir', 'hdfs dfs -rm', 'hdfs dfs -cat', 'ls', 'A', 'The -mkdir command creates a directory in HDFS, similar to mkdir in a local filesystem.', 'BEGINNER', 1, 'MCQ', 1),
(4240, 252, 'Which component of the Hadoop ecosystem provides a SQL-like interface over data in HDFS?', 'Hive', 'Flume', 'Sqoop', 'Oozie', 'A', 'Apache Hive translates SQL-like HiveQL queries into MapReduce or Spark jobs over HDFS data.', 'BEGINNER', 1, 'MCQ', 1),
(4241, 252, 'A cluster has 3 DataNodes and replication factor 3. One node fails. What happens to the blocks it stored?', 'Replicas remain on other nodes and new copies are re-replicated', 'All data is lost permanently', 'The NameNode shuts down', 'The block size doubles', 'A', 'Because each block had replicas elsewhere, HDFS re-replicates to restore the factor of three automatically.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4242, 252, 'Why does HDFS favour large blocks instead of small ones?', 'Large blocks reduce NameNode metadata overhead and disk seek time', 'Small blocks use less RAM in workers', 'Large blocks ignore replication', 'Small blocks cannot be read', 'A', 'Fewer, larger blocks mean less metadata to track in the NameNode and cheaper sequential reads with fewer seeks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4243, 252, 'Which HDFS design property makes a NameNode a single point of failure in classic Hadoop?', 'All metadata lives on one active NameNode', 'Data is stored on the NameNode', 'There is no metadata', 'Clients talk only to DataNodes', 'A', 'In classic HDFS the single NameNode holds all metadata, so its loss can block the entire cluster.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4244, 252, 'Which service is commonly used to allow multiple active or stand-by NameNodes with automatic failover?', 'ZooKeeper', 'Hive', 'Pig', 'Flume', 'A', 'ZooKeeper coordinates leader election and failover so a stand-by NameNode can take over quickly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4245, 252, 'A file of 300 MB is written to HDFS with 128 MB blocks. Roughly how many blocks does it occupy?', '3', '2', '1', '300', 'A', '300 MB divided by 128 MB gives about 2.34 blocks, which rounds up to 3 physical blocks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4246, 252, 'What is the role of the HDFS Secondary NameNode?', 'It periodically merges the edit log with the fsimage to checkpoint metadata', 'It stores data blocks as a backup', 'It runs user MapReduce jobs', 'It compresses all stored files', 'A', 'The Secondary NameNode checkpoints by applying edits to the fsimage, helping the primary recover faster.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4247, 252, 'Which statement about HDFS file write semantics is correct?', 'Files are write-once and append is limited, favouring batch processing', 'Files can be randomly updated in place', 'Files auto-compress on every write', 'Writes bypass replication', 'A', 'HDFS was designed for a write-once, read-many model suited to batch analytics rather than frequent random updates.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4248, 252, 'Which tool transfers structured data between a relational database and HDFS?', 'Sqoop', 'Flume', 'Spark Streaming', 'Oozie', 'A', 'Apache Sqoop imports and exports data between RDBMS systems and HDFS/Hive.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4249, 252, 'Which tool efficiently collects and moves streaming log data into HDFS?', 'Flume', 'Sqoop', 'Mahout', 'Pig', 'A', 'Apache Flume is designed to aggregate streaming logs from many sources into HDFS reliably.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4250, 252, 'You must schedule a nightly workflow that ingests data, runs a Hive query, then emails results. Which tool orchestrates it?', 'Oozie', 'Pig', 'Tez', 'Ambari', 'A', 'Apache Oozie coordinates and schedules Hadoop jobs as directed acyclic graph workflows.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4251, 252, 'A pipeline of many small files causes the NameNode to run out of memory. Which strategy best solves this?', 'Consolidate small files into larger ones with tools like Hadoop Archives or sequence files', 'Buy more DataNode disks', 'Disable the NameNode', 'Reduce replication to zero', 'A', 'Every file and block consumes NameNode memory, so merging small files into archives drastically reduces metadata.', 'ADVANCED', 3, 'MCQ', 1),
(4252, 252, 'An engineer wants rack-aware replication to survive a full rack outage. Which approach is correct?', 'Configure a rack topology script so replicas spread across multiple racks', 'Put all replicas on the same rack', 'Use replication factor 1', 'Store only on the NameNode', 'A', 'Rack awareness places replicas on different racks, so losing one rack does not lose all copies of a block.', 'ADVANCED', 3, 'MCQ', 1),
(4253, 252, 'Why does the NameNode not stream data blocks directly to clients?', 'The client reads from DataNodes after the NameNode supplies block locations, avoiding a bottleneck', 'The NameNode has no network card', 'DataNodes refuse to serve clients', 'Blocks are stored only in memory', 'A', 'NameNode only answers metadata requests; data flows directly between clients and DataNodes to scale bandwidth.', 'ADVANCED', 3, 'MCQ', 1),
(4254, 252, 'Which condition would likely leave an HDFS cluster unable to start after a hard crash?', 'A corrupt or inconsistent fsimage/edit log with no checkpoint recovery', 'A DataNode running out of disk', 'A slow network switch', 'Too many client sessions', 'A', 'If metadata on the NameNode is corrupt and there is no valid checkpoint, the namespace cannot be rebuilt reliably.', 'ADVANCED', 3, 'MCQ', 1),
(4255, 252, 'Which design consideration best limits the blast radius of metadata corruption in HDFS?', 'Frequent checkpointing plus mirrored edits on shared or journaled storage', 'Never restarting the NameNode', 'Storing fsimage on the same disk as data blocks', 'Using one huge edit log', 'A', 'Regular checkpoints and journaling protect the metadata state so recovery is possible after corruption.', 'ADVANCED', 3, 'MCQ', 1),
(4256, 252, 'When many clients write the same 300 MB file, which node coordinates the block pipeline?', 'The client writes to the first DataNode, which forwards to replicas in a pipeline', 'The NameNode copies the file to every node', 'Each DataNode writes its own copy independently', 'YARN streams the file directly', 'A', 'The client pushes data to the first DataNode, which relays it to subsequent replicas, forming a pipeline.', 'ADVANCED', 3, 'MCQ', 1),
(4257, 252, 'Which approach most improves read throughput for a job that needs the entire content of a 2 TB file?', 'Scheduling tasks on nodes that hold the data blocks to exploit data locality', 'Copying the file to the client machine first', 'Reading through a single gateway node', 'Storing the file as one giant block', 'A', 'Data locality moves computation to where blocks reside, avoiding expensive network transfers over the full file.', 'ADVANCED', 3, 'MCQ', 1),
(4258, 252, 'Which HDFS command safely removes a file by moving it to a trash directory rather than destroying it instantly?', 'hdfs dfs -rm with trash enabled, which stages deletion in a trash folder', 'hdfs dfs -rm -skipTrash', 'rm -rf /', 'hdfs dfs -put', 'A', 'With trash enabled, deletions are staged so files can be recovered before permanent purging.', 'ADVANCED', 3, 'MCQ', 1),
(4259, 252, 'What is the purpose of HDFS erasure coding compared with pure replication?', 'It stores parity data to recover from node loss while using much less storage overhead', 'It removes the need for DataNodes', 'It speeds up metadata lookups', 'It encrypts every block twice', 'A', 'Erasure coding trades some CPU overhead for drastically lower storage overhead than replication factor 3.', 'ADVANCED', 3, 'MCQ', 1),
(4260, 252, 'Which activity would produce the most severe write-head-of-line bottleneck in a NameNode?', 'A storm of tiny metadata-only operations such as creating thousands of small files', 'Streaming one very large file sequentially', 'A single large block deletion', 'Reading one file repeatedly', 'A', 'Every small-file creation is a NameNode operation, so bursts of them saturate the single NameNode RPC handler.', 'ADVANCED', 3, 'MCQ', 1),
(4261, 253, 'Which processing model splits a job into a map phase followed by a reduce phase?', 'MapReduce', 'Linear regression', 'Binary search', 'Direct SQL injection', 'A', 'MapReduce is the two-stage programming model popularised by Hadoop for distributed batch processing.', 'BEGINNER', 1, 'MCQ', 1),
(4262, 253, 'In MapReduce, which phase transforms each input element into key-value pairs?', 'Reduce', 'Map', 'Sort only', 'Shuffle only', 'B', 'The map function processes each record and emits intermediate key-value pairs.', 'BEGINNER', 1, 'MCQ', 1),
(4263, 253, 'In MapReduce, which phase groups values by key and produces the final output?', 'Map', 'Input split', 'Reduce', 'Copy phase', 'C', 'The reduce function receives a key with its grouped values and emits aggregated results.', 'BEGINNER', 1, 'MCQ', 1),
(4264, 253, 'What is the default unit of parallelism in Hadoop MapReduce?', 'The input split', 'The number of users', 'The disk size', 'The clock speed', 'A', 'Each input split is processed by one map task, so splits define map parallelism.', 'BEGINNER', 1, 'MCQ', 1),
(4265, 253, 'Which component of Apache Spark keeps frequently used data in memory for fast reuse?', 'RDD cache or persistence', 'Only the disk', 'The network card', 'A print queue', 'A', 'Spark''s RDD persistence keeps partitions in memory, enabling iterative algorithms to run far faster.', 'BEGINNER', 1, 'MCQ', 1),
(4266, 253, 'What does RDD stand for in Apache Spark?', 'Resilient Distributed Dataset', 'Redundant Disk Drive', 'Remote Data Directory', 'Reactive Data Database', 'A', 'RDD stands for Resilient Distributed Dataset, the fundamental abstraction of fault-tolerant data in Spark.', 'BEGINNER', 1, 'MCQ', 1),
(4267, 253, 'Which term describes the stages Spark uses for fault tolerance by rebuilding lost partitions from lineage?', 'RDD lineage or DAG of transformations', 'Static partitioning', 'Manual checkpointing by users only', 'Replication of the driver', 'A', 'Spark records the lineage of transformations so it can recompute lost partitions rather than replicate everything.', 'BEGINNER', 1, 'MCQ', 1),
(4268, 253, 'Which of the following is a transformation (lazy) operation in Spark?', 'map', 'collect', 'count', 'saveAsTextFile', 'A', 'map returns a new RDD and is lazy; collect, count and save are eager actions.', 'BEGINNER', 1, 'MCQ', 1),
(4269, 253, 'Which of the following is an action (eager) operation in Spark?', 'filter', 'flatMap', 'count', 'distinct', 'C', 'count is an action that triggers computation and returns a value to the driver.', 'BEGINNER', 1, 'MCQ', 1),
(4270, 253, 'Which directory structure describes the famous word count MapReduce example''s intermediate output?', 'Word and count pairs', 'Pixels and colors', 'IP addresses only', 'Sums of every key', 'A', 'The canonical example maps each word to 1 and reduces by summing to word-count pairs.', 'BEGINNER', 1, 'MCQ', 1),
(4271, 253, 'In MapReduce, if a mapper produces key K with values [3,5,2], what does a sum reducer output for K?', '10', '3', '30', '2', 'A', 'The reducer sums the grouped values 3 + 5 + 2, emitting the key with total 10.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4272, 253, 'Which phase in MapReduce moves intermediate results from mappers to reducers?', 'Shuffle and sort', 'Serialization', 'Map output only', 'YARN scheduling', 'A', 'During shuffle and sort, Hadoop partitions and sorts intermediate key-value pairs and transfers them to reducers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4273, 253, 'A mapper''s output key should be partitioned to reducers using which mechanism to control grouping?', 'A custom Partitioner based on the key', 'The file creation time', 'The key length only', 'Random disk space', 'A', 'Custom partitioners decide which reducer receives each key, controlling data distribution and grouping.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4274, 253, 'In Spark, which operation groups all elements by a given key and is commonly used before aggregation?', 'groupByKey', 'parallelize', 'union', 'saveAsTextFile', 'A', 'groupByKey collects all values for each key into one iterable, which can then be aggregated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4275, 253, 'Which Spark function applies a provided function to each element and flattens the emitted results?', 'flatMap', 'count', 'take', 'reduce', 'A', 'flatMap produces zero or more output elements per input, unlike map''s one-to-one mapping.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4276, 253, 'Which of the following correctly computes the number of records in an RDD without moving all data to the driver?', 'rdd.count()', 'rdd.collect()', 'rdd.take(10)', 'rdd.foreach', 'A', 'count aggregates partition sizes on the workers and returns a single number, while collect would move everything to the driver.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4277, 253, 'Which pair of Spark concepts distinguishes the plan definition from actual execution?', 'Lazy transformations build a DAG; actions trigger execution', 'Actions build the plan; transformations run immediately', 'Both run eagerly on every call', 'Neither affects execution', 'A', 'Spark defers execution: transformations only build a lineage DAG until an action forces computation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4278, 253, 'Which Spark abstraction is an immutable, typed collection partitioned across the cluster?', 'RDD', 'YARN container', 'HDFS block pointer', 'ZooKeeper node', 'A', 'An RDD is an immutable distributed collection of records partitioned across the cluster.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4279, 253, 'Which strategy prevents a single slow map output from delaying a reducer in MapReduce?', 'Speculative execution of straggler tasks', 'Deleting slow outputs', 'Running everything on one node', 'Disabling YARN', 'A', 'Speculative execution runs duplicate copies of slow tasks and uses the first to finish, smoothing stragglers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4280, 253, 'When a reducer finishes writing its output file, where does it place the final result?', 'In HDFS so it is shared and durable', 'On the local disk of the client''s laptop', 'Only in RAM', 'In the NameNode memory', 'A', 'Reducer outputs are written to HDFS, making results durable and accessible cluster-wide.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4281, 253, 'Why does Spark generally outperform classic MapReduce for iterative machine learning jobs?', 'RDDs cached in memory avoid reloading data from disk on each iteration', 'Spark skips the shuffle entirely', 'Spark has no fault tolerance', 'RDDs store data only on the client', 'A', 'Caching keeps intermediate data in memory across iterations, eliminating repeated disk I/O that MapReduce performs.', 'ADVANCED', 3, 'MCQ', 1),
(4282, 253, 'A skewed key concentrates millions of values on one reducer while others idle. Which technique best balances it?', 'Salting or range-partitioning the key into finer shards before reducing', 'Increasing only the map count', 'Using replication factor 3 on HDFS', 'Turning off speculative execution', 'A', 'Key salting splits hot keys into sub-keys so their load spreads across many reducers, then a second pass merges results.', 'ADVANCED', 3, 'MCQ', 1),
(4283, 253, 'Which Spark setting or design change most directly reduces shuffle write overhead for wide dependencies?', 'Choosing efficient partitioning and reducing the number of shuffle partitions that generate tiny files', 'Using only narrow dependencies', 'Caching the shuffle output on the driver', 'Disabling serialization', 'A', 'Right-sizing shuffle partitions and using good partitioners cut both network I/O and the number of small output files.', 'ADVANCED', 3, 'MCQ', 1),
(4284, 253, 'Which component of Spark''s cluster mode is responsible for converting a DAG into physical stages of tasks?', 'The DAGScheduler in the driver', 'The HDFS DataNode', 'The ZooKeeper quorum', 'The Hive metastore', 'A', 'The DAGScheduler builds stages from the lineage graph and submits task sets to the cluster manager.', 'ADVANCED', 3, 'MCQ', 1),
(4285, 253, 'Why should a Spark broadcast be preferred over a shuffle join for joining a small reference table with a huge RDD?', 'Broadcasting ships the small table to each executor, avoiding an expensive full shuffle', 'Broadcast joins always read from the NameNode', 'Shuffle joins never finish', 'Broadcast joins ignore partitioning', 'A', 'Broadcast hash join sends the small dataset once to every executor, eliminating the shuffle of large data.', 'ADVANCED', 3, 'MCQ', 1),
(4286, 253, 'A reducer must sort billions of records by key for the final output. Which design consideration most affects its cost?', 'Whether sorting is done in the shuffle phase or requires an explicit global sort', 'The colour of the cluster logo', 'The number of mappers', 'The HDFS default block size', 'A', 'Shuffle sort orders data within partitions, but a fully sorted global output needs an additional total-order sort such as a range partitioner.', 'ADVANCED', 3, 'MCQ', 1),
(4287, 253, 'Which failure scenario does Spark''s lineage recomputation handle automatically without replication?', 'A lost worker node whose partitions can be rebuilt from upstream RDDs', 'A corrupt driver program', 'A misconfigured firewall', 'A dead DNS server', 'A', 'Because each RDD knows its lineage, Spark recomputes lost partitions from parent data, providing fault tolerance.', 'ADVANCED', 3, 'MCQ', 1),
(4288, 253, 'Why is data locality especially important for Spark workloads that read large HDFS files?', 'Computing near the data avoids moving terabytes across the network', 'It reduces the need for shuffle sorting', 'It lets Spark skip serialization', 'It increases block replication', 'A', 'Locality keeps computation on nodes holding the blocks, minimising the network traffic for large reads.', 'ADVANCED', 3, 'MCQ', 1),
(4289, 253, 'An interactive job reuses the same filtered dataset ten times. Which Spark call most improves its performance?', 'Calling persist or cache on the filtered RDD after filtering', 'Calling count once then discarding it', 'Using a larger HDFS block size', 'Increasing reducer count', 'A', 'Persistence avoids recomputing the filter transformation on every subsequent action, saving significant time.', 'ADVANCED', 3, 'MCQ', 1),
(4290, 253, 'Which technique lets a Spark job process out-of-core data sets that exceed the memory of the whole cluster?', 'Spilling intermediate data to disk and using lazy evaluation with partitioning', 'Loading all data into the driver', 'Disabling serialization', 'Running every task on one executor', 'A', 'Spark spills overflow data to disk and processes data in streaming partitions, allowing it to exceed aggregate RAM.', 'ADVANCED', 3, 'MCQ', 1),
(4291, 254, 'Which type of NoSQL database stores data as key-value pairs?', 'Key-value store', 'Graph database', 'Document store', 'Column family', 'A', 'Key-value stores like Redis and DynamoDB map each key to a single value with no fixed schema.', 'BEGINNER', 1, 'MCQ', 1),
(4292, 254, 'Which NoSQL model is most suitable for storing JSON-like documents?', 'Document store', 'Pure relational table', 'Flat CSV', 'Hash table only', 'A', 'Document databases such as MongoDB store semi-structured documents, commonly in JSON or BSON.', 'BEGINNER', 1, 'MCQ', 1),
(4293, 254, 'Which NoSQL database models relationships as nodes and edges?', 'Graph database', 'Key-value store', 'Document store', 'Search index', 'A', 'Graph databases such as Neo4j represent entities as nodes and connections as edges for relationship-heavy queries.', 'BEGINNER', 1, 'MCQ', 1),
(4294, 254, 'Which NoSQL storage organises data into column families, ideal for wide rows?', 'Column-family store', 'Object store', 'Queue', 'Spreadsheet', 'A', 'Column-family databases such as HBase and Cassandra group related columns together for wide tables.', 'BEGINNER', 1, 'MCQ', 1),
(4295, 254, 'Which of the following is a widely used key-value in-memory database?', 'Redis', 'PostgreSQL', 'Neo4j', 'HDFS', 'A', 'Redis is a popular in-memory key-value store known for low-latency caching.', 'BEGINNER', 1, 'MCQ', 1),
(4296, 254, 'Which term describes data processing that occurs on records as they arrive, before storage?', 'Stream processing', 'Batch processing', 'Snapshot backup', 'Offline archiving', 'A', 'Stream processing handles events continuously and in near-real-time as they flow in.', 'BEGINNER', 1, 'MCQ', 1),
(4297, 254, 'Which of the following is a stream processing engine?', 'Apache Kafka Streams', 'Pig', 'Sqoop', 'Oozie', 'A', 'Kafka Streams and similar engines consume and process event streams continuously.', 'BEGINNER', 1, 'MCQ', 1),
(4298, 254, 'Which tool is most associated with buffering and delivering streams of events between producers and consumers?', 'Apache Kafka', 'PostgreSQL', 'Neo4j', 'WordPress', 'A', 'Apache Kafka is a distributed event streaming platform acting as a durable, scalable message bus.', 'BEGINNER', 1, 'MCQ', 1),
(4299, 254, 'What does the term ''event time'' mean in stream processing?', 'The moment the event actually occurred', 'The time the analyst reads it', 'The batch job start time', 'The server boot time', 'A', 'Event time is the timestamp attached when the event happened, distinct from when it was processed.', 'BEGINNER', 1, 'MCQ', 1),
(4300, 254, 'Which of the following is an example of a semi-structured data format common in big data pipelines?', 'JSON', 'Fixed-width text', 'A JPEG image', 'A compiled binary', 'A', 'JSON nests key-value pairs with flexible structure, making it a typical semi-structured format.', 'BEGINNER', 1, 'MCQ', 1),
(4301, 254, 'A web shop must keep every click event in order per user and replay them later. Which Kafka concept stores the ordered sequence?', 'A topic partition with an offset per record', 'A single global file', 'The broker''s RAM only', 'The client''s browser cache', 'A', 'Kafka topics are split into partitions that keep records ordered and assign each an offset for replay.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4302, 254, 'Which NoSQL guarantee typically replaces SQL transactions in a distributed key-value store?', 'Eventual consistency with tunable consistency levels', 'Full ACID on every node', 'No consistency at all', 'Serial execution of all reads', 'A', 'Distributed stores like Cassandra offer eventual consistency and tunable consistency rather than global ACID.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4303, 254, 'Cassandra uses a design where replicas are placed based on a hash of the partition key. What is this placement method called?', 'Consistent hashing', 'Round-robin SQL', 'Static replication', 'Random assignment', 'A', 'Consistent hashing assigns keys to nodes around a hash ring, aiding distribution and replication.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4304, 254, 'Which action in stream processing computes a running count that needs to be carried across many events?', 'Stateful aggregation with a persistent state store', 'A stateless filter', 'A one-time batch dump', 'Reading the log files manually', 'A', 'A running count requires state that survives between events, maintained in a state store.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4305, 254, 'Which of the following describes a window in stream processing?', 'A time or count bound that groups events for aggregation', 'A pop-up on the analyst''s screen', 'A size of the database index', 'The screen of the dashboard', 'A', 'Windowing groups stream events into finite buckets, such as tumbling or sliding time windows, for aggregation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4306, 254, 'A document database stores orders as JSON. Which query style does it naturally support over nested fields?', 'Field-level queries and indexes on embedded documents', 'Only full-table scans', 'Stored procedures in COBOL', 'Foreign key joins across servers', 'A', 'Document stores index and query nested JSON fields directly, unlike relational joins.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4307, 254, 'Why might a team choose MongoDB over a relational database for rapidly changing product schemas?', 'Its schema-less documents adapt to evolving fields without migrations', 'It enforces stricter schemas than SQL', 'It never needs indexes', 'It cannot store nested data', 'A', 'Document flexibility lets fields vary per record, reducing migration overhead when requirements evolve.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4308, 254, 'Which scenario best suits a graph database over a relational one?', 'Finding multi-hop relationships such as friends-of-friends or supply chains', 'Storing millions of identical sales rows', 'Enforcing foreign key counts', 'Running pivot table reports', 'A', 'Graph databases excel at traversing variable-length relationships, which relational joins handle awkwardly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4309, 254, 'Which strategy does Kafka use to guarantee that a message is not lost if a broker fails?', 'Replicating partitions across brokers with an in-sync replica set', 'Writing to the client''s disk only', 'Storing messages in a single file', 'Disabling acknowledgements', 'A', 'Partition replication with a configurable in-sync replica set ensures durability despite broker loss.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4310, 254, 'Which process transforms a stream of raw events into a stream of enriched records in Kafka Streams?', 'Mapping each record through a user-defined function that adds context', 'Deleting raw records', 'Storing events only in HDFS', 'Converting events to PDF', 'A', 'A map or transform processor enriches each record with joined or derived context before producing the output stream.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4311, 254, 'Which set of Kafka settings reduces data loss to near zero during a broker crash?', 'Replication factor 3 with acks=all and min.insync.replicas>1', 'Replication factor 1 with acks=0', 'No replication and no acks', 'Storing offsets only in RAM', 'A', 'High replication with full acknowledgements and a minimum in-sync replica count trades latency for durability.', 'ADVANCED', 3, 'MCQ', 1),
(4312, 254, 'Why do NoSQL stores typically favour horizontal scaling over vertical scaling?', 'They can partition data across many commodity nodes to grow capacity linearly', 'One massive server is cheaper per byte', 'They cannot replicate data', 'They require a single master', 'A', 'Distributed partitioning lets NoSQL systems scale out by adding nodes instead of buying ever-larger servers.', 'ADVANCED', 3, 'MCQ', 1),
(4313, 254, 'A Cassandra cluster reads a row at consistency level ONE. Which trade-off does the operator accept?', 'The read may return a stale replica if the coordinator reaches a lagging node', 'The read is blocked until all nodes agree', 'The read is always linearizable', 'The read fails completely', 'A', 'Consistency ONE returns the first replica answer, trading freshness for availability and speed.', 'ADVANCED', 3, 'MCQ', 1),
(4314, 254, 'Which design choice best solves the problem of a hot partition that receives most of the writes?', 'Choosing a high-cardinality partition key that spreads writes evenly', 'Using a single wide partition key for everything', 'Disabling replication', 'Writing all data to one node', 'A', 'A well-chosen, high-cardinality partition key distributes load across nodes instead of concentrating it.', 'ADVANCED', 3, 'MCQ', 1),
(4315, 254, 'In exactly-once stream processing, what does the processing engine guarantee?', 'Each event is applied exactly once even if retries happen', 'Each event is applied at least once', 'Events are applied randomly', 'Retries always duplicate effects', 'A', 'Exactly-once semantics use transactions and idempotent state so retried records do not double-apply.', 'ADVANCED', 3, 'MCQ', 1),
(4316, 254, 'Which architecture pattern decouples event producers from consumers so either can scale independently?', 'Event-driven architecture with a durable message broker between them', 'Tightly coupled stored procedures', 'Direct function calls across services', 'Shared mutable global state', 'A', 'A durable broker buffers events, letting producers and consumers scale and fail independently.', 'ADVANCED', 3, 'MCQ', 1),
(4317, 254, 'Which query pattern makes MongoDB perform a collection scan instead of using an index?', 'A predicate over a field that has no matching index', 'An indexed equality match', 'A range query on an indexed numeric field', 'An equality on the _id field', 'A', 'When no index covers the query predicate, MongoDB falls back to scanning the collection, which is slow at scale.', 'ADVANCED', 3, 'MCQ', 1),
(4318, 254, 'Why is a two-phase commit across many distributed NoSQL nodes avoided in practice?', 'It introduces a coordinator single point of failure and high blocking latency', 'It is faster than eventual consistency', 'It needs no coordination', 'It always succeeds', 'A', 'Distributed transactions cost coordination, blocking and failure risk, so most systems prefer lighter consistency.', 'ADVANCED', 3, 'MCQ', 1),
(4319, 254, 'Which approach preserves event order while processing millions of users'' streams in parallel?', 'Keying events by user id so all of one user''s events land in the same partition', 'Shuffling events randomly across partitions', 'Sorting by timestamp globally', 'Processing in one single partition', 'A', 'Partitioning by the user key keeps each user''s events ordered within one partition while allowing parallelism.', 'ADVANCED', 3, 'MCQ', 1),
(4320, 254, 'What does the at-least-once delivery guarantee imply for an idempotent consumer?', 'Retries are safe because the consumer can recognise and skip duplicate effects', 'Duplicates always corrupt state', 'Retries are impossible', 'Only once semantics cannot be built', 'A', 'With at-least-once delivery, duplicates can occur, and idempotent processing makes those duplicates harmless.', 'ADVANCED', 3, 'MCQ', 1),
(4321, 255, 'Which discipline focuses on extracting insights and patterns from data?', 'Data analytics', 'Pencraft', 'Cartography', 'Calligraphy', 'A', 'Data analytics applies statistical and computational techniques to discover patterns and support decisions.', 'BEGINNER', 1, 'MCQ', 1),
(4322, 255, 'Which analytics type looks backward to describe what already happened?', 'Descriptive analytics', 'Prescriptive analytics', 'Predictive analytics', 'Speculative analytics', 'A', 'Descriptive analytics summarises historical data with metrics and reports.', 'BEGINNER', 1, 'MCQ', 1),
(4323, 255, 'Which analytics type predicts future outcomes based on historical data?', 'Predictive analytics', 'Descriptive analytics', 'Random analytics', 'Diagnostic analytics', 'A', 'Predictive analytics builds models that forecast future values or events from past data.', 'BEGINNER', 1, 'MCQ', 1),
(4324, 255, 'Which analytics type recommends specific actions to take?', 'Prescriptive analytics', 'Descriptive analytics', 'Reactive analytics', 'Manual analytics', 'A', 'Prescriptive analytics suggests the best course of action using optimisation and simulation.', 'BEGINNER', 1, 'MCQ', 1),
(4325, 255, 'Which type of chart is best for showing how a quantity changes over time?', 'Line chart', 'Pie chart of a single value', 'Word cloud', 'Bar of categories only', 'A', 'Line charts connect ordered points to reveal trends and changes across time.', 'BEGINNER', 1, 'MCQ', 1),
(4326, 255, 'Which visualisation is best for comparing parts of a whole?', 'Pie chart', 'Scatter plot', 'Box plot', 'Heat map', 'A', 'Pie charts show each category''s share of the total, making part-to-whole comparison intuitive.', 'BEGINNER', 1, 'MCQ', 1),
(4327, 255, 'Which chart type plots two numeric variables to reveal correlation?', 'Scatter plot', 'Donut chart', 'Single number card', 'Timeline', 'A', 'Scatter plots place each observation by its two numeric coordinates, exposing relationships.', 'BEGINNER', 1, 'MCQ', 1),
(4328, 255, 'Which statistic measures the average of a dataset?', 'Mean', 'Mode of distribution', 'Median of error', 'Variance of samples', 'A', 'The mean sums all values and divides by the count, giving the central average.', 'BEGINNER', 1, 'MCQ', 1),
(4329, 255, 'Which statistic is the middle value when data is sorted?', 'Median', 'Mean', 'Range', 'Variance', 'A', 'The median is the central value, robust to outliers unlike the mean.', 'BEGINNER', 1, 'MCQ', 1),
(4330, 255, 'Which statistic measures how spread out values are around the mean?', 'Standard deviation', 'The mode', 'The median', 'The count', 'A', 'Standard deviation quantifies the dispersion of data points from their mean.', 'BEGINNER', 1, 'MCQ', 1),
(4331, 255, 'Which visualisation best reveals the distribution shape of a continuous variable?', 'Histogram', 'Pie chart', 'Single number', 'Logo', 'A', 'Histograms bin a continuous variable into ranges, showing shape, spread and skew.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4332, 255, 'Which chart is most useful for comparing a metric across many categories?', 'Bar chart', 'Scatter plot', 'Box plot of one series', 'Flow diagram', 'A', 'Bar charts compare category values clearly using lengths from a common baseline.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4333, 255, 'Which visualisation lets you spot outliers and quartiles of several groups at once?', 'Box plot', 'Pie chart', 'Histogram of one group', 'Word cloud', 'A', 'Box plots summarise medians, quartiles and outliers, making cross-group comparison easy.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4334, 255, 'Which analytics method would you use to answer ''why did sales drop last quarter?''', 'Diagnostic analytics with drill-down analysis', 'Predictive forecasting', 'Prescriptive optimisation', 'Random sampling', 'A', 'Diagnostic analytics investigates the causes of observed outcomes by drilling into dimensions and drivers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4335, 255, 'Which statistical correlation value indicates a strong negative linear relationship?', '-0.9', '0', '0.5', '1.5', 'A', 'A correlation near -1 indicates a strong negative linear relationship, so -0.9 fits best.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4336, 255, 'A scatter plot shows points scattered randomly with no trend. What correlation is implied?', 'Near zero', 'Near +1', 'Near -1', 'Exactly 100', 'A', 'Random scatter with no trend implies correlation close to zero.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4337, 255, 'Which kind of dashboard metric would alert an operations team to a current service outage?', 'A real-time latency or error-rate KPI', 'A quarterly revenue chart', 'A yearly headcount bar', 'A five-year forecast', 'A', 'Real-time operational KPIs such as error rates surface live incidents immediately.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4338, 255, 'Which analytics practice is most effective at handling a dataset with many correlated features?', 'Dimensionality reduction such as PCA before modelling', 'Ignoring all features', 'Plotting every pair manually', 'Using raw pixels as features', 'A', 'Principal component analysis condenses correlated features into fewer orthogonal components, reducing noise and cost.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4339, 255, 'Which technique divides customers into segments based on similar behaviour?', 'Clustering such as K-means', 'Linear regression', 'Descriptive reporting', 'Pivot tables', 'A', 'Clustering groups observations so members of a cluster are similar to each other and different from other clusters.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4340, 255, 'Which metric measures prediction error as the average of absolute differences?', 'Mean absolute error', 'Mode', 'R-squared', 'Variance', 'A', 'Mean absolute error averages the absolute differences between predictions and actual values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4341, 255, 'A regression model on time series data shows a strong correlation with a confounder. Which practice best protects the insight?', 'Controlling for known confounders and testing on held-out data', 'Plotting only two variables', 'Increasing the dashboard size', 'Removing time entirely', 'A', 'Controlling confounders and validating on unseen data separates genuine effects from spurious correlations.', 'ADVANCED', 3, 'MCQ', 1),
(4342, 255, 'Which visual encoding pitfall most commonly misleads readers on an area chart?', 'Starting the y-axis at a non-zero value that exaggerates small changes', 'Using a single colour', 'Adding grid lines', 'Labeling axes clearly', 'A', 'Truncated axes distort relative magnitude, making tiny differences look dramatic.', 'ADVANCED', 3, 'MCQ', 1),
(4343, 255, 'Why are correlation and causation frequently conflated in business dashboards?', 'Co-occurrence alone cannot prove that one variable causes another', 'Correlation always implies causation', 'Causation is impossible to measure', 'Dashboards cannot show correlation', 'A', 'Two metrics may move together without one causing the other, so analysts must test causality with experiments or domain knowledge.', 'ADVANCED', 3, 'MCQ', 1),
(4344, 255, 'Which statistical concern most affects a recommender system trained on the popular subset of users only?', 'Selection bias making the model unrepresentative of all users', 'Too much data', 'The chart type', 'The number of colours used', 'A', 'Training on an unrepresentative, self-selected sample biases predictions for the broader population.', 'ADVANCED', 3, 'MCQ', 1),
(4345, 255, 'Which evaluation approach best measures how a model generalises to truly new data?', 'Evaluating on a held-out test set or via cross-validation', 'Testing on the training data', 'Reading the loss of zero', 'Reviewing only the training accuracy', 'A', 'Held-out or cross-validated evaluation estimates performance on data the model never saw during training.', 'ADVANCED', 3, 'MCQ', 1),
(4346, 255, 'Which strategy prevents a K-means clustering result from being determined solely by arbitrary initial centres?', 'Running K-means several times with different seeds and picking the best inertia', 'Fixing one random seed forever', 'Using cluster size only', 'Plotting the data once', 'A', 'K-means is sensitive to initialisation, so multiple runs with different seeds and best-inertia selection stabilise results.', 'ADVANCED', 3, 'MCQ', 1),
(4347, 255, 'Which dashboard design principle best prevents analysts from drawing wrong conclusions about trends?', 'Consistent axes, clear scales and a fixed period for comparison', 'Rotating chart colours randomly', 'Removing all labels', 'Shrinking every chart', 'A', 'Consistent, honest scales and comparable periods keep visual comparisons valid and interpretations accurate.', 'ADVANCED', 3, 'MCQ', 1),
(4348, 255, 'Which practice best ensures analytics findings are reproducible in a regulated industry?', 'Version-controlled pipelines, data lineage and audit trails', 'Running analyses once manually', 'Deleting old data', 'Keeping results only in a chat', 'A', 'Reproducibility requires tracked code, documented data lineage and auditable records of transformations.', 'ADVANCED', 3, 'MCQ', 1),
(4349, 255, 'An analyst reports a model accuracy of 99% on a rare-disease dataset with 1% positive cases. What is the biggest flaw?', 'The metric is misleading because a naive classifier predicting all negatives also scores 99%', 'The accuracy is too low', 'There is too much data', 'The report is too long', 'A', 'On imbalanced data, raw accuracy hides that a trivial majority-class predictor performs equally well; precision and recall matter more.', 'ADVANCED', 3, 'MCQ', 1),
(4350, 255, 'Which approach is most appropriate when data from different sources use inconsistent units and scales?', 'Standardising and normalising fields before modelling', 'Plotting the raw numbers unchanged', 'Multiplying all values by random factors', 'Ignoring units entirely', 'A', 'Normalisation brings disparate scales onto a common footing, preventing dominant-magnitude features from biasing models.', 'ADVANCED', 3, 'MCQ', 1),
(4351, 271, 'What is an ensemble method?', 'Combining multiple models to improve predictions', 'Training a single model', 'Deleting models', 'Using one dataset', 'A', 'Ensembles aggregate multiple models for better performance.', 'BEGINNER', 1, 'MCQ', 1),
