(4353, 271, 'What is boosting?', 'Sequentially training models to correct previous errors', 'Training in parallel', 'Averaging all models', 'Deleting weak models', 'A', 'Boosting focuses on hard-to-classify examples.', 'BEGINNER', 1, 'MCQ', 1),
(4354, 271, 'What is a random forest?', 'An ensemble of decision trees', 'A single tree', 'A clustering method', 'A regression line', 'A', 'Random forests average many trees.', 'BEGINNER', 1, 'MCQ', 1),
(4355, 271, 'What is a weak learner?', 'A model only slightly better than random', 'A perfect model', 'A deep network', 'A database', 'A', 'Weak learners are simple models with modest accuracy.', 'BEGINNER', 1, 'MCQ', 1),
(4356, 271, 'What is voting in ensemble learning?', 'Combining model predictions by majority or average', 'Training one model', 'Deleting models', 'Selecting one model', 'A', 'Voting aggregates the decisions of many models.', 'BEGINNER', 1, 'MCQ', 1),
(4357, 271, 'What is a base learner?', 'An individual model in an ensemble', 'The final ensemble', 'A dataset', 'A label', 'A', 'Base learners are the components of an ensemble.', 'BEGINNER', 1, 'MCQ', 1),
(4358, 271, 'What does random forest randomize?', 'Data samples and feature subsets for each tree', 'Labels', 'Final predictions', 'Data sizes', 'A', 'Randomness decorrelates the trees.', 'BEGINNER', 1, 'MCQ', 1),
(4359, 271, 'What is AdaBoost?', 'A boosting algorithm that reweights misclassified examples', 'A clustering method', 'A regression', 'A single tree', 'A', 'AdaBoost emphasizes examples previous models got wrong.', 'BEGINNER', 1, 'MCQ', 1),
(4360, 271, 'What is the main goal of ensembling?', 'Improving accuracy and robustness', 'Reducing data', 'Speeding training', 'Deleting features', 'A', 'Ensembles generally outperform single models.', 'BEGINNER', 1, 'MCQ', 1),
(4361, 271, 'Which ensemble reduces variance by averaging trees?', 'Random forest (bagging)', 'AdaBoost', 'XGBoost only', 'Stacking', 'A', 'Random forests average many trees to lower variance.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4362, 271, 'Which ensemble reduces bias by correcting errors?', 'Boosting', 'Bagging', 'Random forest', 'Voting', 'A', 'Boosting iteratively fixes previous mistakes.', 'INTERMEDIATE', 2, 'MCQ', 1),
