(4401, 272, 'What is the vanishing gradient problem?', 'Gradients become tiny in deep networks, slowing learning', 'Gradients explode', 'Data is missing', 'Weights vanish', 'A', 'Small gradients in early layers hinder training.', 'ADVANCED', 3, 'MCQ', 1),
(4402, 272, 'What is the exploding gradient problem?', 'Gradients grow very large, destabilizing training', 'Gradients disappear', 'Weights are fixed', 'Data is lost', 'A', 'Large gradients can cause unstable weight updates.', 'ADVANCED', 3, 'MCQ', 1),
